--======================================================================================================================================
-- Language_ko_KR
--======================================================================================================================================
INSERT OR REPLACE INTO Language_ko_KR (Tag, Text)
SELECT 'TXT_KEY_CITYSTATE_KEMZHIKET', 			'켐지켓' UNION ALL -- replaces Clermont
SELECT 'TXT_KEY_CITYSTATE_KEMZHIKET_ADJ', 			'예니세이 키르기스의' UNION ALL
SELECT 'TXT_KEY_CIV5_KEMZHIKET_TEXT', 				'예니세이 키르기스인은 시베리아 남부(현대 투바 및 하카시아)의 예니세이강 상류 지역에 거주했던 고대 튀르크계 민족으로, 서기 6세기에서 13세기 사이에 중앙아시아 역사에서 중요한 역할을 했습니다. 당나라 시대 중국 연대기에 처음 언급된 그들은 유목 목축 생활 방식, 숙련된 승마술, 고대 튀르크 문자로 쓰인 독특한 룬 문자로 유명했습니다. 9세기에 지도자 아조 칸의 지휘 아래 예니세이 키르기스인은 위구르 카간국을 전복하고(서기 840년) 몽골과 시베리아 일부에 걸친 강력한 카간국을 세워 명성을 얻었습니다. 13세기 몽골 제국의 확장으로 영향력이 약해졌지만, 예니세이 키르기스인은 중앙아시아 현대 키르기스인의 조상으로 간주됩니다. 그들의 유산은 초기 튀르크 초원 문명과 후기 키르기스 국가 형성을 잇는 언어적, 문화적, 역사적 전통으로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONDURAS', 			'테구시갈파' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONDURAS_ADJ', 			'온두라스의' UNION ALL
SELECT 'TXT_KEY_CIV5_HONDURAS_TEXT', 				'과테말라, 엘살바도르, 니카라과 사이의 중앙아메리카에 위치하며 카리브해와 태평양 모두에 해안선이 있는 온두라스는 원주민 문명, 식민지화, 현대 국가 건설에 의해 형성된 풍부하고 복잡한 역사를 가지고 있습니다. 유럽인과 접촉하기 전에는 코판 유적지가 주요 고고학적, 문화적 보물로 남아 있는 마야와 같은 선진 문화의 본거지였습니다. 스페인 탐험가 크리스토퍼 콜럼버스는 1502년 해안에 상륙했고, 1524년까지 이 지역은 스페인 제국에 완전히 편입되어 광업 및 식민지 행정의 중심지가 되었습니다. 1821년 스페인으로부터 독립한 후 온두라스는 단명한 중앙아메리카 연방 공화국에 가입했다가 나중에 분리되어 1838년 공화국으로 수립되었습니다. 20세기에는 정치적 불안정, 외국 기업의 영향력, 특히 미국 바나나 회사의 영향력, 군사 통치 기간을 겪었습니다. 오늘날 온두라스는 활기찬 문화적 전통, 자연의 아름다움, 다양한 원주민 및 아프로-카리브 유산을 보존하면서 사회적, 경제적 문제를 해결하기 위한 지속적인 노력으로 특징지어지는 민주주의 국가입니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PARIHAKA', 			'파리하카' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PARIHAKA_ADJ', 			'마오리의' UNION ALL
SELECT 'TXT_KEY_CIV5_PARIHAKA_TEXT', 				'마오리족은 아오테아로아(뉴질랜드)의 원주민 폴리네시아인으로, 조상들은 13세기경 동부 폴리네시아에서 카누 항해를 통해 도착하여 땅, 바다, 조상(와카파파)과의 영적 연결에 깊이 뿌리를 둔 풍부한 문화를 발전시켰습니다. 수 세기 동안 그들은 뚜렷한 부족 그룹(이위)과 하위 부족(하푸)을 형성하여 복잡한 사회 시스템, 요새화된 마을(파), 조각, 문신(타 모코), 구전 스토리텔링 전통을 구축했습니다. 마오리 사회는 18세기 유럽인의 도착 이후 큰 변화를 겪었으며, 1840년 마오리 추장들과 영국 왕실 사이에 와이탕이 조약이 체결되면서 정점에 달했습니다. 이는 뉴질랜드 역사의 창립 문서이자 논쟁의 여지가 있는 문서입니다. 이후의 토지 상실, 갈등, 식민지화는 마오리 생활을 혼란에 빠뜨렸지만, 20세기와 21세기에는 강력한 문화적, 정치적 부흥이 있었습니다. 오늘날 마오리 정체성, 언어(테 레오 마오리), 관습(티캉가)은 뉴질랜드 국가적 성격의 중심이며 진화하는 이중 문화 사회를 계속 형성하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SARATOV', 			'사라토프' UNION ALL -- replaces Armagh
SELECT 'TXT_KEY_CITYSTATE_SARATOV_ADJ', 			'칼미크의' UNION ALL
SELECT 'TXT_KEY_CIV5_SARATOV_TEXT', 				'칼미크인은 17세기에 중앙아시아의 준가리아 지역에서 볼가강 하류 지역으로 이주하여 유럽에서 유일하게 전통적으로 불교를 믿는 인구가 된 몽골계 민족입니다. 오이라트 몽골의 후손인 그들은 1630년 코 오를룩 하에 칼미크 칸국을 세워 자치권을 유지하면서 러시아 차르에게 충성을 맹세했습니다. 그들의 사회는 유목 목축, 풍부한 구전 전통, 티베트 불교를 기반으로 했습니다. 18세기 후반 러시아 제국의 확장으로 독립이 축소되었고, 1771년 칼미크인의 상당 부분이 준가리아로 돌아가려고 시도했는데, 이는 "대귀환"으로 알려진 위험한 이주였으며 대부분이 사망했습니다. 남은 사람들은 러시아 제국에 흡수되었지만 뚜렷한 정체성을 유지했습니다. 소련 시대에 칼미크인은 제2차 세계 대전 중 대량 추방을 포함한 탄압에 직면했습니다. 오늘날 그들은 주로 러시아 남서부의 칼미키아 공화국에 거주하며 유럽 최서단의 불교 공동체로서 언어, 종교, 문화유산을 계속 부활시키고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUSCAT', 				'무스카트' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUSCAT_ADJ', 				'오만의' UNION ALL
SELECT 'TXT_KEY_CIV5_MUSCAT_TEXT', 					'무스카트를 흐르는 무역은 적어도 2천 년 동안 이 도시의 생명선이었습니다. 알하자르 산맥 기슭에 자리 잡은 이곳을 프톨레마이오스는 1세기에 이미 숨겨진 항구("Cryptus Portus")라고 불렀습니다. 불행히도 이 도시는 충분히 숨겨지지 않았습니다. 페르시아만 입구라는 최적의 위치 때문에 오랫동안 정복의 매력적인 표적이 되었습니다. [NEWLINE][NEWLINE]수 세기 동안 무스카트 항구에는 사산조, 아라비아(7세기에 이슬람으로 개종), 아바스, 셀주크, 페르시아 등 수많은 깃발이 휘날렸습니다. 16세기 초, 포르투갈 제독은 대포로 무역 관계를 열고자 했고 무스카트 대부분을 불태웠습니다. 도시는 재건되었고 1650년 오만인이 그들을 몰아내고 항구 도시를 되찾을 때까지 포르투갈의 지배하에 있었습니다.[NEWLINE][NEWLINE]무스카트는 오랫동안 오만 내륙 부족들과 갈등을 빚어왔으며, 가장 흔한 원인은 자치권 문제였습니다. 18세기 이러한 혼란기 속에 알 부 사이드 왕조가 일어났고, 현대까지 이어지고 있습니다. 오늘날 광범위하게 현대화된 무스카트는 오만의 수도이자 중요한 무역항으로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GRANADA', 			'그라나다' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GRANADA_ADJ', 			'무어의' UNION ALL
SELECT 'TXT_KEY_CIV5_GRANADA_TEXT', 				'8세기에 우마이야 칼리프조는 이베리아반도로 확산되어 서고트 히스파니아를 빠르게 정복했습니다. 현재 스페인 남부의 요새화된 정착지였던 그라나다도 침략에 휩쓸렸습니다. 훗날(정확히는 15세기 후반) 가톨릭 군주들에게 항복함으로써 안달루시아의 레콘키스타는 끝났지만, 750년 동안 그라나다는 무어인의 것이었습니다.[NEWLINE][NEWLINE]시에라 네바다 산맥 기슭에 위치한 그라나다는 저지대 평원에 위치하여 방어가 거의 불가능하다는 불운을 안고 있었습니다. 무어인 통치자들은 이를 빠르게 깨닫고 마을이 내려다보이는 방어하기 좋은 산기슭으로 권력의 중심을 옮겼습니다. 그들의 계획 중 일부는 알카사르 건설을 포함했고, 그중 하나는 훗날 아름다운 알람브라 궁전으로 개조되었습니다.[NEWLINE][NEWLINE]그라나다의 무어인 주인들은 수 세기에 걸쳐 바뀌었습니다. 알모하드 왕조가 알모라비드 왕조를 대체했고, 알모라비드 왕조는 우마이야 왕조의 잔재를 계승했습니다. 13세기 나스르 왕조가 가톨릭 카스티야 왕국과 동맹을 맺으면서 그라나다 토후국이 탄생했고 도시의 운명은 다시 바뀌었습니다. 사하라 이남 아프리카의 무역 중심지에 직접 접근할 수 있었던 덕분에 그라나다는 한동안 레콘키스타로부터 자유를 살 수 있었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NAN_MADOL', 			'난마돌' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NAN_MADOL_ADJ', 			'난마돌의' UNION ALL
SELECT 'TXT_KEY_CIV5_NAN_MADOL_TEXT', 				'난마돌은 미크로네시아 연방 폰페이섬 동쪽 해안에 위치한 고대 고고학 유적지로, 인공 섬을 분리하는 운하 네트워크로 인해 종종 "태평양의 베니스"라고 불립니다. 서기 12세기에서 16세기 사이에 사우델레우르 왕조에 의해 건설된 이곳은 섬의 의식 및 정치 중심지 역할을 했으며 왕실 구역, 사원, 무덤이 있었습니다. 이 유적지는 모르타르 없이 조심스럽게 쌓은 거대한 현무암 기둥이 있는 거석 건축으로 유명하며 정교한 공학 및 사회 조직을 반영합니다. 난마돌은 사우델레우르 통치자들의 폰페이 통제에 중심적인 역할을 했으며 종교적 권위와 정치적 권력을 모두 상징했습니다. 이 도시는 내부 불안과 사우델레우르 왕조의 붕괴로 인해 17세기 초에 쇠퇴했지만, 인상적인 폐허는 고대 미크로네시아 문명의 독창성과 문화적 복잡성에 대한 증거로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SEORABEOL', 			'서라벌' UNION ALL -- replaces Aberffraw
SELECT 'TXT_KEY_CITYSTATE_SEORABEOL_ADJ', 			'신라의' UNION ALL
SELECT 'TXT_KEY_CIV5_SEORABEOL_TEXT', 				'신라 왕국은 고대 한국의 삼국 중 하나로, 기원전 57년 한반도 남동부에 건국되어 서기 935년까지 지속되었습니다. 처음에는 작은 부족 국가였던 신라는 점차 왕실 혈통 아래 권력을 중앙 집중화하여 6세기에 불교를 받아들이고 예술, 건축, 학문의 번영하는 문화를 육성했습니다. 문무왕과 그의 전임자들 하에서 신라는 당나라와 동맹을 맺어 7세기에 라이벌인 백제와 고구려를 정복하고 서기 668년 통일 신라로 알려진 최초의 통일 한국 국가를 달성했습니다. 이 기간에는 불국사와 석굴암과 같은 불교 사원 건설을 포함하여 놀라운 문화적, 기술적 성취가 있었습니다. 그러나 내부 분쟁과 귀족 권력 투쟁으로 결국 왕국이 약화되어 935년 신흥 고려 왕조에 멸망했습니다. 신라의 유산은 한반도 통일과 문화 및 예술 발전의 황금기로 기억되는 한국 역사의 결정적인 장으로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUISCA', 				'수아목스' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUISCA_ADJ', 				'무이스카의' UNION ALL
SELECT 'TXT_KEY_CIV5_MUISCA_TEXT', 					'무이스카는 서기 600년에서 1600년경까지 현재 콜롬비아의 동부 안데스 고원, 주로 보고타와 툰하 지역에서 번성했던 선진 원주민 문명이었습니다. 잉카, 마야, 아즈텍과 함께 남미의 주요 콜럼버스 이전 문화 중 하나인 무이스카는 농업, 무역, 야금술을 기반으로 한 정교한 사회를 발전시켰으며 엘도라도 전설에 영감을 준 훌륭한 금세공품 생산에 탁월했습니다. 지파(바카타, 현대 보고타)와 자케(훈자, 현대 툰하)로 알려진 통치자들이 이끄는 느슨한 추장국 연합으로 조직된 무이스카는 수에(태양신)와 치아(달의 여신)와 같은 신 숭배를 중심으로 복잡한 사회, 종교, 정치 시스템을 유지했습니다. 곤살로 히메네스 데 케사다가 이끄는 스페인 정복자들은 1530년대에 무이스카를 정복하여 정치 구조를 붕괴시켰습니다. 식민지화에도 불구하고 무이스카 후손들은 언어, 전통, 정체성의 요소를 계속 보존하여 콜롬비아의 히스패닉 이전 유산에 대한 중요한 연결 고리를 유지하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NOGAI', 				'사라이-주크' UNION ALL -- replaces Sparta
SELECT 'TXT_KEY_CITYSTATE_NOGAI_ADJ', 				'노가이의' UNION ALL
SELECT 'TXT_KEY_CIV5_NOGAI_TEXT', 					'노가이 칸국은 1500년경부터 17세기 칼미크인에 의해 서쪽으로, 러시아인에 의해 남쪽으로 밀려날 때까지 폰토스-카스피해 초원을 점령했던 노가이인이 세운 연합체였습니다. 망구트라고 불리는 몽골 부족이 노가이 칸국의 핵심을 구성했습니다. [NEWLINE][NEWLINE]13세기에 주치를 통한 칭기즈 칸의 직계 후손인 킵차크 칸국의 지도자 노가이 칸은 수많은 튀르크 부족이 합류한 망구트 군대를 결성했습니다. 1세기 후 노가이인은 망구트 부계 기원과 주치 모계 기원을 가진 사령관 에디구가 이끌었고, 그는 노가이 왕조를 세웠습니다. [NEWLINE][NEWLINE]1557년 노가이 누르 알 딘 카지 미르자는 이스마엘 베그와 다투고 북코카서스 초원에 소 노가이 칸국을 세웠습니다. 카스피해 북쪽의 노가이인은 그 후 대 노가이 칸국이라고 불렸습니다. 17세기 초, 칸국은 칼미크인의 맹공격으로 더욱 무너졌습니다. [NEWLINE][NEWLINE]흑해 북쪽의 노가이인은 노가이 베이보다는 크림 칸국에 명목상 종속되었습니다. 그들은 부자크(다뉴브강에서 드네스트르강까지), 예디산(드네스트르강에서 부그강까지), 잠보일룩(부그강에서 크림반도까지), 예디쿨(크림반도 북쪽), 쿠반으로 나뉘었습니다. 특히 예디산은 별개의 그룹으로 다양한 위치에서 언급됩니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CHEVAK', 				'키나크' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CHEVAK_ADJ', 				'유픽의' UNION ALL
SELECT 'TXT_KEY_CIV5_CHEVAK_TEXT', 					'알래스카와 러시아 극동의 원주민인 유픽족은 북극 및 아북극 환경과 깊이 연결된 풍부한 역사를 가지고 있습니다. 더 큰 에스키모-알류트 그룹의 일부인 그들의 조상은 수천 년 동안 이 지역에 살면서 낚시, 해양 포유류 사냥, 채집과 같은 생계 활동을 중심으로 반유목 생활 방식을 발전시켰습니다. 그들은 정교한 도구, 카약, 전통적인 카스기크(공동 주택)로 유명합니다. 유픽 세계관은 구전 전통, 춤, 의식에 반영된 자연과의 조화로운 관계를 강조합니다. [NEWLINE]약 3,000년 전 유피트의 조상들은 서부 알래스카가 될 해안 지역에 정착했으며, 서기 1400년경 해안 강(특히 유콘강과 쿠스코크림강)을 따라 이주하여 결국 유콘강의 파이미우트와 쿠스코크림강의 크로우 빌리지(툴루카루그미우트)까지 상류로 도달했습니다. [NEWLINE]18세기와 19세기 유럽인과의 접촉은 기독교 도입, 새로운 무역 상품, 질병 및 문화적 혼란과 같은 도전을 포함하여 중대한 변화를 가져왔습니다. 이러한 영향에도 불구하고 유픽족은 언어, 전통, 지식의 많은 부분을 보존하여 오늘날 알래스카에서 가장 큰 원주민 그룹 중 하나로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANTO_DOMINGO', 		'산토도밍고' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANTO_DOMINGO_ADJ', 		'도미니카의' UNION ALL
SELECT 'TXT_KEY_CIV5_SANTO_DOMINGO_TEXT', 			'카리브해 히스파니올라섬의 동쪽 3분의 2를 차지하는 도미니카 공화국은 원주민, 유럽, 아프리카의 영향으로 형성된 복잡한 역사를 가지고 있습니다. 유럽인과 접촉하기 전, 이 섬은 조직화된 추장국에 살았던 타이노 사람들의 고향이었습니다. 크리스토퍼 콜럼버스는 1492년에 그곳에 상륙하여 1498년에 산토도밍고를 세웠는데, 이는 아메리카 대륙 최초의 영구적인 유럽 정착지이자 신대륙 스페인 초기 식민 제국의 중심지였습니다. 식민지는 스페인 확장의 중심지가 되었지만 나중에 스페인이 다른 곳으로 초점을 옮기면서 쇠퇴하여 서쪽 3분의 1(현재 아이티)에 대한 프랑스 통치를 포함하여 외세 점령 기간으로 이어졌습니다. 도미니카 공화국은 1844년 후안 파블로 두아르테 하에 아이티로부터 독립을 선언했고 나중에 스페인에 의한 잠시 합병과 여러 정치적 격변을 겪었습니다. 오늘날 이곳은 원주민, 아프리카, 스페인 유산을 혼합한 활기찬 문화, 음악, 경제로 알려진 민주주의 국가입니다. 공식적인 "왕국"은 아니었지만 역사적 진화는 카리브해에서 수 세기에 걸친 식민지 및 국가적 변화를 반영합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANAGUA', 			'마나과' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANAGUA_ADJ', 			'니카라과의' UNION ALL
SELECT 'TXT_KEY_CIV5_MANAGUA_TEXT', 				'중앙아메리카에서 가장 큰 국가인 니카라과는 북쪽으로 온두라스, 남쪽으로 코스타리카와 접해 있으며 태평양과 카리브해 모두에 해안선이 있습니다. 그 이름은 원주민 니카라오족과 물을 뜻하는 스페인어 "아구아"에서 유래했으며, 광대한 니카라과 호수를 포함한 많은 호수와 강을 반영합니다. 16세기 스페인 식민지화 이전에는 다양한 원주민 그룹이 거주했습니다. 1821년 스페인으로부터, 나중에 1838년 중앙아메리카 연방으로부터 독립한 후 니카라과는 오랜 기간의 정치적 불안정, 독재, 외세 개입, 특히 20세기 초 미국의 개입을 겪었습니다. 소모사 가문은 1936년부터 1979년 산디니스타 혁명으로 전복될 때까지 통치했으며, 사회주의 정부가 들어섰지만 나중에 1980년대에 미국의 지원을 받는 콘트라 전쟁에 직면했습니다. 그 이후로 니카라과는 명목상의 민주주의로 전환했지만, 최근 다니엘 오르테가 대통령 하에서 권위주의 증가, 반대 의견 탄압, 서방 국가와의 관계 긴장이 나타나고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ODENSO', 				'헬싱키' UNION ALL -- VP5 conflict
SELECT 'TXT_KEY_CITYSTATE_ODENSO_ADJ', 				'핀란드의' UNION ALL
SELECT 'TXT_KEY_CIV5_ODENSO_TEXT', 					'핀란드의 수도이자 가장 큰 도시인 헬싱키는 발트해를 마주한 핀란드만 북쪽 해안에 위치하고 있습니다. 1550년 스웨덴의 구스타프 1세 왕이 탈린에 대항하기 위한 무역소로 설립한 이곳은 19세기 초 핀란드가 러시아에 합병된 후 명성을 얻을 때까지 작은 마을로 남아 있었습니다. 1812년 러시아 제국은 통제력과 상트페테르부르크와의 근접성을 강화하기 위해 핀란드 수도를 투르쿠에서 헬싱키로 옮겼고, 건축가 카를 루드비그 엥겔 하에 급속한 성장과 신고전주의 도시 개발을 촉진했습니다. 1917년 핀란드가 러시아로부터 독립한 후 헬싱키는 새로운 공화국의 심장부가 되어 기능주의 건축, 디자인 유산, 높은 삶의 질로 알려진 현대적인 유럽 수도로 발전했습니다. 오늘날 헬싱키는 북유럽 전통과 혁신, 지속 가능성, 강력한 해양 문화를 혼합한 활기차고 미래 지향적인 도시입니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_YANGCHENG', 			'양성' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_YANGCHENG_ADJ', 			'하나라의' UNION ALL
SELECT 'TXT_KEY_CIV5_YANGCHENG_TEXT', 				'하나라의 첫 번째 수도로 여겨지는 이곳은 잉강 위에 지어졌으며 왕조가 멸망할 때까지 유지되었습니다. 전통적으로 중국 최초의 왕조로 여겨지는 하나라는 기원전 2070년에서 1600년경까지 통치하여 중국 문명의 시작을 알렸다고 합니다. 사마천의 사기와 같은 고대 문헌에 따르면, 황하의 홍수를 통제하고 세습 통치를 확립하여 권위를 얻은 전설적인 우왕에 의해 설립되었습니다. 하나라는 초기 형태의 청동 주조, 농업, 사회 조직을 발전시켜 후기 중국 왕조의 토대를 마련한 것으로 묘사됩니다. 그러나 그 시기의 확실한 기록이 없고 많은 증거가 후기 역사적 설명과 얼리터우 문화와의 가능한 고고학적 상관관계에서 도출되었기 때문에 하나라의 역사적 존재는 부분적으로 신화적이며 학자들 사이에서 논쟁의 여지가 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PHANOTEUS', 			'파노테우스' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PHANOTEUS_ADJ', 			'포키스의' UNION ALL
SELECT 'TXT_KEY_CIV5_PHANOTEUS_TEXT', 				'파노테우스(또는 파노테)는 에피루스 지역, 구체적으로 그리스 북서부 현대 지역 근처의 카오니아인 영토에 위치한 고대 그리스 도시였습니다. 에피루스와 테살리아 및 그리스 중부를 연결하는 중요한 경로를 따라 전략적으로 위치하여 군사적, 무역적 중요성을 모두 가졌습니다. 파노테우스에 대한 역사적 언급은 제한적이지만 폴리비오스와 리비우스와 같은 고전 작가들이 특히 헬레니즘 전쟁의 맥락에서 언급했습니다. 이 도시는 요새화되었으며 기원전 3세기와 2세기에 마케도니아인, 로마인, 에피루스인 간의 전쟁 중에 역할을 했습니다. 결국 많은 작은 에피루스 도시와 마찬가지로 파노테우스는 기원전 167년 로마의 에피루스 정복 이후 쇠퇴했으며, 당시 이 지역은 황폐화되었고 많은 정착지가 인구가 감소하거나 로마 속주 시스템에 흡수되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DOUALA', 				'두알라' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DOUALA_ADJ', 				'카메룬의' UNION ALL
SELECT 'TXT_KEY_CIV5_DOUALA_TEXT', 					'문화적, 지리적 다양성으로 인해 종종 "아프리카의 축소판"이라고 불리는 카메룬은 중앙아프리카에 위치하며 나이지리아, 차드, 중앙아프리카 공화국, 적도 기니, 가봉, 콩고 공화국과 국경을 접하고 대서양을 따라 해안선이 있습니다. 이 지역은 유럽인과 접촉하기 훨씬 전부터 차드호 근처의 사오 문명을 포함하여 다양한 왕국과 민족의 본거지였습니다. 포르투갈 탐험가들은 15세기에 도착하여 이 지역을 리오 도스 카마로에스("새우의 강")라고 명명했으며, 여기서 현대 이름이 유래했습니다. 19세기 후반 카메룬은 독일 식민지(카메룬)가 되었지만 제1차 세계 대전에서 독일이 패배한 후 국제 연맹 위임 통치하에 프랑스와 영국으로 분할되었습니다. 프랑스령 카메룬은 1960년에 독립했고, 영국령 남카메룬은 1961년에 독립하여 카메룬 연방 공화국을 형성했습니다. 그 이후로 이 나라는 주로 아흐마두 아히조와 폴 비야 두 대통령에 의해 통치되었으며, 일부 이웃 국가에 비해 비교적 안정적이지만 카메룬은 최근 몇 년 동안 정치적 긴장, 부패, 폭력적인 영어권 분리주의 갈등에 직면해 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ZAZZAU', 				'자자우' UNION ALL -- replaces Ambracia
SELECT 'TXT_KEY_CITYSTATE_ZAZZAU_ADJ', 				'자자우의' UNION ALL
SELECT 'TXT_KEY_CIV5_ZAZZAU_TEXT', 					'자리아라고도 알려진 자자우 왕국은 현재 나이지리아 북부에 있는 하우사 도시 국가 중 하나였으며 그 기원은 11세기로 거슬러 올라갑니다. 하우사족에 의해 설립된 자자우는 사하라 횡단 무역로의 전략적 위치 덕분에 이 지역의 무역, 농업, 문화의 주요 중심지가 되었습니다. 노예, 목화, 곡물 생산으로 유명했으며, 이는 북아프리카와 그 너머의 소금, 말, 사치품과 교환되었습니다. 이슬람교는 15세기에 자자우에 도입되어 통치자와 엘리트들이 종교를 받아들이고 통치와 교육에 통합하면서 정치 및 문화 생활에 지대한 영향을 미쳤습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DJIBOUTI', 			'지부티' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DJIBOUTI_ADJ', 			'지부티의' UNION ALL
SELECT 'TXT_KEY_CIV5_DJIBOUTI_TEXT', 				'아프리카의 뿔에 있는 작지만 전략적으로 중요한 국가인 지부티는 에리트레아, 에티오피아, 소말리아 사이에 있으며 홍해와 아덴만을 따라 해안선이 있습니다. 그 영토는 오랫동안 아프리카, 아라비아, 인도양을 연결하는 고대 무역 네트워크의 일부였던 아파르족과 소말리아(이사)족이 거주해 왔습니다. 이 지역은 9세기까지 아랍 상인들을 통해 이슬람의 영향을 받았습니다. 19세기 후반 프랑스는 통제권을 확립하여 1896년 프랑스령 소말릴란드 식민지를 만들었고 나중에 아파르 및 이사 프랑스 영토로 개명했습니다. 지부티는 1977년 하산 굴레드 압티돈을 초대 대통령으로 하여 프랑스로부터 독립했습니다. 그 이후로 이 나라는 현재 이스마일 오마르 겔레 대통령이 이끄는 엄격하게 통제되는 시스템 하에서 정치적으로 안정된 상태를 유지하고 있습니다. 경제적, 지정학적 중요성은 심해 항구와 홍해 입구에 위치하여 여러 외국 군사 기지를 유치하고 아프리카, 중동, 아시아 간의 무역 및 해운의 핵심 허브 역할을 하는 데서 비롯됩니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DODOMA', 				'다르에스살람' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DODOMA_ADJ', 				'탄자니아의' UNION ALL
SELECT 'TXT_KEY_CIV5_DODOMA_TEXT', 					'스와힐리 해안에 위치한 다르에스살람(아랍어: "평화의 집")은 탄자니아 최대 도시이자 예술, 패션, 미디어, 영화, 텔레비전, 금융의 가장 저명한 중심지입니다. 인구 600만 명이 넘는 다르에스살람은 동아프리카에서 가장 큰 도시이자 아프리카에서 여섯 번째로 큰 도시입니다.[NEWLINE][NEWLINE]다르에스살람은 1862년 잔지바르의 첫 술탄인 마지드 빈 사이드가 음지지마("건강한 마을"이라는 스와힐리어) 마을 부지에 건설했습니다. 1887년 독일 동아프리카 회사가 이곳에 기지를 건설할 때까지 작은 항구로만 남아 있었습니다. 1905년 이 도시는 중앙 철도의 기점이 되어 도시의 성장과 산업 발전을 촉진했습니다. 다르에스살람은 독일령 동아프리카(1891-1916), 탕가니카(1961-64), 탄자니아(1964-74)의 수도 역할을 했습니다. 1974년 도도마가 새 수도로 지정되었지만 공식적인 기능 이전은 1996년에야 완료되었습니다.[NEWLINE][NEWLINE]다르에스살람의 건물들은 종종 식민지 과거를 반영하며 스와힐리, 영국, 독일, 아시아 전통을 통합한 풍부한 건축 양식을 보여줍니다. 제2차 세계 대전 이후의 현대화와 확장은 병원 단지, 기술 연구소, 고등 법원을 포함한 현대적인 고층 건물을 가져왔습니다. 교육 시설로는 다르에스살람 대학교(1961), 여러 도서관 및 연구소, 국립 박물관이 있습니다.[NEWLINE][NEWLINE]다르에스살람의 자연적이고 거의 육지로 둘러싸인 항구는 탄자니아 본토의 농산물 및 광물 수출의 대부분을 담당하는 출구이며, 우간다, 르완다, 부룬디, 콩고 민주 공화국, 잠비아, 말라위 등 인근 내륙 국가들의 관문 역할도 합니다. 또한 철도로 연결되는 콩고강의 항해 가능한 지류인 루알라바강의 환적 항구이기도 합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_FAYA', 				'은자메나' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_FAYA_ADJ', 				'차드의' UNION ALL
SELECT 'TXT_KEY_CIV5_FAYA_TEXT', 					'차드는 북중부 아프리카의 내륙국으로 리비아, 수단, 중앙아프리카 공화국, 카메룬, 나이지리아, 니제르와 국경을 접하고 있습니다. 지리는 북쪽의 사막에서 남쪽의 건조한 사헬과 비옥한 사바나에 이르기까지 다양합니다. 이 지역은 수천 년 동안 사람이 거주해 왔으며 차드호 주변에서 사오족과 같은 고대 문명이 번성했습니다. 19세기 후반 프랑스는 이 지역을 식민지화하여 1900년 프랑스령 적도 아프리카의 일부로 만들었습니다. 차드는 1960년 8월 11일에 독립했지만 식민지 이후 역사는 정치적 불안정, 내전, 주로 무슬림인 북부와 기독교 또는 정령 숭배자인 남부 간의 민족 분열로 점철되었습니다. 이러한 어려움에도 불구하고 차드는 주로 석유 생산을 통해 정부와 경제를 점진적으로 강화하는 동시에 빈곤, 지역 갈등, 차드호의 환경 압력과 같은 지속적인 문제에 직면해 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KIGALI', 				'키갈리' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KIGALI_ADJ', 				'르완다의' UNION ALL
SELECT 'TXT_KEY_CIV5_KIGALI_TEXT', 					'키갈리는 르완다의 수도로 14세기 르완다 왕국에 의해 처음 개발되었으며, 현대에 이르러 역사적인 수도가 되었습니다. 동중부 아프리카의 작은 내륙국인 르완다는 무성한 산악 지형으로 인해 "천 개의 언덕의 땅"으로 알려져 있습니다. 역사적으로 트와, 후투, 투치족의 고향이었으며, 이들은 언어와 문화를 공유했지만 중앙 집중식 군주제 하에서 수 세기 동안 뚜렷한 사회적 역할을 발전시켰습니다. 19세기 후반 르완다는 독일령 동아프리카의 일부가 되었고 나중에 제1차 세계 대전 이후 벨기에가 관리하는 영토가 되었으며, 식민지 정책은 투치 소수 민족을 선호하여 민족 분열을 심화시켰습니다. 1962년 독립 후 후투와 투치 그룹 간의 긴장은 폭력의 순환으로 이어졌고, 1994년 대량 학살로 정점에 달했습니다. 당시 극단주의 후투 민병대는 불과 100일 만에 약 80만 명의 투치와 온건파 후투를 살해했습니다. 대량 학살은 폴 카가메가 이끄는 투치 주도의 르완다 애국전선(RPF)이 권력을 잡으면서 끝났습니다. 그 이후로 르완다는 놀라운 정치적 안정과 경제 성장을 달성하여 화해와 현대화를 추구했지만, 정부는 권위주의적 관행과 정치적 자유 제한에 대한 비판에 직면해 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LEVUKA', 				'레부카' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LEVUKA_ADJ', 				'피지의' UNION ALL
SELECT 'TXT_KEY_CIV5_LEVUKA_TEXT', 					'레부카는 남태평양 국가 피지의 오발라우섬 동해안에 있는 항구 도시이자 로마이비티주의 주도입니다. 1822년 미국 모험가가 정착한 이 지역은 미국 남북 전쟁(1861-65) 중 세계 목화 공급이 중단되었을 때 목화 붐의 중심지였습니다.[NEWLINE][NEWLINE]1871년 피지 최초의 근대 민족 국가인 피지 왕국이 건국되었을 때 세루 에페니사 카코바우가 레부카에서 왕으로 즉위했습니다. 1874년 피지가 영국의 식민지로 합병된 후 레부카는 1877년 행정부가 수바로 이전될 때까지 수도로 남아 있었지만, 공식적인 이전은 1882년에야 이루어졌습니다.[NEWLINE][NEWLINE]현재는 주로 일본, 한국, 대만 어선이 공급하는 피지 참치 가공 산업의 중심지입니다. 이 마을의 19세기 건축물은 여전히 대부분 온전하며, 2013년 레부카는 문화적, 역사적 가치를 인정받아 유네스코 세계문화유산으로 지정되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_QUELIMANE', 			'켈리만' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_QUELIMANE_ADJ', 			'스와힐리의' UNION ALL
SELECT 'TXT_KEY_CIV5_QUELIMANE_TEXT', 				'켈리만은 모잠비크 중부의 역사적인 항구 도시로 인도양의 리오 도스 본스 시나이스 하구 근처에 위치하고 있습니다. 16세기 초 포르투갈 상인과 선교사들에 의해 설립된 이곳은 동아프리카에서 가장 오래된 식민지 정착지 중 하나가 되었습니다. 원래 스와힐리-아랍 무역소였던 켈리만은 상아, 금, 나중에는 노예를 위한 포르투갈 무역 네트워크의 핵심 지점으로 성장하여 잠베지 계곡과 같은 내륙 지역으로 가는 관문 역할을 했습니다. 19세기와 20세기 초에는 비옥한 주변 땅의 농장과 연결되어 설탕, 코프라, 차 수출의 중심지로 발전했습니다. 포르투갈로부터의 모잠비크 독립 투쟁(1964-1975) 동안 켈리만은 정치적 불안의 장소였으며 독립 후 잠베지아주의 주도가 되었습니다. 오늘날 이 도시는 열대 기후, 맹그로브가 늘어선 수로, 자연 보호 구역 및 해변과의 근접성으로 알려진 중요한 지역 항구이자 상업 허브로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OYO', 				'오요' UNION ALL -- replaces Freetown
SELECT 'TXT_KEY_CITYSTATE_OYO_ADJ', 				'오요의' UNION ALL
SELECT 'TXT_KEY_CIV5_OYO_TEXT', 					'오요 제국은 서아프리카의 요루바 제국이었습니다. 현재 베냉 남부와 나이지리아 서부(남서부 지역과 북중부 지역의 서쪽 절반 포함)에 위치했습니다. 제국은 요루바 사람들의 조직적, 행정적 노력, 무역, 기병대의 군사적 사용을 통해 가장 큰 요루바어 사용 국가로 성장했습니다. 오요 제국은 17세기 중반부터 18세기 후반까지 서아프리카에서 가장 정치적으로 중요한 국가 중 하나였으며 요루바랜드의 다른 왕국 대부분뿐만 아니라 인근 아프리카 국가, 특히 서쪽의 현대 베냉 공화국에 있는 다호메이 폰 왕국을 지배했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DETTAH', 				'데타' UNION ALL -- replaces Brooklands
SELECT 'TXT_KEY_CITYSTATE_DETTAH_ADJ', 				'옐로나이프의' UNION ALL
SELECT 'TXT_KEY_CIV5_DETTAH_TEXT', 					'옐로나이프 또는 타차오티네는 캐나다 북부의 원주민으로, 전통적으로 현재 노스웨스트 준주에 있는 그레이트 슬레이브 호수 주변 지역에 거주했습니다. 그들의 이름은 역사적으로 그들이 제작하고 거래했던 독특한 노란색 구리 도구에서 유래했으며, 이는 야금술과 자원 사용에 대한 전문성을 강조합니다. 옐로나이프는 순록, 물고기 및 기타 지역 야생 동물에 의존하는 수렵 채집인으로 살았으며 사냥감을 쫓고 자원에 접근하기 위해 계절적 이동을 유지했습니다. 그들은 이웃 데네 그룹과 밀접하게 연결되어 언어와 문화적 관행을 공유하는 동시에 아북극 전역으로 확장된 무역 네트워크에 참여했습니다. 18세기와 19세기 유럽인과의 접촉, 특히 모피 무역을 통한 접촉은 질병과 전통적인 생활 방식의 변화를 포함하여 새로운 기회와 도전을 모두 가져왔습니다. 오늘날 옐로나이프는 언어, 문화적 전통, 토지 권리를 계속 보존하고 있으며 지역 거버넌스와 원주민 옹호에 적극적인 역할을 하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TAIWAN', 				'타이베이' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TAIWAN_ADJ', 				'대만의' UNION ALL
SELECT 'TXT_KEY_CIV5_TAIWAN_TEXT', 					'대만의 수도인 타이베이(공식적으로 중화민국)는 섬의 북부에 위치한 활기찬 대도시로 산으로 둘러싸여 있고 단수이강이 가로지르고 있습니다. 이곳은 대만의 정치, 경제, 문화 중심지 역할을 하며 상징적인 타이베이 101이 지배하는 현대적인 스카이라인, 번화한 야시장, 전통과 현대의 영향이 풍부하게 섞인 것으로 유명합니다. 역사적으로 이 지역은 청나라 통치하인 18세기에 한족 이민자들이 정착했으며 나중에 주요 행정 중심지가 되었습니다. 1895년 일본이 대만을 장악한 후 타이베이는 현대적인 인프라와 도시 계획으로 빠르게 발전했습니다. 제2차 세계 대전과 대만의 중국 통치 반환 이후, 국민당 정부가 중국 본토에서 후퇴한 후 1949년 타이베이는 중화민국의 수도가 되었습니다. 오늘날 타이베이는 민주주의, 기술 부문, 요리, 역동적인 문화생활로 유명한 세계적인 도시입니다. 주변 지역의 대부분은 여전히 여러 포르모사 원주민 그룹이 거주하고 있어 한족의 지배를 받는 중국 본토와는 구별되는 풍부한 문화적 구조를 만들고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OC_EO', 				'옥에오' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OC_EO_ADJ', 				'푸난의' UNION ALL
SELECT 'TXT_KEY_CIV5_OC_EO_TEXT', 					'푸난은 서기 1세기에 캄보디아에서 발생하여 6세기에 첸라 국가에 통합된 고대 국가입니다. 푸난(아마도 "산"을 뜻하는 프놈의 중국어 음차)은 동남아시아 최초의 중요한 힌두교 왕국이었습니다. 현재의 베트남, 태국, 캄보디아 일부를 포함했습니다. 푸난은 인도 및 중국과 무역 관계를 맺었으며, 3세기에서 6세기 사이에 중국 황제에게 조공을 바쳤습니다.[NEWLINE][NEWLINE]푸난은 3세기 왕 판시만(스레이 메아라라고도 함) 치하에서 권력의 정점에 도달했습니다. 판시만은 제국의 해군을 확장하고 푸난 관료제를 개선하여, 특히 제국의 먼 지역에서 지역 관습과 정체성을 대부분 온전하게 유지하는 준봉건적 패턴을 만들었습니다. 판시만과 그의 후계자들은 또한 해상 무역을 규제하기 위해 중국과 인도에 사절을 보냈습니다. 왕국은 동남아시아의 인도화 과정을 가속화했을 가능성이 큽니다. 첸라와 같은 후기 동남아시아 왕국들은 푸난 궁정을 모방했을 수 있습니다. 푸난인들은 이 지역 제국들의 패턴이 될 강력한 중상주의와 상업 독점 시스템을 구축했습니다.[NEWLINE][NEWLINE]푸난의 해상 무역 의존은 푸난 몰락의 시작 원인으로 간주됩니다. 그들의 해안 항구는 외국 지역과의 무역을 허용하여 상품을 북쪽과 해안 인구에게 전달했습니다. 그러나 해상 무역이 수마트라로 이동하고, 스리비자야 무역 제국이 부상하고, 중국이 동남아시아 전역의 무역로를 장악하면서 남부의 경제적 불안정이 초래되었고 정치와 경제가 북쪽으로 이동하게 되었습니다. 푸난은 6세기에 첸라 왕국의 크메르 정치체에 의해 대체되고 흡수되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_THIMPHU', 			'팀푸' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_THIMPHU_ADJ', 			'부탄의' UNION ALL
SELECT 'TXT_KEY_CIV5_THIMPHU_TEXT', 				'1955년부터 팀푸는 중국과 인도 사이의 히말라야 동부에 자리 잡은 작고 내륙에 위치한 왕국인 부탄의 수도로, 놀라운 산악 풍경과 풍부한 불교 문화로 유명합니다. 역사적으로 부탄은 17세기 샤브드룽 나왕 남걀의 지도하에 통일되었으며, 그는 종교적 권위와 시민적 권위를 결합한 이중 통치 시스템을 확립했습니다. 왕추크 왕조는 1907년에 집권하여 오늘날까지 이어지는 세습 군주제를 세웠습니다. 역사의 대부분 동안 부탄은 전통을 보존하기 위해 고립된 상태를 유지했으며 20세기 후반에야 점차 외부 세계에 개방되었습니다. 2008년 부탄은 입헌 군주제로 평화롭게 전환하고 첫 민주 선거를 치렀습니다. 이 나라는 현대화와 문화 보존 및 지속 가능한 성장의 균형을 맞추는 국민 총행복이라는 독특한 개발 철학으로 널리 존경받고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ANDORRA', 			'안도라' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ANDORRA_ADJ', 			'안도라의' UNION ALL
SELECT 'TXT_KEY_CIV5_ANDORRA_TEXT', 				'피레네산맥 남쪽 경사면에 위치한 안도라 공국은 발리라강을 형성하는 계곡들의 집합체로 구성되어 있습니다. 안도라의 독립은 전통적으로 서기 803년 이슬람교도들로부터 이 지역을 되찾은 샤를마뉴 대제 덕분이라고 합니다. 1278년 프랑스 푸아 백작과 스페인 우르젤 주교의 공동 주권하에 놓였으며, 이후 스페인 우르젤 주교와 프랑스 국가 원수가 공동으로 통치했습니다. 유럽의 마지막 봉건 통치 시스템인 이 제도는 1993년 보통 선거로 선출된 안도라 의회에 공동 영주의 권한 대부분을 이양하는 헌법이 채택될 때까지 계속되었습니다.[NEWLINE][NEWLINE]안도라는 오랫동안 카탈루냐와 강한 친밀감을 유지해 왔습니다. 제도는 카탈루냐 법에 기반을 두고 있으며 우르젤 교구(스페인)의 일부입니다.[NEWLINE][NEWLINE]전통 경제는 양 사육에 기반을 두었으나 1950년대 이후 관광업의 중요성이 커져 21세기 초에는 안도라 경제의 중심이 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CANOSSA', 			'카노사' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CANOSSA_ADJ', 			'토스카나의' UNION ALL
SELECT 'TXT_KEY_CIV5_CANOSSA_TEXT', 				'카노사는 이탈리아 북부 에밀리아로마냐 지역에 위치한 역사적인 성이자 마을로, 중세 유럽 역사에서 극적인 역할로 유명합니다. 940년경 아토니 가문의 창시자이자 카노사의 첫 번째 백작인 아토 아달베르트가 건설한 이곳은 당대 가장 강력한 통치자 중 한 명이었던 토스카나의 마틸다 백작 부인의 거주지가 되었습니다. 카노사는 1077년 서임권 투쟁 중에 신성 로마 제국 황제 하인리히 4세가 파문당한 후 교황 그레고리오 7세에게 용서를 구하기 위해 그곳을 여행했을 때 지속적인 명성을 얻었습니다. 전승에 따르면 하인리히는 사면을 받기 전에 3일 동안 눈 속에서 맨발로 서 있었다고 하며, 이는 중세 유럽에서 세속 권력과 교황 권력 사이의 투쟁을 보여주는 강력한 상징입니다. 성은 나중에 13세기에 파괴되었지만 그 폐허는 교회와 국가 관계의 이 중추적인 순간에 대한 지속적인 기념비로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BEDULU', 				'베둘루' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BEDULU_ADJ', 				'발리의' UNION ALL
SELECT 'TXT_KEY_CIV5_BEDULU_TEXT', 					'"천 개의 사원이 있는 섬"으로 알려진 발리와 그 역사는 문화와 종교에 깊이 빠져 있으며, 인도네시아 힌두교의 마지막 보루 중 하나입니다.[NEWLINE][NEWLINE]발리는 기원전 2000년경 원래 동남아시아와 오세아니아에서 해양 동남아시아를 통해 이주한 오스트로네시아인들이 거주했습니다.[NEWLINE][NEWLINE]문화적으로나 언어적으로 발리인은 인도네시아 군도, 말레이시아, 필리핀, 오세아니아 사람들과 밀접한 관련이 있습니다. 이 시기의 석기 도구는 섬 서쪽의 체킥 마을 근처에서 발견되었습니다. 896년과 911년의 비문에는 왕에 대한 언급이 없다가 914년에 스리 케사리바르마가 언급됩니다. 또한 불교와 시바교가 동시에 행해지는 독특한 방언을 가진 독립적인 발리를 보여줍니다.[NEWLINE][NEWLINE]음푸 신독의 증손녀 마헨드라다타는 989년경 발리 왕 우다야나 와르마데와와 결혼하여 1001년경 아이를랑가를 낳았습니다. 이 결혼은 또한 발리에 더 많은 힌두교와 자바 문화를 가져왔습니다. 사칼렌두키라나 공주는 1098년에 등장했습니다. 수라디파는 1115년부터 1119년까지, 자야사크티는 1146년부터 1150년까지 통치했습니다. 자야팡구스는 1178년에서 1181년 사이의 비문에 등장하며, 아디쿤티케타나와 그의 아들 파라메스바라는 1204년에 등장합니다.[NEWLINE][NEWLINE]발리 문화는 서기 1세기경부터 인도, 중국, 특히 힌두 문화의 영향을 강하게 받았습니다. 발리 드위파("발리 섬")라는 이름은 914년 스리 케사리 와르마데와가 쓴 블란종 기둥 비문을 포함한 다양한 비문에서 발견되었으며 왈리드위파를 언급합니다. 이 시기에 사람들은 습지 경작에서 쌀을 재배하기 위해 현지에서 수박(subak)이라고 불리는 복잡한 관개 시스템을 개발했습니다. 오늘날에도 행해지는 일부 종교 및 문화적 전통은 이 시기로 거슬러 올라갈 수 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DALI', 				'양쥐미에' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DALI_ADJ', 				'대리국의' UNION ALL
SELECT 'TXT_KEY_CIV5_DALI_TEXT', 					'"위대한 진리" 또는 "위대한 통치"를 의미하는 대리국은 10세기부터 13세기까지 거의 3세기 동안 동남아시아에서 중요한 역할을 했던 불교 왕국이었습니다. 이곳은 신심의 왕국이자 많은 사원과 거대한 석탑의 왕국이었으며, 단일 민족이 아니라 많은 민족과 부족으로 구성되었으며 그중 가장 큰 부족은 백족과 이족이었습니다.[NEWLINE][NEWLINE]대리국은 불교를 보존하고 전파하는 데 영향력을 미친 것으로 유명합니다. 왕실 단씨 가문은 이전의 남조 선조들처럼 독실한 불교도였으며, 대리 주변과 석보산에 거대한 불교 사원을 건설했습니다. 이곳은 곧 불교 교육의 중심지가 되었습니다. 이곳의 왕들은 인근 동남아시아 왕국들의 불교 신왕 모델을 본받으려 했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MULTAN', 				'물탄' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MULTAN_ADJ', 				'가즈나의' UNION ALL
SELECT 'TXT_KEY_CIV5_MULTAN_TEXT', 					'물탄은 파키스탄 펀자브주의 도시이자 물탄 지구의 주도입니다. 주의 남부에 위치하고 있으며 역사가 깊습니다. 인구는 380만 명이 넘으며(1998년 인구 조사 기준) 파키스탄에서 여섯 번째로 큰 도시입니다. 체나브강 바로 동쪽에 지어졌으며, 국토의 지리적 중심에 위치하고 카라치에서 약 966km 떨어져 있습니다.[NEWLINE][NEWLINE]물탄은 "피르와 성지의 도시"로 알려져 있으며 시장, 모스크, 훌륭하게 설계된 무덤이 있는 번영하는 도시입니다. 물탄 국제공항은 파키스탄의 주요 도시와 페르시아만의 도시로 항공편을 연결합니다. 도시의 산업에는 금속 가공, 제분, 설탕, 제유, 섬유 제조, 비료, 비누, 유리가 포함됩니다. 물탄은 또한 수공예품, 특히 도자기와 에나멜 작업으로 유명합니다.[NEWLINE][NEWLINE]아대륙에서 가장 오래된 도시 중 하나인 물탄은 이슬람 이전 시대의 성지인 태양신 사원의 우상에서 이름을 따왔습니다.[NEWLINE][NEWLINE]이 도시는 알렉산더 대왕에게 정복당했고(기원전 326년경), 중국 불교 학자 현장이 방문했으며(서기 641년), 아랍인들에게 점령당했고(8세기), 1005년 이슬람 튀르크 정복자 가즈나의 마흐무드와 1398년 티무르에게 점령당했습니다. 16세기와 17세기에 물탄은 무굴 황제의 통치하에 평화를 누렸습니다. 1818년 이 도시는 시크교 지도자 란지트 싱에게 점령당했습니다. 영국은 1848년부터 1947년 파키스탄이 독립할 때까지 이곳을 점령했습니다. 랜드마크로는 두 이슬람 성인의 14세기 무덤이 있는 오래된 요새가 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGAN', 				'파간' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGAN_ADJ', 				'버마의' UNION ALL
SELECT 'TXT_KEY_CIV5_BAGAN_TEXT', 					'이 왕국은 최근 남조 왕국에서 이라와디 계곡으로 들어온 므란마/버마인들이 파간(오늘날의 바간)에 세운 9세기의 작은 정착지에서 성장했습니다. 이후 200년 동안 작은 공국은 점차 주변 지역을 흡수하여 성장하다가 1050년대와 1060년대에 아나우라타 왕이 파간 제국을 건국하여 처음으로 이라와디 계곡과 그 주변부를 하나의 정치체로 통일했습니다. 12세기 후반 아나우라타의 후계자들은 남쪽으로는 말레이반도 상부, 동쪽으로는 적어도 살윈강, 북쪽으로는 현재 중국 국경 아래, 서쪽으로는 아라칸 북부와 친 구릉지대까지 영향력을 확장했습니다. 12세기와 13세기에 파간은 크메르 제국과 함께 동남아시아 본토의 두 주요 제국 중 하나였습니다. 1280년대까지 면세 종교 재산의 지속적인 증가가 왕실의 신하와 군인들의 충성심을 유지하는 능력에 심각한 영향을 미치면서 왕국은 13세기 중반 쇠퇴하기 시작했습니다. 이는 아라칸인, 몬족, 몽골인, 샨족의 내부 혼란과 외부 도전의 악순환을 불러왔습니다. 반복된 몽골의 침략(1277-1301)으로 4세기 된 왕국은 1287년에 무너졌습니다. 붕괴 이후 250년 동안 정치적 분열이 이어져 16세기까지 지속되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_RISHIKESH', 			'리시케시' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_RISHIKESH_ADJ', 			'가르왈의' UNION ALL
SELECT 'TXT_KEY_CIV5_RISHIKESH_TEXT', 				'"가르왈 히말라야의 관문"이자 "세계 요가의 수도"로 알려진 리시케시(Hrishikesh라고도 표기)는 인도 우타라칸드주 데라둔 지구의 데라둔 근처에 있는 도시입니다. 갠지스강 우안에 위치하고 있으며 힌두교 순례지로서 고대 현자와 성인들이 더 높은 지식을 찾아 명상하던 곳입니다. 강변을 따라 수많은 사원과 아슈람이 지어져 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUTITJULU', 			'무티줄루' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUTITJULU_ADJ', 			'아난구의' UNION ALL
SELECT 'TXT_KEY_CIV5_MUTITJULU_TEXT', 				'"아난구"는 서부 사막 언어를 사용하는 여러 호주 원주민 그룹을 설명하는 포괄적인 용어입니다. 이 용어는 피찬차차라족과 양쿤차차라족이 가장 두드러지게 사용합니다. 서부 사막 언어는 다른 어떤 원주민 언어보다 호주 영토의 더 많은 부분을 포괄하는 것으로 묘사되었습니다.[NEWLINE][NEWLINE]울룰루와 카타추타는 아난구 신앙 체계의 신성한 장소이며, 11개의 송라인이 그곳을 통과하거나 근처를 지나갑니다. 1979년 원주민 중앙 토지 위원회는 울룰루-카타추타 국립공원에 대한 소유권을 주장하기 위해 법적 투쟁을 시작했습니다. 1985년 결과적인 합의안이 시행되어 아난구에게 공원 관리 위원회의 과반수를 부여했지만 관광객의 공원 방문은 여전히 허용되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISKANWAYA', 			'이스칸와야' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISKANWAYA_ADJ', 			'칼라와야의' UNION ALL
SELECT 'TXT_KEY_CIV5_ISKANWAYA_TEXT', 				'이스칸와야는 볼리비아 라파스에서 북쪽으로 325km 떨어진 리카강 위 산등성이에 위치한 콜럼버스 이전의 신성한 장소입니다. 규모와 연대 면에서 이스칸와야는 페루의 마추픽추를 능가하지만 보존 상태는 좋지 않습니다. 이스칸와야 유적은 잉카 문명보다 앞선 몰로 문화로 거슬러 올라가며, 그 사람들은 기원전 800년경 또는 전성기인 1145년에서 1425년 사이에 건축물을 지은 것으로 추정됩니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TIWANAKU', 			'티와나쿠' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TIWANAKU_ADJ', 			'티와나쿠의' UNION ALL
SELECT 'TXT_KEY_CIV5_TIWANAKU_TEXT', 				'티와나쿠(스페인어: Tiahuanaco 및 Tiahuanacu)는 남아메리카 볼리비아 서부의 콜럼버스 이전 고고학 유적지입니다. 현재의 페루와 칠레까지 확장된 제국의 수도였으며 서기 300년부터 서기 1000년까지 번성했습니다. 티와나쿠는 안데스 학자들에게 잉카 제국 이전의 가장 중요한 문명 중 하나로 인정받고 있습니다. 약 500년 동안 주요 국가 권력의 의식 및 행정 수도였습니다. 고대 도시 국가의 유적은 라파스주 잉가비 지방 티와나쿠 자치구의 티티카카 호수 남동쪽 기슭 근처, 라파스에서 서쪽으로 약 72km(45마일) 떨어진 곳에 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DANO', 				'다노' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DANO_ADJ', 				'다가라의' UNION ALL
SELECT 'TXT_KEY_CIV5_DANO_TEXT', 					'다노는 부르키나파소 이오바주의 주도입니다. 직조와 도자기 시장이 있는 작은 마을이며, 식민지 기독교의 영향에도 불구하고 전통적인 우주론과 의식 관행을 지속해 온 다가라 사람들의 고향입니다. 이러한 관행에는 정령의 힘과 교감하고, 다른 세계의 존재를 불러내고, 개오지 조개껍데기로 점을 치는 것이 포함됩니다.[NEWLINE][NEWLINE]다가라 정착지는 부르키나파소 남서부의 약 3,500제곱킬로미터와 가나 북서부의 거의 같은 면적을 차지합니다. 다가라의 정치 및 사회 조직은 "텐간 시스템", 즉 다가라 공동체를 식별, 경계 설정 및 영적으로 보호하는 대지 성소 네트워크를 기반으로 합니다.[NEWLINE][NEWLINE]대지 성소는 희생 제사를 지내는 장소로, 주로 큰 나무 아래에 있는 돌로 구성되어 있으며, 규범에 따르면 해당 지역에 도착한 첫 번째 정착민이 세워야 합니다. 대지 성소에서는 여성과 토양의 비옥함, 특정 지역의 평화를 책임지는 대지의 신에게 제물을 바칩니다. 대지 성소에 대한 의식적 통제는 동시에 토지를 분배하고 필요한 희생 제물에 대한 기부를 요구할 권리를 의미합니다. 성소를 담당하는 제사장인 대지 사제는 나중에 온 정착민들에게 토지를 분배하고 다른 자원에 대한 접근을 규제하며, 때로는 상당히 많은 선물을 대가로 받기도 합니다. 늦게 온 사람들은 집을 짓고 죽은 자를 매장하기 위해서도 대지 사제의 허가를 받아야 합니다.[NEWLINE][NEWLINE]이 지역의 비중앙집권적 사회에서 텐간솝 또는 틴다나라고 불리는 대지 사제는 공동체 장로의 역할을 수행했으며, 식민지 이전 기간에는 유일한 지역 권위자였습니다. 전통에 따르면 대지 사제직은 정착지의 설립자나 같은 씨족 내의 후손에게 돌아갑니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARYES', 				'카리에스' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARYES_ADJ', 				'아토스의' UNION ALL
SELECT 'TXT_KEY_CIV5_KARYES_TEXT', 					'아토스산의 수도원 공동체는 그리스의 동방 정교회 수도사 공동체로, 자치 지역의 지위와 분권화된 행정, 지역 및 지방 자치 단체의 권한을 결합하여 아토스산이 포함된 아토스 반도의 말단 부분을 영토로 하고 있습니다. 반도의 인접한 기부 부분은 중앙 마케도니아의 일반 아리스토텔리스 공동체에 속합니다.[NEWLINE][NEWLINE]조직적인 수도원 생활은 963년 성 아타나시우스 아토니테가 첫 번째 수도원을 세우면서 시작되었습니다. 1400년까지 40개의 수도원이 있었습니다. 오랫동안 그리스 정교회의 성산으로 여겨졌던 이곳은 1927년 신정 공화국으로 선포되었습니다. 아토스 수도원들은 잘 보존된 유물, 희귀 서적, 고대 문서 및 엄청난 역사적 가치를 지닌 예술품 컬렉션을 소장하고 있으며, 아토스산은 1988년부터 세계문화유산으로 등재되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SGANG_GWAAY', 		'스강 과이' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SGANG_GWAAY_ADJ', 		'하이다의' UNION ALL
SELECT 'TXT_KEY_CIV5_SGANG_GWAAY_TEXT', 			'북미의 많은 원주민 부족 중 하이다족은 섬사람으로서 독특합니다. 틀링깃족 및 침시안족과 관련된 하이다 사회는 귀족, 평민, 노예의 계급으로 나뉜 씨족 시스템을 중심으로 조직되었습니다. 모계 혈통을 통해 결정되는 두 개의 주요 씨족이 있었습니다. 이 씨족들은 다시 혈통으로 세분화되었습니다.[NEWLINE][NEWLINE]하이다족은 특히 목공, 직조, 항해에 재능이 있습니다. 그들은 토템 폴을 처음 사용한 것으로 알려져 있습니다. 그들의 해양 활동은 식민지 개척자들과 많은 평화로운 무역로를 개척하게 했지만, 지역적으로는 노예제를 시행하는 두려운 전사들이었습니다. 이러한 이유로 그들은 종종 "북미의 바이킹"이라고 불렸습니다.[NEWLINE][NEWLINE]오늘날 하이다 과이 본섬의 하이다 보호구역은 하이다 국가 위원회를 만들기 위해 뭉쳤습니다. 그들은 문화적 부흥을 경험하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NYARYANA_MARQ', 		'냐르야나 마르크' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NYARYANA_MARQ_ADJ', 		'네네츠의' UNION ALL
SELECT 'TXT_KEY_CIV5_NYARYANA_MARQ_TEXT', 			'사모예드라고도 알려진 네네츠인은 러시아 북부 북극 지방의 원주민입니다. 2010년 최신 인구 조사에 따르면 러시아 연방에는 44,857명의 네네츠인이 있으며, 대부분 야말로-네네츠 자치구와 네네츠 자치구에 거주하고 있습니다. 그들은 툰드라 또는 숲 종류의 네네츠어를 사용합니다. 러시아어의 문자 그대로의 형태소 samo와 yed는 "자기 식인종"이라는 의미를 전달하여 경멸적으로 보입니다. 따라서 사모예드라는 이름은 20세기 들어 빠르게 사용되지 않게 되었고, 사람들은 "사람"을 의미하는 네네츠라는 이름을 사용합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ADEJE', 				'아데헤' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ADEJE_ADJ', 				'관체의' UNION ALL
SELECT 'TXT_KEY_CIV5_ADEJE_TEXT', 					'관체족은 북아프리카 해안에서 서쪽으로 약 100km(60마일) 떨어진 대서양 카나리아 제도의 원주민이었습니다. 그들은 17세기에 멸종된 관체어를 사용했는데, 이는 베르베르어와 관련이 있는 것으로 여겨집니다. 그들은 기원전 1천 년경에 군도에 도착했을 것으로 추정됩니다.[NEWLINE][NEWLINE]관체족은 유럽인이 도착하기 전에 마카로네시아 군도 지역에 살았던 것으로 알려진 유일한 원주민이었습니다. 다른 마카로네시아 군도(카보베르데 제도, 마데이라, 아조레스 제도)에 사람이 살았다는 인정된 증거는 없습니다. 15세기 초부터 시작된 스페인의 카나리아 정복 이후 많은 원주민이 스페인 정복자들에 의해 전멸했고 나머지는 시간이 지남에 따라 정착민 인구와 문화에 동화되었지만, 라고메라섬의 휘파람 언어인 실보와 카나리아 스페인어의 일부 어휘와 같이 카나리아 관습과 전통 내에 원래 문화의 요소가 남아 있습니다.[NEWLINE][NEWLINE]일부 학자들은 관체족과 문화의 파괴를 식민지 대량 학살의 초기 사례로 분류했습니다. 2017년 관체족의 첫 번째 게놈 전체 데이터는 북아프리카 기원을 확인했으며 인근 북아프리카 본토의 고대 북아프리카 베르베르인과 유전적으로 가장 유사하다는 것을 확인했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_WOOTEI_NIICIE', 		'우테이-니치에' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_WOOTEI_NIICIE_ADJ', 		'아라파호의' UNION ALL
SELECT 'TXT_KEY_CIV5_WOOTEI_NIICIE_TEXT', 			'약 3,000년 전, 아라파호어를 사용하는 조상인 헤테이노노에이노는 오늘날 캐나다 매니토바와 미국 미네소타로 분류되는 레드강 계곡을 따라 서부 오대호 지역에 살았습니다. 그곳에서 아라파호족은 옥수수를 포함한 작물을 재배하는 농경 민족이었습니다.[NEWLINE][NEWLINE]캐나다 동부의 유럽 식민지화 이후, 초기 샤이엔족인 히테시노와 함께 아라파호족은 오지브와족에 의해 서쪽 대평원으로 강제 이주당했습니다. 그들은 프랑스 무역 동맹국으로부터 총을 얻어 수가 많고 강력했습니다. 아라파호족의 조상은 1700년 이전에 서부 오대호 지역에서 대평원으로 들어왔습니다. 평원에서의 초기 역사 동안 아라파호족은 캐나다의 사우스 서스캐처원강에서 남쪽으로 몬타나, 와이오밍, 사우스다코타 서부에 이르는 북부 평원에 살았습니다.[NEWLINE][NEWLINE]아라파호족이 말을 얻기 전에는 개를 짐 싣는 동물로 사용하여 트라보아를 끌었습니다. 아라파호족은 1700년대 초 다른 부족으로부터 말을 얻었고, 이는 그들의 생활 방식을 바꾸어 놓았습니다. 그들은 말을 짐 싣는 동물과 타는 동물로 사용하는 유목민이 되었습니다. 그들은 더 많은 짐을 운반하고 말을 타고 더 쉽게 이동하여 더 쉽고 넓게 사냥할 수 있었고 평원에서의 사냥 성공률을 높였습니다. 점차 아라파호족은 더 남쪽으로 이동하여 밀접하게 동맹을 맺은 북부 및 남부 아라파호족으로 나뉘었고 몬타나 남부, 와이오밍 대부분, 네브래스카 팬핸들, 콜로라도 중부 및 동부, 오클라호마 서부, 캔자스 극서부의 땅에 걸친 넓은 공동 영토를 확립했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DAKKAR', 				'다카르' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DAKKAR_ADJ', 				'아달의' UNION ALL
SELECT 'TXT_KEY_CIV5_DAKKAR_TEXT', 					'다카르 또는 데케르라고도 알려진 다카르는 현재 에티오피아 동부에 위치한 역사적인 이슬람 도시였습니다. 1415년부터 1422년까지 통치한 사브르 아드 딘 3세가 15세기 초에 아달 술탄국(1415-1577)을 건국한 후 첫 번째 수도 역할을 했습니다. 아달 술탄국은 현재의 에티오피아 동부, 지부티, 소말리아 북부를 중심으로 아프리카의 뿔에서 번성했던 강력한 중세 이슬람 국가였습니다. 술탄국은 홍해와 인도양 무역에서 핵심적인 역할을 하여 아프리카와 아라비아, 아시아를 연결했습니다. 16세기 초 아흐마드 "그란"으로도 알려진 군사령관 아흐마드 이븐 이브라힘 알가지가 이끈 에티오피아 제국과의 치열한 갈등으로 가장 유명합니다. 그의 원정은 1543년 패배하고 사망하기 전까지 에티오피아 왕국을 거의 무너뜨릴 뻔했습니다. 술탄국은 결국 내부 및 외부의 압력으로 쇠퇴했지만, 이 지역의 정치, 문화, 종교적 지형에 지속적인 유산을 남겼습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONIARA', 			'호니아라' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HONIARA_ADJ', 			'솔로몬의' UNION ALL
SELECT 'TXT_KEY_CIV5_HONIARA_TEXT', 				'호니아라는 과달카날 북서쪽 해안에 위치한 솔로몬 제도의 수도이자 가장 큰 도시입니다. 이 지역은 제2차 세계 대전 중 연합군과 일본군 사이의 치열한 전투, 특히 과달카날 전역(1942-1943)의 현장으로 세계적인 주목을 받았습니다. 전쟁 후 호니아라는 더 나은 인프라와 전략적 위치 때문에 툴라기를 대신할 국가 수도로 선정되었습니다. 1952년 공식적으로 수도로 지정된 이 도시는 빠르게 발전하여 국가의 행정, 경제, 문화 중심지가 되었습니다. 오늘날 호니아라에는 정부 기관, 분주한 항구, 다양한 인구가 거주하고 있으며 기념비와 유물과 같은 전쟁의 잔재가 여전히 눈에 띄어 현대적 정체성을 중추적인 전시 과거와 연결합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARASJOHKA', 			'카라스요크' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARASJOHKA_ADJ', 			'사미의' UNION ALL
SELECT 'TXT_KEY_CIV5_KARASJOHKA_TEXT', 				'사미족은 노르웨이, 스웨덴, 핀란드 북부 지역과 러시아 콜라반도, 즉 사프미라고 알려진 문화 지역의 원주민입니다. 수천 년 전으로 거슬러 올라가는 역사를 가진 사미족은 전통적으로 반유목 순록 목축, 낚시, 사냥을 하며 북극 환경과 밀접한 관계를 유지하며 살았습니다. 그들의 문화는 구전 전통, 수공예품(두오지), 각티와 같은 독특한 의복이 풍부합니다. 19세기 이후 그들은 국가 정부의 동화 압력과 토지 권리 상실에 직면했습니다. 그러나 최근 수십 년 동안 사미 의회 설립과 권리 인정 강화로 강력한 문화적, 정치적 부흥이 있었습니다. 오늘날 사미족은 언어, 전통, 조상의 땅을 보존하면서 현대 생활과의 균형을 계속 유지하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KATENDE', 			'카텐데' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KATENDE_ADJ', 			'루바의' UNION ALL
SELECT 'TXT_KEY_CIV5_KATENDE_TEXT', 				'루바 왕국은 조공 시스템으로 주변 국가를 통치했습니다. 물로프웨("신성한 왕")는 제국의 전체 지도자였으며 대규모 귀족 궁정을 유지했습니다. 이 궁정에는 루바의 구전 역사를 보존하는 비밀 결사인 음부디예의 구성원이 포함되었습니다. 조공 국가는 발로프웨("씨족 왕")가 통치했으며 농업 및 광물 자원을 통해 중앙 정부에 조공을 바쳤습니다. [NEWLINE][NEWLINE]중앙아프리카에 위치한 덕분에 루바는 단거리 및 장거리 무역로의 중심이 되었습니다. 루바의 무역 네트워크는 소금과 구리와 같은 자원을 독점하고 콩고 북부 숲과 남쪽의 광물이 풍부한 "구리 벨트"를 연결할 수 있게 했습니다. 장거리 무역은 또한 루바가 대서양 및 인도양 무역 네트워크에 접근할 수 있게 하여 유리 구슬과 개오지 조개껍데기와 같은 사치품에 접근할 수 있게 했습니다. [NEWLINE][NEWLINE]예술가들도 루바에서 높은 평가를 받았습니다. 지팡이, 여인상 기둥 의자, 활 받침대를 포함한 예술품은 지위의 중요한 표시였습니다. 따라서 조각가는 매우 존경받았으며 직업을 나타내기 위해 자귀를 가지고 다녔습니다. 루바 예술의 가장 독특한 유형 중 하나는 구전 역사를 이야기하기 위한 기억술로 사용되는 장식된 나무 조각인 루카사 기억 판이었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LAHORE', 				'라호르' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LAHORE_ADJ', 				'펀자브의' UNION ALL
SELECT 'TXT_KEY_CIV5_LAHORE_TEXT', 					'파키스탄 펀자브주의 주도인 라호르는 천 년이 넘는 역사를 가진 남아시아에서 가장 오래되고 문화적으로 활기찬 도시 중 하나입니다. 종종 "파키스탄의 심장"이라고 불리는 라호르는 가즈나 왕조, 무굴 제국, 시크 제국, 영국을 포함한 다양한 제국 하에서 정치, 예술, 지적 허브였습니다. 16~18세기 무굴 시대에 화려하게 번성했으며, 현재 유네스코 세계문화유산인 바드샤히 모스크, 라호르 요새, 샬리마르 정원과 같은 웅장한 기념물로 장식되었습니다. 나중에 시크교 통치자 마하라자 란지트 싱과 영국 식민 행정 하에서 이 도시는 권력과 학문의 중심지로 계속 번성했습니다. 1947년 파키스탄 독립 이후 라호르는 국가 정체성과 회복력의 상징이 되었습니다. 오늘날 이곳은 풍부한 유산, 활기찬 예술, 요리, 사람들의 따뜻함으로 유명한 역동적인 대도시로, 역사와 현대적 에너지의 독특한 조화를 구현하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OUIDAH', 				'위다' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OUIDAH_ADJ', 				'위다의' UNION ALL
SELECT 'TXT_KEY_CIV5_OUIDAH_TEXT', 					'현재 베냉 해안에 위치한 위다 왕국은 17세기에 명성을 얻은 저명한 서아프리카 국가였습니다. 원래 작은 해안 정착지였던 이곳은 기니만에서의 전략적 위치 덕분에 무역, 외교, 문화 교류의 중요한 중심지가 되었습니다. 위다는 대서양 횡단 노예 무역에서의 역할로 알려져 있으며, 포르투갈, 네덜란드, 프랑스, 영국과 같은 유럽 열강이 무역소를 설립한 주요 허브 역할을 했습니다. 내륙에서 온 노예들은 위다로 끌려와 총기, 직물, 알코올을 포함한 유럽 상품과 교환되었습니다. 이 도시는 또한 유럽의 영향이 지역 폰 사람들의 부두 종교 관행과 섞이면서 문화의 용광로가 되었습니다. [NEWLINE][NEWLINE]18세기까지 위다의 번영은 1727년 위다를 합병한 다호메이 왕국을 포함한 이웃 강대국들의 관심을 끌었습니다. 다호메이의 통제하에 위다는 노예 무역에서 계속 중요한 역할을 했지만 다른 항구와의 경쟁과 19세기 대서양 횡단 노예 무역의 최종 폐지를 포함하여 점점 더 많은 도전에 직면했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PELYM', 				'펠림' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PELYM_ADJ', 				'페름의' UNION ALL
SELECT 'TXT_KEY_CIV5_PELYM_TEXT', 					'페름인은 핀-우그리아 민족의 한 분파이며 페름어를 사용하는 코미인과 우드무르트인을 포함합니다. 이전에는 비아르미아인이라는 이름도 이 민족들을 묘사하는 데 사용되었습니다. 그러나 러시아 북부 방언의 핀-우그리아 기층에 대한 최근 연구에 따르면 비아르말란드에는 페름인 외에도 다른 여러 핀-우그리아 그룹이 살았습니다. 페름인의 조상은 원래 카마강 중류와 상류를 덮고 있는 페르미아라고 불리는 땅에 거주했습니다. 페름인은 아마도 9세기에 두 그룹으로 나뉘었을 것입니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_POKROVKA', 			'약사르테스' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_POKROVKA_ADJ', 			'마사게타이의' UNION ALL
SELECT 'TXT_KEY_CIV5_POKROVKA_TEXT', 				'사카 티그라하우다 또는 오르토코리반티안으로도 알려진 마사게타이 또는 마사게타이인은 중앙아시아의 초원에 거주했던 고대 동부 이란계 사카 민족으로 더 넓은 스키타이 문화의 일부였습니다. 마사게타이는 기원전 8세기에서 7세기에 권력을 잡았으며, 스키타이인을 중앙아시아에서 쫓아내어 캅카스와 폰토스 초원으로 몰아냄으로써 광범위한 결과를 초래하는 일련의 사건을 시작했습니다. 마사게타이는 여왕 토미리스가 페르시아 아케메네스 제국의 창시자인 키루스를 패배시키고 죽였다는 주장으로 가장 유명합니다. [NEWLINE]마사게타이는 기원전 3세기 이후 쇠퇴했으며, 그 후 다른 부족들과 합쳐져 알란족을 형성했습니다. 알란족은 더 큰 사르마티아 부족 연합에 속한 민족으로, 캅카스와 유럽 초원으로 서쪽으로 이동하여 민족 대이동 시대의 사건에 참여했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SARNATH', 			'사르나트' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SARNATH_ADJ', 			'마우리아의' UNION ALL
SELECT 'TXT_KEY_CIV5_SARNATH_TEXT', 				'기원전 321년경 찬드라굽타 마우리아가 세운 마우리아 제국은 인도 아대륙 대부분을 통일한 최초의 주요 제국으로 고대 인도 역사의 결정적인 순간을 기록했습니다. 파탈리푸트라(현대 파트나)를 중심으로 한 이 제국은 찬드라굽타가 고문 차나키야(카우틸랴)의 지도를 받아 마가다의 난다 왕조를 전복시킨 후 등장했습니다. 찬드라굽타와 그의 후계자들, 특히 아소카 대왕 치하에서 마우리아 국가는 아프가니스탄에서 벵골까지, 그리고 데칸 깊숙한 곳까지 뻗어 있는 남아시아 거의 전체를 포함하도록 확장되었습니다. 제국은 고도로 조직화된 행정, 광범위한 도로 및 무역 네트워크, 경제 및 문화 통합 촉진으로 유명했습니다. 피비린내 나는 칼링가 전쟁 이후 아소카 황제의 불교 개종은 제국의 이데올로기를 변화시켰고, 도덕적 통치(다르마)를 장려하는 선교와 비문 지원을 통해 아시아 전역으로 불교가 확산되었습니다. 기원전 232년 아소카가 사망한 후 제국은 내부 분열과 지역 반란으로 점차 약화되어 결국 기원전 185년경 붕괴되었고 숭가 왕조와 같은 더 작은 후계 왕국이 들어설 길을 열었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SUCEAVA', 			'수체아바' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SUCEAVA_ADJ', 			'몰도바의' UNION ALL
SELECT 'TXT_KEY_CIV5_SUCEAVA_TEXT', 				'수체아바는 루마니아 북동부 부코비나 지역, 동부 카르파티아산맥 근처에 위치한 역사적인 도시입니다. 14세기 후반에 설립된 이곳은 1388년경부터 1565년까지 몰다비아 공국의 수도 역할을 했으며, 오스만 제국의 침략을 방어하기 위해 도시를 요새화하고 인상적인 수체아바 요새를 건설한 스테판 대제와 같은 통치자들 하에 있었습니다. 이 기간 동안 수체아바는 정치, 경제, 문화 중심지로 번성했으며 현재 유네스코 세계문화유산의 일부인 아름다운 수도원과 교회가 있습니다. 수도가 이아시로 옮겨진 후 수체아바의 중요성은 줄어들었지만 지역 허브로 남았습니다. 나중에 18세기에 합스부르크 통치하에 들어갔다가 1918년 루마니아와 재통일되었습니다. 오늘날 수체아바는 중세 유산, 종교 건축물, 부코비나의 채색된 수도원으로 가는 관문으로 유명합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TBILISI', 			'트빌리시' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TBILISI_ADJ', 			'조지아의' UNION ALL
SELECT 'TXT_KEY_CIV5_TBILISI_TEXT', 				'조지아 국가는 9세기에서 10세기에 바그라티오니 왕조 하에서 왕국으로 처음 통일되었으며, 고대 콜키스와 이베리아의 여러 전신 국가에서 발생했습니다. 조지아 왕국은 10세기에서 12세기에 번성했으며 1243년 몽골의 조지아 및 아르메니아 침공으로 무너졌고, 조지아의 게오르기 5세 하에서 잠시 재통일된 후 티무르 제국에 무너졌습니다. 1490년까지 조지아는 여러 개의 작은 왕국과 공국으로 분열되었으며, 근대 초기 내내 사파비 왕조와 오스만 제국의 지배에 맞서 자치권을 유지하기 위해 고군분투하다가 1801년 마침내 러시아 제국에 합병되었습니다. 1918-1921년 조지아 민주 공화국으로 잠시 독립을 시도한 후 조지아는 1922년부터 1936년까지 자캅카스 사회주의 연방 소비에트 공화국의 일부였으며, 그 후 소련이 해체될 때까지 조지아 소비에트 사회주의 공화국을 형성했습니다. 현재의 조지아 공화국은 1991년부터 독립했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANAA', 				'사나' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANAA_ADJ', 				'예멘의' UNION ALL
SELECT 'TXT_KEY_CIV5_SANAA_TEXT', 					'고대에 예멘은 현대 에티오피아와 에리트레아 일부를 포함하는 무역 국가인 사바인의 고향이었습니다. 나중에 서기 275년 힘야르 왕국은 유대교의 영향을 받았습니다. 기독교는 4세기에 도착했습니다. 이슬람교는 7세기에 빠르게 퍼졌고 예멘 군대는 초기 이슬람 정복에 결정적인 역할을 했습니다. 9세기에서 16세기에 라술 왕조와 같은 여러 왕조가 등장했습니다. 이 나라는 1800년대에 오스만 제국과 대영제국으로 나뉘었습니다. 자이디 무타와킬라이트 예멘 왕국은 제1차 세계 대전 이후 1962년 예멘 아랍 공화국이 수립되기 전에 설립되었습니다. 남예멘은 1967년 독립 국가가 되고 나중에 마르크스-레닌주의 국가가 될 때까지 아덴 보호령으로서 영국의 보호령으로 남아 있었습니다. 두 예멘 국가는 1990년에 통일되어 현대 예멘 공화국을 형성했습니다. 알리 압둘라 살레 대통령은 아랍의 봄 여파로 2012년 사임할 때까지 새 공화국의 초대 대통령이었습니다.' UNION ALL
