SELECT 'TXT_KEY_CIV5_AYUTTHAYA_TEXT', 				'아유타야는 1350년 라마티보디 1세 왕이 세 강이 합류하는 섬에 세운 태국 중부의 강력하고 번영한 왕국이었습니다. 중국, 인도, 말레이 군도 사이에 전략적으로 위치하여 무역, 외교, 문화의 번성하는 중심지가 되었으며 유럽, 일본, 페르시아 등지의 상인들을 끌어들였습니다. 전성기 아유타야는 웅장한 사원, 궁전, 국제적인 사회로 유명했으며 4세기 이상 시암의 수도 역할을 했습니다. 왕국은 이웃 문명의 영향을 혼합하면서 독특한 태국 정체성을 발전시켰고 지역에서 정치적 지배력을 유지했습니다. 그러나 1767년 아유타야는 버마 군대에 의해 파괴되어 붕괴되었고 문화유산의 많은 부분을 잃었습니다. 현재 유네스코 세계문화유산인 옛 도시의 폐허는 아유타야의 옛 영광과 태국 역사에서의 중심적 역할에 대한 증거로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PALMYRA', 			'팔미라' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PALMYRA_ADJ', 			'팔미라의' UNION ALL
SELECT 'TXT_KEY_CIV5_PALMYRA_TEXT', 				'타드무르, 타드모르 또는 투드무르라고도 불리는 팔미라는 다마스쿠스에서 북동쪽으로 210km 떨어진 시리아 중남부의 고대 도시입니다. "야자수의 도시"를 의미하는 팔미라라는 이름은 서기 1세기 로마 통치자들이 도시에 부여한 것입니다. 유적지의 셈족 이전 이름인 타드무르, 타드모르 또는 투드무르도 여전히 사용되고 있습니다. 이 도시는 기원전 19세기 초의 점토판에 언급되어 있습니다. 기원전 3세기에 이곳을 통과하는 도로가 동서 무역의 주요 경로 중 하나가 되면서 명성을 얻었습니다. 팔미라는 지중해(서쪽)와 유프라테스강(동쪽)의 거의 중간에 위치한 오아시스에 건설되었으며 로마 세계와 메소포타미아 및 동방을 연결하는 데 도움이 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AL_TIRABIN', 			'알티라빈' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AL_TIRABIN_ADJ', 			'베두인의' UNION ALL
SELECT 'TXT_KEY_CIV5_AL_TIRABIN_TEXT', 				'베두인은 아라비아반도의 사막에서 유래하여 북아프리카, 레반트 및 중동 일부 지역으로 퍼진 뿌리 깊은 문화, 목축 생활 방식, 강한 부족 정체성으로 알려진 전통적으로 유목하는 아랍 부족입니다. 역사적으로 그들은 낙타, 염소, 양을 치며 물과 목초지를 찾아 계절에 따라 이동하며 살았으며 사막 생존, 구전 시, 환대에 능숙해졌습니다. 그들의 사회 구조는 친족 관계, 명예, 부족에 대한 충성심을 중심으로 구축되었으며 족장은 셰이크라고 불립니다. 시간이 지남에 따라 20세기에 현대 국가가 확장되고 도시화가 증가함에 따라 많은 베두인이 마을에 정착하거나 반유목 생활을 채택했지만 의복, 시, 음악과 같은 전통의 요소는 아랍 문화유산과 정체성의 중요한 상징으로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HANUABADA', 			'하누아바다' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HANUABADA_ADJ', 			'모투의' UNION ALL
SELECT 'TXT_KEY_CIV5_HANUABADA_TEXT', 				'모투족은 파푸아뉴기니 남동부 출신으로, 이 나라의 수도이자 가장 큰 도시인 포트모르즈비 땅의 원주민이었습니다. 가장 큰 모투 정착지이자 그룹의 전통적인 중심지는 포트모르즈비 해안에서 그리 멀지 않은 하누아바다 마을입니다. 오늘날 이곳은 포트모르즈비에서 북서쪽으로 불과 몇 킬로미터 떨어져 있어 거의 포트모르즈비 자체의 일부입니다. 하누아바다라는 이름은 모투어에서 유래했으며 단순히 "큰 마을"을 의미합니다. 그들의 언어는 오스트로네시아어족이지만 오늘날 일부는 톡 피신이라는 영어 기반 피진어를 사용합니다. 모투족은 섬에 유럽인이 영구적으로 정착한 첫 번째 해안선에 살았기 때문에 다른 부족보다 더 잘 기록되어 있습니다. 그들은 또한 코코넛 섬유로 만든 게 발톱 모양의 돛이 달린 다동선 뗏목을 사용하여 근처의 다른 사람들과 무역하는 항해 전통을 가지고 있습니다. 모투족은 무역상이자 어부였기 때문에 내륙으로 멀리 이동하지 않고 주로 다리를 따라 거주했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BALKH', 				'박트라' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BALKH_ADJ', 				'박트리아의' UNION ALL
SELECT 'TXT_KEY_CIV5_BALKH_TEXT', 					'오늘날 아프가니스탄 북부의 발흐로 알려진 박트라는 세계에서 가장 오래된 도시 중 하나이며 중앙아시아 고대 문명의 주요 중심지였습니다. 실크로드를 따라 위치한 이곳은 고대 박트리아 지역의 수도 역할을 했으며 무역, 문화, 종교의 중심지로 번성했습니다. 기원전 2000년 이전에 세워진 것으로 추정되는 박트라는 아케메네스 페르시아의 지배를 받았고, 기원전 4세기 알렉산더 대왕에게 정복당했으며, 나중에 그리스-박트리아 왕국의 심장부가 되었습니다. 또한 조로아스터교와 나중에는 불교의 주요 중심지였으며, 아시아 전역의 영적 생활에 영향을 미친 수많은 수도원과 스투파가 있었습니다. 쿠샨 왕조에서 아랍인과 몽골인에 이르기까지 반복되는 침략에도 불구하고 박트라는 "도시들의 어머니"라는 명성을 유지하며 고대 이란과 중앙아시아 문명의 지속적인 유산을 상징합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TONDO', 				'톤도' UNION ALL -- replaces Donostia (Irunea)
SELECT 'TXT_KEY_CITYSTATE_TONDO_ADJ', 				'타갈로그의' UNION ALL
SELECT 'TXT_KEY_CIV5_TONDO_TEXT', 					'"강의 사람들"이라는 적절한 이름을 가진 강인하고 적응력 있는 타갈로그족은 필리핀에서 두 번째로 큰 민족 언어 그룹으로, 주로 마닐라와 인근 지방을 포함한 루손 중부에 거주합니다. 그들의 역사는 식민지 이전 시대로 거슬러 올라가며, 당시 그들은 강과 해안선을 따라 조직된 사회를 건설하고 농업, 어업, 무역에 의존했습니다. 타갈로그 공동체는 다투(추장)가 통치했으며 바랑가이라고 불리는 더 큰 정치체의 일부였습니다. 그들은 중국, 인도, 말레이 군도를 포함한 이웃 아시아 지역과 무역을 하여 힌두-불교 및 이슬람 문화 요소를 사회에 도입했습니다. 타갈로그어는 의사소통을 위한 중요한 매체로 발전했으며, 그들의 세계관을 반영하는 서사시, 노래, 속담의 풍부한 구전 전통을 가지고 있습니다. [NEWLINE][NEWLINE]16세기 스페인 식민지 개척자들이 도착하면서 타갈로그족은 서구의 영향을 가장 먼저 접한 그룹 중 하나였습니다. 스페인 사람들은 식민지 통치 및 경제 시스템과 함께 타갈로그 문화에 깊이 뿌리 박힌 기독교를 도입했습니다. 타갈로그 지역은 식민 통치에 대한 저항의 중심지가 되었으며 필리핀 혁명 기간 동안 안드레스 보니파시오와 아폴리나리오 마비니와 같은 혁명 지도자를 배출했습니다. 현대에 타갈로그족은 필리핀 정체성을 형성하는 데 중심적인 역할을 했으며, 그들의 언어는 국어인 필리핀어의 기초가 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_JETARKTE', 			'제타르크테' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_JETARKTE_ADJ', 			'카웨스카의' UNION ALL
SELECT 'TXT_KEY_CIV5_JETARKTE_TEXT', 				'카웨스카 사람들의 역사는 기껏해야 무심하게 손을 내미는 무정한 세상에서 전통을 지키기 위해 필사적으로 노력한 헛된 투쟁의 이야기입니다. 아메리카 탐험 초기부터 목격되었지만 20세기에 들어서야 완전히 접촉된 사람들입니다. 세상이 그들 주위로 움직이는 것을 보면서도 영구적인 무역을 확립할 만큼 관련성이 없으면서도 싸움을 걸 만큼 충분한 부를 소유하지도 않은 채 세상이 제공할 수 있는 가장 가혹한 환경 중 하나에서 살았던 사람들입니다. 전염병으로 인구가 급감하여 멸종의 길로 접어들었고 대지의 정령에 대한 믿음조차 잃게 만든 세상이었습니다. 그러나 여전히 극복하고 생존하여 오늘날까지 살아남은 사람들입니다. 카웨스카와의 초기 접촉은 마젤란과 신대륙 초기 탐험가 시대에 이루어졌지만, 이 영토는 20세기가 되어서야 백인에 의해 진정으로 식민지화되었습니다. 그때는 이미 전통적인 식량 자원의 남획과 면역력이 없는 질병으로 인해 인구가 급감한 상태였습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MBABANE', 			'음바바네' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MBABANE_ADJ', 			'에스와티니의' UNION ALL
SELECT 'TXT_KEY_CIV5_MBABANE_TEXT', 				'에스와티니(구 스와질란드)의 수도이자 가장 큰 도시인 음바바네는 음바바네강을 따라 북서부 고원 지대에 위치하고 있으며 아름다운 들랑게니 산맥과 음짐바 산맥으로 둘러싸여 있습니다. 1900년대 초 영국에 의해 식민지 행정 중심지로 설립된 이곳은 1902년 영국 보호령 스와질란드의 수도가 되었으며 1968년 독립 후에도 그 지위를 유지했습니다. 이 지역의 초기 거주자인 음바바네 쿠네네 추장의 이름을 딴 이 도시는 정부 기관과 무역로를 중심으로 성장하여 국가의 정치 및 상업 중심지로 발전했습니다. 오늘날 음바바네는 현대적인 도시 생활과 전통적인 스와지 문화를 조화시키고 에스와티니의 산악 풍경으로 가는 관문 역할을 하여 행정 중심지이자 문화 및 경제 활동의 중심지가 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TUNIS', 				'튀니스' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TUNIS_ADJ', 				'튀니지의' UNION ALL
SELECT 'TXT_KEY_CIV5_TUNIS_TEXT', 					'튀니지의 수도이자 가장 큰 도시인 튀니스는 카르타고의 고대 유적 근처 지중해 연안에 위치하고 있으며 국가의 정치, 경제, 문화 중심지 역할을 합니다. 그 역사는 적어도 기원전 9세기로 거슬러 올라가며, 베르베르 정착지로 시작하여 나중에 페니키아 카르타고, 로마 통치, 서기 7세기 이슬람 정복의 영향을 받았습니다. 아글라브 왕조와 이후 하프스 왕조 하에서 튀니스는 북아프리카의 주요 학문, 무역, 이슬람 문화 중심지로 부상했습니다. 이 도시는 오스만 제국과 프랑스 식민 통치하에서 더욱 번성하여 건축과 사회에 아랍, 지중해, 유럽의 영향을 혼합했습니다. 1956년 튀니지가 독립한 후 튀니스는 정부 소재지이자 국가 정체성의 상징이 되었습니다. 오늘날 유네스코 세계문화유산으로 지정된 번화한 메디나는 2천 년이 넘는 역사와 문화 교류의 살아있는 증거로 서 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MENDYARRUP', 			'멘댜룹' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MENDYARRUP_ADJ', 			'눙가르의' UNION ALL
SELECT 'TXT_KEY_CIV5_MENDYARRUP_TEXT', 				'눙가르족은 서호주 남서부 지역의 원주민으로, 그들의 조상 땅은 북쪽의 주리엔만에서 남동쪽의 에스페란스까지 뻗어 있으며 퍼스 주변 지역을 포함합니다. 45,000년이 넘는 역사를 가진 눙가르족은 환경과 법의 창조를 설명하는 드림타임 이야기에 따라 부자(땅)와 깊은 영적, 문화적 관계를 유지해 왔습니다. 전통적으로 눙가르 사회는 고유한 영토, 언어, 관습을 가진 상호 연결된 그룹으로 구성되었으며 생계를 위해 계절적 이동, 사냥, 채집에 의존했습니다. 1829년 영국의 식민지화 이후 눙가르족은 이주, 토지 상실, 문화 탄압에 직면했지만 언어, 전통, 정체성을 계속 보존하고 부활시켜 왔습니다. 오늘날 눙가르 사람들은 서호주 전역의 문화 교육, 환경 관리 및 화해 노력에서 중요한 역할을 하며 지구상에서 가장 오래된 지속적인 살아있는 문화 중 하나를 구현하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SADDARVAZEH', 		'사다르바제' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SADDARVAZEH_ADJ', 		'파르티아의' UNION ALL
SELECT 'TXT_KEY_CIV5_SADDARVAZEH_TEXT', 			'페르시아어와 그리스어로 각각 "백 개의 문이 있는 도시"를 의미하는 사다르바제 또는 헤카톰필로스는 현대의 담간 또는 샤루드 근처 이란 북동부에 위치한 고대 도시였습니다. 기원전 3세기경 아르사케스 왕조 치하의 파르티아 제국의 수도 역할을 했으며 메소포타미아와 중앙아시아를 연결하는 실크로드의 주요 정치 및 상업 중심지가 되었습니다. 원래 셀레우코스 왕조의 기반이었거나 파르티아인들이 재건한 더 오래된 헬레니즘 정착지였던 헤카톰필로스는 크테시폰과 같은 다른 파르티아 수도들에 의해 가려질 때까지 왕실 거주지이자 전략적 요새로 번성했습니다. 오늘날 도시의 유적은 거의 남아 있지 않지만(대부분 사르-에 쿠미스 유적지에서 확인됨), 스트라보와 플리니우스와 같은 고대 작가들은 그 웅장함과 동서양을 잇는 관문으로서의 위치를 찬양했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGHCASARAY', 		'바흐치사라이' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGHCASARAY_ADJ', 		'크림의' UNION ALL
SELECT 'TXT_KEY_CIV5_BAGHCASARAY_TEXT', 			'바흐치사라이(Baghchasaray 또는 Bakhchysarai라고도 표기)는 우크라이나 크림반도의 역사적인 도시로, 16세기부터 18세기까지 크림 칸국의 수도로 알려져 있습니다. 1532년경 사히브 1세 기라이가 설립한 이곳은 크림 타타르족의 정치, 문화, 영적 중심지가 되었습니다. 페르시아어(baghche-saray는 "정원 궁전"을 의미)에서 유래한 도시 이름은 정원과 산골짜기 사이의 그림 같은 배경을 반영합니다. 가장 유명한 랜드마크인 바흐치사라이 궁전(한사라이)은 크림 칸의 거주지 역할을 했으며 이슬람 건축, 복잡한 타일 작업, 알렉산드르 푸시킨이 1823년 시에서 불멸의 존재로 만든 "눈물의 샘"으로 유명합니다. 1783년 러시아의 크림반도 합병 이후 도시는 쇠퇴했지만 크림 타타르족의 유산과 회복력의 상징으로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CAVVANBAH', 			'카반바' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CAVVANBAH_ADJ', 			'분잘룽의' UNION ALL
SELECT 'TXT_KEY_CIV5_CAVVANBAH_TEXT', 				'분잘룽족은 뉴사우스웨일스 북부 해안과 내륙, 퀸즐랜드 남동부에 걸쳐 있는 전통적인 땅을 가진 호주 원주민으로, 바이런 베이, 리즈모어, 클래런스강과 리치먼드강 주변 지역을 포함합니다. 수만 년에 걸친 역사를 가진 분잘룽족은 땅과 수로에 얽힌 언어, 송라인, 의식 관행을 통해 표현되는 컨트리(ngalingah jugun)와의 깊은 연결을 중심으로 풍부한 문화생활을 발전시켰습니다. 전통적으로 그들은 숙련된 사냥꾼, 어부, 채집가로 살았으며 드림타임에 기반을 둔 복잡한 친족 시스템과 영적 신념을 가지고 있었습니다. 19세기 유럽 식민지화 이후 분잘룽족은 추방, 폭력, 문화적 전통의 붕괴를 겪었지만 언어와 유산을 계속 유지하고 부활시켜 왔습니다. 오늘날 분잘룽 사람들은 문화 보존, 토지 관리, 원주민 권리 옹호에서 중요한 역할을 하며 호주에서 가장 오래된 살아있는 문화 중 하나의 생존과 갱신을 보장합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BOGANIDA', 			'보가니다' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BOGANIDA_ADJ', 			'돌간의' UNION ALL
SELECT 'TXT_KEY_CIV5_BOGANIDA_TEXT', 				'돌간인은 시베리아 북부의 튀르크어 사용 원주민으로, 주로 러시아 크라스노야르스크 지방의 타이미르 반도에 거주합니다. 그들의 기원은 17세기와 18세기로 거슬러 올라가는데, 당시 에벤키족, 야쿠트족, 러시아 정착민 그룹이 북극 지역에서 섞여 독특한 문화적, 언어적 정체성을 형성했습니다. 전통적으로 돌간인은 반유목 순록 목축업자, 사냥꾼, 어부였으며 혹독한 툰드라 환경에 적응하고 북극의 계절적 리듬과 깊이 연결된 생활 방식을 발전시켰습니다. 그들은 야쿠트어(사하어)와 밀접한 관련이 있는 돌간어를 사용하며 풍부한 구전 전통, 민속, 샤머니즘 관행을 유지하고 있지만 많은 사람이 러시아 정교회도 믿습니다. 소련 시대에 집단화와 정착화는 돌간 사회를 변화시켜 공동체를 마을로 집중시키고 전통적인 생계를 방해했습니다. 이러한 압력에도 불구하고 돌간인은 문화유산의 많은 부분을 보존했으며 러시아 북극의 문화적, 생태적 구조에서 계속해서 중심적인 역할을 하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SIPIWININIWAK', 		'시피위니니와크' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SIPIWININIWAK_ADJ', 		'크리의' UNION ALL
SELECT 'TXT_KEY_CIV5_SIPIWININIWAK_TEXT', 			'크리족은 북미에서 가장 큰 원주민 그룹 중 하나로, 전통적인 영토는 앨버타와 서스캐처원의 아북극 숲에서 퀘벡과 온타리오의 제임스만과 허드슨만 해안에 이르기까지 캐나다의 광대한 지역에 걸쳐 있으며 미국 북부에도 관련 공동체가 있습니다. 허드슨만 지역 근처에서 기원한 것으로 여겨지는 크리족은 수 세기에 걸쳐 서쪽으로 확장하여 숲 거주자(네히야와크)와 평원 사냥꾼(파스콰위이니와크)으로서 다양한 환경에 적응했습니다. 알곤킨어족의 일부인 그들의 문화와 언어는 땅과 깊이 연결되어 있으며 자연에 대한 존중, 구전 스토리텔링, 공동체 친족 관계를 강조합니다. 크리족은 17세기 이후 모피 무역의 주요 참여자였으며 유럽 상인들과 광범위한 관계를 맺으면서도 자체적인 정치 및 영적 시스템을 유지했습니다. 식민지화, 조약, 기숙 학교의 영향에도 불구하고 크리족은 활기찬 공동체를 계속 유지하고 있으며 오늘날 캐나다 전역에서 원주민 거버넌스, 문화 활성화, 환경 관리에서 주도적인 역할을 하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ATOLAN', 				'아톨란' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ATOLAN_ADJ', 				'아미의' UNION ALL
SELECT 'TXT_KEY_CIV5_ATOLAN_TEXT', 					'팡카라고도 알려진 아미족은 대만에서 가장 큰 원주민 그룹으로, 전통적으로 화롄에서 타이둥까지 섬의 동부 해안 평원과 강 계곡에 거주합니다. 수천 년 전으로 거슬러 올라가는 역사를 가진 아미족은 오스트로네시아 문화 및 언어 가족의 일부이며 다른 태평양 섬 사람들과 깊은 조상적 유대를 공유합니다. 전통적으로 그들은 대가족과 연령 등급 시스템을 중심으로 조직된 모계 사회에서 살았으며, 쌀과 기장 농사와 같은 공동 의식과 농업 관행을 통해 남성과 여성의 역할이 명확하게 정의되었습니다. 그들의 풍부한 구전 전통, 음악, 춤, 특히 일리신 수확 축제는 자연 및 영적 세계와의 밀접한 관계를 반영합니다. 일본 식민지 시대(1895-1945)와 이후 중국 통치하에서 아미족은 동화 압력에 직면했지만 언어와 관습의 많은 부분을 보존했습니다. 오늘날 아미족은 대만의 원주민 문화 부흥의 최전선에 서서 토지 권리, 교육, 더 넓은 국가 정체성 내에서 유산 인정을 옹호하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISHIYAMA', 			'이시야마' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISHIYAMA_ADJ', 			'잇코잇키의' UNION ALL
SELECT 'TXT_KEY_CIV5_ISHIYAMA_TEXT', 				'잇코잇키는 15~16세기 일본에서 봉건 영주와 사무라이 통치에 대항하여 봉기한 불교 승려, 농민, 지역 무사들의 무장 집단이었습니다. 정토진종(진정한 정토) 종파의 가르침을 중심으로 그들은 종교적 헌신과 사회적 평등에 대한 열망으로 뭉쳤습니다. 혼란스러운 전국 시대에 등장한 이 연맹은 여러 지방에 자치 공동체를 설립했으며, 특히 오사카 근처의 이시야마 혼간지 요새 사원을 통제했습니다. 그들의 강력한 저항은 16세기 후반에 결국 운동을 진압한 오다 노부나가를 포함한 강력한 군벌들에게 도전했습니다. 비록 패배했지만 잇코잇키는 신앙과 정치적 저항을 결합하여 일본 역사상 가장 초기의 대규모 풀뿌리 운동 중 하나로 지속적인 유산을 남겼습니다.';

INSERT INTO Language_ko_KR (Tag, Text)
SELECT 'TXT_KEY_CITYSTATE_YAIUWA', 				'야이우와' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_YAIUWA_ADJ', 				'마네켄크의' UNION ALL
SELECT 'TXT_KEY_CIV5_YAIUWA_TEXT', 					'마네켄크라고도 알려진 하우시족은 오늘날 칠레와 아르헨티나가 공유하는 남미 남단의 큰 섬인 티에라델푸에고의 남동부에 거주했던 원주민이었습니다. 셀크남(오나)족과 밀접한 관련이 있는 하우시족은 주로 바다사자, 과나코, 새를 사냥하고 조개류와 야생 식물을 채집하며 혹독한 아한대 환경에 능숙하게 적응했습니다. 그들의 사회는 자연과 관련된 풍부한 영적, 의식적 삶을 가진 소규모 유목 그룹으로 조직되었습니다. 19세기 유럽 탐험가와 정착민의 도착, 뒤이어 양 목장과 금 채굴은 파괴적인 질병, 폭력, 이주를 가져와 20세기 초 하우시족을 거의 멸종시켰습니다. 오늘날 그들은 지구상에서 가장 도전적인 환경 중 하나에서 놀라운 회복력을 반영한 삶의 방식을 가진 세계 최남단 민족 중 하나로 기억됩니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SHAHRAZUR', 			'샤라주르' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SHAHRAZUR_ADJ', 			'고라니의' UNION ALL
SELECT 'TXT_KEY_CIV5_SHAHRAZUR_TEXT', 				'샤리조르 또는 샤라주르는 이라크 쿠르디스탄 지역의 일부로 술라이마니야주에 위치하며 아브로만 서쪽에 있습니다. 샤리조르는 디얄라강과 티그리스강으로 흐르는 탄자로강의 지류가 물을 공급하는 비옥한 평원입니다. 특히 2009년 이후 바크르 아와, 텔 베굼, 기르드-이 칼라크, 베스탄수르(유네스코 세계문화유산 잠정 목록에 등재됨)와 같은 유적지에서의 광범위한 고고학 연구는 이 평원이 선사 시대부터 지속적으로 점유되었음을 보여주었습니다. [NEWLINE]샤라주르는 11세기부터 16세기까지 아르달란 공국에 편입되었으며 첫 번째 수도였습니다. 아르달란은 14세기경부터 1865년 또는 1868년까지 이란 서부의 세습 쿠르드 봉신국이었으며 사난다지를 수도로 삼았습니다. 영토는 대략 현재 이란의 쿠르디스탄주에 해당하며 통치자들은 카자르 제국에 충성했습니다. 바반이 주요 라이벌이었습니다. 고라니는 문학 언어이자 링구아 프랑카였습니다. 봉신국이 무너지자 고라니 문학 작품은 중단되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CARARIES', 			'카라리에스' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_CARARIES_ADJ', 			'오마과의' UNION ALL
SELECT 'TXT_KEY_CIV5_CARARIES_TEXT', 				'오마과족(캄베바라고도 함)은 오늘날 브라질과 페루의 아마존 상류를 따라 살았던 투피어 사용자들이었습니다. 그들의 가장 중요한 유적지는 주로 솔리몽이스강과 이 지역의 다른 여러 강을 따라 있었습니다. 오마과족의 가장 독특한 문화적 특징 중 하나는 이마를 납작하게 만드는 관습이었습니다. 오마과 아기의 이마에 나무 조각을 묶어두어 이마가 납작한 모양으로 자라게 했습니다. 오마과족은 이 관습에 큰 자부심을 느꼈고 그렇게 하지 않는 대부분의 이웃 그룹을 미개하다고 여겼습니다. 그러나 외부 관찰자들에게 가장 즉각적으로 눈에 띄는 것은 오마과족이 짠 옷이었습니다. 많은 아마존 부족이 옷을 거의 입지 않거나 전혀 입지 않은 반면, 오마과족은 여러 가지 색의 면 직물을 입었는데, 이는 여러 스페인 원정대 지도자들로부터 찬사를 받은 특징이었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KITCISIPIRINIK', 		'키치시피리니크' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KITCISIPIRINIK_ADJ', 		'알곤킨의' UNION ALL
SELECT 'TXT_KEY_CIV5_KITCISIPIRINIK_TEXT', 			'알곤킨족은 현재 캐나다 퀘벡과 온타리오의 오타와강 계곡과 주변 지역에 전통적으로 거주하는 북미 원주민입니다. 그들은 북미 북동부 전역의 많은 부족을 포함하는 더 큰 알곤킨어족의 일부입니다. 역사적으로 알곤킨족은 반유목 무리로 살면서 사냥, 낚시, 채집에 의존했으며 이웃 원주민들과 광범위한 무역 네트워크를 유지했습니다. 그들은 17세기 프랑스 탐험가 및 정착민과의 초기 모피 무역에서 중요한 역할을 했으며 지역 역사를 형성하는 중요한 동맹을 맺었습니다. 그러나 유럽의 식민지화는 질병, 이주, 토지 상실을 포함한 중대한 혼란을 가져왔습니다. 이러한 어려움에도 불구하고 알곤킨 사람들은 문화유산, 언어, 전통의 많은 부분을 보존해 왔으며 오늘날 캐나다 내에서 권리, 토지 청구, 문화 활성화를 위해 계속 옹호하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KOKAND', 				'코칸트' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KOKAND_ADJ', 				'코칸트의' UNION ALL
SELECT 'TXT_KEY_CIV5_KOKAND_TEXT', 					'코칸트 마을은 우즈베키스탄에서 가장 오래된 마을 중 하나이며 페르가나 계곡 서부에 위치하고 있습니다. 10세기 연대기에는 후칸데, 하보칸데(마을의 옛 이름) 마을에 관한 최초의 기록 문서가 있습니다. 13세기에 대부분의 중앙아시아 마을과 마찬가지로 몽골인들이 도시를 파괴했습니다. 이 마을은 실크로드 무역의 중요한 허브입니다. [NEWLINE]코칸트는 적어도 10세기부터 카바칸드라는 이름으로 존재했으며 남아시아와 동아시아 사이의 대상 경로에 대한 여행자의 기록에 자주 언급되었습니다. 중국 한나라는 기원전 1세기에 도시 전체를 정복했습니다. 나중에 아랍인들이 당나라로부터 이 지역을 정복했습니다. 몽골인들은 13세기에 코칸트를 파괴했습니다. [NEWLINE]현재 도시는 1732년 에스키-쿠르간이라는 또 다른 오래된 요새 부지에 요새로 시작되었습니다. 1740년 우즈베크 왕국인 코칸트 칸국의 수도가 되었으며 서쪽으로는 키질로르다, 북동쪽으로는 비슈케크까지 뻗어 있었습니다. 코칸트는 또한 300개 이상의 모스크를 자랑하는 페르가나 계곡의 주요 종교 중심지였습니다. [NEWLINE]코칸트 칸국은 1709년 우즈베크 밍 부족의 샤이반 왕조 에미르 샤루흐가 부하라 칸국으로부터 독립을 선언하고 페르가나 계곡 동부에 국가를 수립하면서 설립되었습니다. 그는 작은 마을 코칸트에 수도로 성채를 건설하여 코칸트 칸국을 시작했습니다. 그의 아들 압둘 카림 베이와 손자 나르부타 베이는 성채를 확장했지만 둘 다 1774년에서 1798년 사이에 청나라에 보호국으로 복종하고 조공을 바쳐야 했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUTAWAYNATJI', 		'무타와이나지' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MUTAWAYNATJI_ADJ', 		'팔라와의' UNION ALL
SELECT 'TXT_KEY_CIV5_MUTAWAYNATJI_TEXT', 			'팔라와족은 본토 남쪽에 위치한 호주 태즈메이니아섬의 원주민입니다. 20세기 대부분 동안 태즈메이니아 원주민은 백인 정착민들에 의해 의도적으로 멸종된 멸종된 문화 및 민족 그룹으로 널리, 그리고 잘못 생각되었습니다. 태즈메이니아 원주민 혈통을 가진 사람들의 수에 대한 현대 수치(2016)는 이 정체성을 결정하는 데 사용되는 기준에 따라 6,000명에서 23,000명 이상까지 다양합니다.[NEWLINE][NEWLINE]약 40,000년 전 태즈메이니아(당시 호주의 반도)에 처음 도착한 태즈메이니아 원주민의 조상은 기원전 6000년경 해수면 상승으로 호주 본토와 단절되었습니다. 그들은 유럽인과 접촉할 때까지 8,000년 동안 외부 세계와 완전히 고립되었습니다.[NEWLINE][NEWLINE]1803년 영국의 태즈메이니아 식민지화 이전에는 약 3,000~15,000명의 팔라와족이 있었습니다. 팔라와 인구는 30년 이내에 급격히 감소하여 1835년에는 약 400명의 순수 혈통 태즈메이니아 원주민만이 살아남았고, 이들 중 대부분은 수용소에 감금되어 12년 이내에 47명을 제외하고 모두 사망했습니다. 원인에 대한 합의는 없으며 이에 대해 큰 논란이 일어났습니다. 전통적인 견해는 이러한 급격한 인구 붕괴가 정책의 결과라기보다는 유입된 질병의 영향 때문이라고 보았습니다. 헨리 레이놀즈와 같은 다른 사람들은 쇠퇴의 원인을 검은 전쟁에서의 손실 탓으로 돌립니다. 벤 키어넌, 콜린 타츠, 벤자민 매들리와 같은 많은 식민주의 및 대량 학살 역사학자들은 태즈메이니아 학살이 유엔 대량 학살 협약에서 채택된 라파엘 렘킨의 정의에 따라 대량 학살에 해당한다고 생각합니다. 완전한 태즈메이니아 원주민 언어는 사라졌습니다. 연구에 따르면 섬에서 사용되는 언어는 여러 별개의 어족에 속했습니다. 일부 원래 태즈메이니아 언어 단어는 퍼노 제도의 팔라와 사람들에게 남아 있으며 사용 가능한 단어 목록에서 팔라와 카니라는 언어를 재구성하려는 노력이 있습니다.' UNION ALL
