SELECT 'TXT_KEY_CITYSTATE_NGAZARGAMU_ADJ', 			'보르누의' UNION ALL
SELECT 'TXT_KEY_CIV5_NGAZARGAMU_TEXT', 				'카넴-보르누 제국은 오늘날의 차드와 나이지리아에 존재했던 제국이었습니다. 서기 9세기부터 아랍 지리학자들에게 카넴 제국으로 알려졌으며 1900년까지 독립된 보르누 왕국으로 지속되었습니다. 제국의 역사는 주로 1851년 독일 여행자 하인리히 바르트가 발견한 왕실 연대기 또는 기르감을 통해 알려져 있습니다. 전성기 카넴-보르누 제국은 차드 대부분뿐만 아니라 현대 리비아 남부, 니제르 동부, 나이지리아 북동부, 카메룬 북부 일부를 포함하는 지역을 포괄했습니다. 트리폴리와 차드호 지역 사이의 사하라 횡단 무역로 남쪽 끝에 위치했습니다. 이곳은 가장 큰 오아시스인 차드호가 있는 덥고 건조한 지역입니다.' UNION ALL
