SELECT 'TXT_KEY_CITYSTATE_SHAMAKHI_ADJ', 			'시르반의' UNION ALL
SELECT 'TXT_KEY_CIV5_SHAMAKHI_TEXT', 				'시르반은 이슬람 이전 사산 왕조와 이슬람 시대에 알려진 캅카스 동부의 역사적 지역입니다. 809년에서 1607년 사이 800년 동안 독립 또는 봉신 상태를 유지한 시르반은 이슬람 문화와 무역의 중심지였습니다. 오늘날 이 지역은 카스피해 서쪽 해안과 쿠라강 사이, 시르반 평원을 중심으로 뻗어 있는 아제르바이잔 공화국의 산업 및 농업적으로 발전된 부분입니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_THABA_BOSIU', 		'타바 보시우' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_THABA_BOSIU_ADJ', 		'바소토의' UNION ALL
SELECT 'TXT_KEY_CIV5_THABA_BOSIU_TEXT', 			'현재 레소토로 알려진 영토는 일찍이 신석기 시대(신석기)부터 코이산어를 사용하는 수렵 채집인들이 점유했습니다. 16세기경부터 아프리카 농부들(현재 인구의 조상)이 남부 아프리카의 초원을 가로질러 이동하여 칼레돈강의 비옥한 계곡에 정착하여 이 지역의 사냥꾼들을 지배하게 되었습니다. 가축을 기르는 이 농업인들은 대규모 소토 그룹에 속했으며 촌락을 점유한 구성원들로 이루어진 추장국의 핵심을 형성하는 수많은 씨족으로 나뉘었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_VADUZ', 				'파두츠' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_VADUZ_ADJ', 				'리히텐슈타인의' UNION ALL
SELECT 'TXT_KEY_CIV5_VADUZ_TEXT', 					'파두츠는 알프스 기슭의 라인강을 따라 자리 잡은 리히텐슈타인의 수도입니다. 크기는 작지만 역사적, 정치적으로 큰 의미를 지니고 있습니다. 이 지역은 중세 시대에 처음 정착되었으며 파두츠는 14세기에 공식적으로 설립되었습니다. 1712년 리히텐슈타인 가문이 백작령을 매입한 후 행정 중심지가 되었으며 결국 공국 전체에 이름을 부여했습니다. 시간이 지남에 따라 파두츠는 작은 마을에서 정치 및 문화 중심지로 성장했으며, 특히 1866년 리히텐슈타인이 완전한 주권을 얻은 후 더욱 그러했습니다. 마을을 지배하는 것은 대공 가문의 거주지인 파두츠성입니다. 오늘날 파두츠는 박물관, 정부 청사, 금융 센터를 포함한 역사적 매력과 현대적 기관의 조화로 유명하며 유럽에서 가장 그림 같은 수도 중 하나로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_VICTORIA', 			'빅토리아' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_VICTORIA_ADJ', 			'세이셸의' UNION ALL
SELECT 'TXT_KEY_CIV5_VICTORIA_TEXT', 				'세이셸 공화국은 소말리아해 동쪽 가장자리의 인도양에 있는 군도 국가입니다. 115개의 섬으로 구성되어 있습니다. 수도이자 가장 큰 도시인 빅토리아는 아프리카 본토에서 동쪽으로 1,500km 떨어져 있습니다. 다른 인근 섬나라 및 영토로는 남쪽의 코모로, 마요트(프랑스 영토), 마다가스카르, 레위니옹(프랑스 영토), 모리셔스; 동쪽의 몰디브와 차고스 제도가 있습니다. 인구는 약 94,367명으로 주권 아프리카 국가 중 인구가 가장 적습니다. [NEWLINE][NEWLINE]세이셸은 16세기 유럽인들이 발견하기 전에는 사람이 살지 않았습니다. 19세기 후반 영국의 완전한 통제하에 들어갈 때까지 프랑스와 영국의 경쟁적인 이해관계에 직면했습니다. 1976년 영국으로부터 독립을 선언한 이후 세이셸은 주로 농업 사회에서 시장 기반의 다각화된 경제로 발전했으며 서비스, 공공 부문, 관광 활동이 급격히 증가했습니다. 1976년부터 2015년까지 명목 GDP는 거의 7배 증가했고 구매력 평가 기준은 거의 16배 증가했습니다. 2010년대 후반부터 정부는 외국인 투자를 장려하기 위한 조치를 취했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ASMARA', 				'아스마라' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ASMARA_ADJ', 				'에리트레아의' UNION ALL
SELECT 'TXT_KEY_CIV5_ASMARA_TEXT', 					'홍해에 위치한 아프리카의 뿔 국가인 에리트레아. 에리트레아의 해안 위치는 역사와 문화에서 오랫동안 중요했습니다. 이는 "홍해"를 뜻하는 라틴어 Mare Erythraeum의 이탈리아어 버전인 이름에도 반영되어 있습니다. 홍해는 기독교와 이슬람교가 이 지역에 도달한 경로였으며 터키, 이집트, 이탈리아와 같은 강대국들이 에리트레아 해안의 항구를 장악하여 지배하고자 했던 중요한 무역로였습니다. 그 항구들은 남쪽의 에티오피아 고원에서 상인들이 판매하는 금, 커피, 노예에 대한 접근을 약속했으며, 20세기 후반에 에티오피아는 에리트레아 사람들이 자신의 국가를 만들기 위해 해방되어야 했던 세력이 되었습니다.[NEWLINE][NEWLINE]거의 30년 동안 지속된 독립 전쟁 후 1993년 에리트레아는 주권 국가가 되었습니다. 긴 투쟁 동안 에리트레아 사람들은 공통된 민족 의식을 형성했지만, 평화가 확립되자 수년간의 가뭄, 방치, 전쟁으로 악화된 빈곤에서 나라를 일으키기 위해 민족적, 종교적 차이를 극복해야 하는 과제에 직면했습니다. 에리트레아의 수도이자 가장 큰 도시는 아스마라(아스메라)입니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TORSHAVN', 			'토르스하운' UNION ALL  -- replaces Balley Chashtal
SELECT 'TXT_KEY_CITYSTATE_TORSHAVN_ADJ', 			'페로의' UNION ALL
SELECT 'TXT_KEY_CIV5_TORSHAVN_TEXT', 				'현지 페로어로 푀로야르라고 불리는 페로 제도는 덴마크 왕국 내의 자치 국가입니다. 스코틀랜드 북쪽, 노르웨이와 아이슬란드 중간쯤에 있는 북대서양의 군도로 구성되어 있습니다. 현재 섬의 인구는 약 50,000명이며 거의 모두 서기 650년경 군도에 정착한 노르드-게일인의 후손입니다. 꽤 고립되어 있음에도 불구하고 페로 제도는 고도로 현대화되어 있으며 인간 개발 지수에서 가장 높은 범주에 속합니다. 덴마크 왕국의 일부이지만 페로 제도는 1948년부터 자치권을 행사해 왔습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CARAL', 				'카랄' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_CARAL_ADJ', 				'카랄의' UNION ALL
SELECT 'TXT_KEY_CIV5_CARAL_TEXT', 					'카랄-수페 문명이라고 더 공식적으로 불리는 노르테 치코 문화는 오늘날 페루의 북중부 해안에서 발전한 콜럼버스 이전 문화였습니다. 기원전 3200-1800년 사이에 번성한 아메리카 대륙에서 가장 오래된 문명으로 확립되었으며 고대 세계에서 문명이 독립적으로 발생한 6곳 중 하나입니다. 노르테 치코는 주식 곡물이 없는 상태에서 해양 식량 자원에 대한 독특한 의존을 나타낼 가능성이 있지만, 최근 연구에서는 산업을 지원하고 식단을 보강하는 데 있어 농업의 역할을 강조합니다. 노르테 치코는 차빈과 잉카와 같은 위대한 후속 안데스 문명의 문화적 전임자였을 가능성이 큽니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DAKAR', 				'다카르' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_DAKAR_ADJ', 				'세네갈의' UNION ALL
SELECT 'TXT_KEY_CIV5_DAKAR_TEXT', 					'세네갈 공화국은 서아프리카에 있는 나라입니다. 세네갈은 북쪽으로 모리타니, 동쪽으로 말리, 남동쪽으로 기니, 남서쪽으로 기니비사우와 국경을 접하고 있습니다. 세네갈은 또한 감비아강 유역을 따라 좁은 땅을 차지하고 있는 감비아와 국경을 접하고 있는데, 감비아강은 세네갈의 남부 카자망스 지역을 나머지 지역과 분리합니다. 세네갈은 또한 카보베르데와 해상 국경을 공유합니다. 세네갈의 경제 및 정치 수도는 다카르입니다. [NEWLINE][NEWLINE]단일 대통령제 공화국은 구세계, 즉 아프로-유라시아 본토의 최서단 국가이며 동쪽과 북쪽 경계를 이루는 세네갈강에서 이름을 따왔습니다. 세네갈의 면적은 거의 197,000제곱킬로미터(76,000제곱마일)이며 인구는 약 1,500만 명으로 추산됩니다. 기후는 전형적인 사헬 기후이지만 우기가 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KAGYRGYN', 			'카기르긴' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KAGYRGYN_ADJ', 			'축치의' UNION ALL
SELECT 'TXT_KEY_CIV5_KAGYRGYN_TEXT', 				'축치인은 러시아 시베리아 극동 북동부의 축치반도 원주민입니다. 전통적으로 그들은 북극 해안을 따라 살며 고래, 바다코끼리, 물범 사냥에 의존하는 "해양 축치"와 내륙에서 순록을 방목하는 "순록 축치"의 두 가지 주요 그룹으로 나뉩니다. 그들의 문화는 애니미즘, 샤머니즘, 자연환경과의 밀접한 관계에 깊이 뿌리를 두고 있습니다. 러시아인과의 첫 접촉은 17세기에 이루어졌으며 갈등과 러시아 제국으로의 최종 통합으로 이어졌습니다. 소비에트 시대의 동화 압력에도 불구하고 축치인은 언어, 전통, 유목 생활 방식의 많은 부분을 보존했습니다. 오늘날 많은 사람이 여전히 조상의 땅에 살면서 문화적 관습을 유지하는 동시에 현대 러시아 사회에도 참여하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KARIATEBIKE', 		'카리아테비케' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KARIATEBIKE_ADJ', 		'키리바시의' UNION ALL
SELECT 'TXT_KEY_CIV5_KARIATEBIKE_TEXT', 			'키리바시는 태평양 중부에 위치한 섬나라입니다. 그 역사는 폴리네시아 사람들의 이주 및 유럽 식민주의와 얽혀 있습니다. [NEWLINE]키리바시의 가장 초기 알려진 거주자는 기원전 2,000년경 이 지역에 정착했을 가능성이 높은 폴리네시아인이었습니다. 이 항해 민족은 낚시, 농업, 씨족 및 섬 공동체를 중심으로 한 사회 시스템을 포함하는 독특한 문화를 발전시켰습니다. [NEWLINE]키리바시와 유럽의 접촉은 18세기 후반 영국과 프랑스 탐험가들이 이 지역에 도착하면서 시작되었습니다. 이 섬들은 19세기 후반 대영제국의 일부가 되었으며 길버트 엘리스 제도 식민지에 편입되었습니다. [NEWLINE]제2차 세계 대전 중 키리바시는 일본군에 점령되었으며 일본군은 일부 섬에 군사 시설을 건설했습니다. 전쟁 후 섬들은 영국의 통제하에 돌아왔습니다. [NEWLINE]1960년대에 자치에 대한 열망이 커지면서 키리바시에서 정치적 변화가 일어났습니다. 길버트 제도는 1979년 영국으로부터 독립하여 키리바시 공화국이 되었습니다. 엘리스 제도는 현재의 투발루로, 1978년 키리바시에서 분리되어 독립 국가가 되었습니다. [NEWLINE]독립 이후 키리바시는 인구 증가, 제한된 자원, 기후 변화의 영향 등 수많은 도전에 직면해 있습니다. 이 나라는 33개의 산호 환초와 섬으로 구성되어 있으며 대부분이 매우 낮아 해수면 상승에 취약합니다. 키리바시는 기후 변화에 대한 국제 논의의 최전선에 서 있으며 국민을 보호하고 땅을 보존하기 위한 해결책을 모색해 왔습니다. [NEWLINE]키리바시 경제는 자급 농업, 어업, 국제 원조에 크게 의존합니다. 정부는 또한 관광과 외국에 대한 어업권 판매를 통해 수익원을 모색했습니다. [NEWLINE]키리바시는 고유한 언어, 전통, 관습을 가진 독특하고 문화적으로 풍요로운 국가로 남아 있습니다. 국민들은 유산과 생활 방식을 보존하면서 현대 세계의 도전에 계속 적응하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MADURAI', 			'마두라이' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MADURAI_ADJ', 			'판디아의' UNION ALL
SELECT 'TXT_KEY_CIV5_MADURAI_TEXT', 				'판디아 왕조는 남인도에서 가장 오래된 타밀 왕조 중 하나로, 주로 마두라이를 수도로 하는 현재의 타밀나두 지역에서 번성했습니다. 기원전 6세기 초에 등장한 판디아는 고대 타밀 문학에서 무역, 문학, 예술을 후원한 것으로 찬사를 받았습니다. 그들은 코르카이와 같은 항구를 통해 로마 제국 및 기타 지역과 해상 무역 관계를 유지했습니다. 왕조는 여러 단계의 권력을 경험했으며 서기 7세기에서 14세기 사이에 남인도 대부분과 스리랑카 일부를 지배했을 때 정점에 도달했습니다. 촐라 왕조 및 체라 왕조와의 경쟁으로 알려진 판디아는 마두라이의 유명한 미낙시 암만 사원의 후원자이기도 했습니다. 14세기 델리 술탄국의 침략 이후 그들의 통치는 쇠퇴하여 정치적 지배가 끝났지만 그들의 문화적 유산은 타밀 역사와 전통에 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_OKAK', 				'오카크' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_OKAK_ADJ', 				'툴레의' UNION ALL
SELECT 'TXT_KEY_CIV5_OKAK_TEXT', 					'툴레 문화는 서기 1000년경 현재의 알래스카에서 발생하여 캐나다 북극을 가로질러 그린란드까지 동쪽으로 퍼진 원주민 북극 문명이었습니다. 초기 고대 이누이트 그룹의 후손인 툴레 사람들은 매우 숙련된 사냥꾼이었으며 특히 고래 잡이, 물범 사냥, 도구 제작의 고급 기술로 유명했습니다. 그들은 개썰매, 우미악(대형 가죽 보트), 극한의 극지 조건에서의 생활에 적합한 작살과 같은 정교한 기술을 개발했습니다. 그들의 이주는 초기 도싯 문화를 대체하거나 흡수했으며, 그들의 정착지에는 종종 고래 뼈와 떼로 만든 반지하 주택이 있었습니다. 17세기까지 툴레는 문화적으로나 지리적으로 현대 이누이트의 조상으로 진화하여 북극 생존에 대한 적응력과 전문성을 반영하는 중요한 고고학적, 문화적 유산을 남겼습니다. 바이킹 소스에서 이 사람들은 스크렐링이라고 불립니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_REYKJAVIK', 			'레이캬비크' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_REYKJAVIK_ADJ', 			'아이슬란드의' UNION ALL
SELECT 'TXT_KEY_CIV5_REYKJAVIK_TEXT', 				'아이슬란드의 수도이자 가장 큰 도시인 레이캬비크는 남서부 해안에 위치하고 있으며 문화, 경제, 정치 중심지 역할을 합니다. 아이슬란드 전통에 따르면 서기 874년경 노르드인 잉골푸르 아르나르손이 처음 정착하여 근처 온천에서 피어오르는 증기를 보고 "연기의 만"이라는 뜻의 "레이캬비크"라고 명명했습니다. 수 세기 동안 레이캬비크는 작은 어업 및 농업 정착지로 남아 있다가 18세기에 덴마크 주도의 도시 및 경제 개발의 초점이 되었습니다. 이 도시는 19세기와 20세기에 빠르게 성장했으며, 특히 1918년 아이슬란드가 자치권을 얻고 1944년 덴마크로부터 완전히 독립하여 레이캬비크가 국가 수도로 지정된 후 더욱 그렇습니다. 오늘날 이곳은 깨끗하고 현대적인 디자인, 지열 에너지 사용, 활기찬 예술 현장, 눈에 띄는 자연환경으로 유명하며 현대 아이슬란드 정체성을 정의하는 전통과 혁신의 조화를 상징합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SKARA_BRAE', 			'스카라 브레이' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SKARA_BRAE_ADJ', 			'픽트의' UNION ALL
SELECT 'TXT_KEY_CIV5_SKARA_BRAE_TEXT', 				'스카라 브레이는 스코틀랜드 오크니 본토에 위치한 신석기 시대 정착지입니다. 기원전 3100년경으로 거슬러 올라가는 이곳은 북유럽에서 가장 잘 보존된 선사 시대 마을 중 하나입니다. 이 유적지는 1850년 심한 폭풍으로 인해 발견되었으며 정교한 배수 시스템, 화로, 침대 및 옷장과 같은 가구를 갖춘 잘 지어진 석조 주택 단지가 드러났습니다. 스카라 브레이는 주민들의 일상생활에 대한 귀중한 통찰력을 제공하며 그들의 진보된 건축 및 조직 기술을 보여줍니다. [NEWLINE][NEWLINE]이 마을에는 아마도 50~100명의 사람들이 살았을 것이며 기원전 2500년경 불분명한 이유로 버려지기 전까지 수 세기 동안 거주했습니다. 뛰어난 보존 상태로 인해 스카라 브레이는 유네스코 세계문화유산으로 지정되었으며 인기 있는 관광 명소가 되어 방문객들에게 고대 과거와 초기 거주자들이 환경에 적응한 독창성을 엿볼 수 있는 기회를 제공합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KESPUKWITK', 			'케스푸크위트크' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KESPUKWITK_ADJ', 			'와바나키의' UNION ALL
SELECT 'TXT_KEY_CIV5_KESPUKWITK_TEXT', 				'와바나키 연맹은 현재 캐나다의 연해주와 미국 메인주로 알려진 지역에 위치한 5개 원주민 국가의 느슨한 제휴였습니다. 미크맥, 말리시트, 파사마쿼디, 아베나키, 페놉스콧의 5개 국가는 공동의 목표와 이익, 주로 어업 및 사냥 수역을 보호하기 위해 한 명의 대추장 아래 뭉쳤습니다. 와바나키 연맹은 위에서 언급했듯이 느슨한 제휴였지만 연맹의 회원국들은 서로에게 맹렬히 충성했습니다. 연맹은 이로쿼이와 같은 외부 위협으로부터 회원국을 보호하기 위해 노력했으며 대추장의 지도를 따랐습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BAGUIO', 				'바기오' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_BAGUIO_ADJ', 				'이고로트의' UNION ALL
SELECT 'TXT_KEY_CIV5_BAGUIO_TEXT', 					'"이고로트"라는 단어는 필리핀 루손 북부 산악 지대의 다양한 민족 그룹을 지칭하며, 이들은 모두 전통 종교와 생활 방식을 유지하거나 최근까지 유지해 왔습니다. 일부는 산기슭의 열대 우림에 살지만 대부분은 더 높은 곳의 험준한 초원과 소나무 숲 지대에 삽니다. 이고로트족은 21세기 초에 약 150만 명이었습니다. 그들의 언어는 오스트로네시아(말레이-폴리네시아)어족에 속하는 필리핀 언어의 북부 루손 하위 그룹에 속합니다. [NEWLINE]이고로트 사람들은 오스트로네시아인입니다. 그들은 옛날에 전쟁과 머리 사냥 관습으로 유명했습니다. 스페인 사람들은 필리핀을 식민 점령하는 동안 그들을 강제로 부분적으로 복종시켰으며, 그 과정은 미국 패권 기간 동안 완료되었습니다. 민족학자들은 약 10개의 주요 민족 그룹을 구별하며 각각 고유한 방언과 문화를 가지고 있습니다. 이 그룹 내에도 변형이 있습니다. [NEWLINE]이고로트 전체를 두 가지 더 넓은 그룹으로 나눌 수 있습니다. 훨씬 더 큰 그룹은 주로 산비탈의 계단식 논에서 벼를 재배하는 고지대 사람들로 구성됩니다. 다른 그룹은 계절에 따라 이동하는 정원에서 밭벼를 재배하는 저지대 열대 우림 지역의 사람들로 구성됩니다. 첫 번째 그룹 내에서 나발로이 또는 이발로이, 칸카나이, 레판토 또는 북부 칸카나이, 본톡, 남부 칼링가, 팅기안은 거의 모두 인구가 많은 마을에 살지만, 한 민족 단위인 이푸가오는 계단식 논 전체에 흩어져 있는 친척들의 작은 농가에 삽니다. 두 번째 그룹인 가당, 북부 칼링가, 이스네그 또는 아파야오는 토양의 지력이 다하면 새로운 정원을 개간하는 촌락이나 농가에 드문드문 정착해 있습니다. 일부 가당은 나무 위 오두막에 삽니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ABALESSA', 			'아발레사' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ABALESSA_ADJ', 			'투아레그의' UNION ALL
SELECT 'TXT_KEY_CIV5_ABALESSA_TEXT', 				'베르베르어인 타마셰크어를 사용하는 반유목 이슬람 민족인 투아레그족은 니제르, 말리, 알제리, 리비아의 현대 민족 국가에 살고 있습니다. 그들은 북아프리카 베르베르인의 후손으로 리비아의 페잔 지역에서 기원했지만 나중에 사하라 사막 접경 지역으로 확장하여 사하라 이남 지역의 정착 농경 민족을 전통적으로 계층화된 사회에 동화시킨 것으로 여겨집니다. 투아레그족은 이 인구와 무역을 했으며 노예를 얻기 위해 그들을 습격하기도 했습니다. 따라서 투아레그족은 아랍의 영향에서 사하라 이남에서 유래한 영향에 이르기까지 다양한 신체적, 문화적 특성을 보여줍니다. 오늘날 가장 일반적으로 알려진 용어인 "투아레그"는 사실 외부, 아마도 아랍어 기원의 용어입니다. 공통 언어와 문화로 통합되어 있지만 혈통에 기반한 다양한 사회 계층에 속하고 지리적 기원이 다르며 가축 사육, 오아시스 원예, 대상, 전문적인 꾸란 학문, 대장장이 등 다양한 생계 패턴을 실천하는 사람들의 민족성과 문화를 지정하기 위해 광택 또는 포괄적 용어로 부과되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AZEBA', 				'아제바' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_AZEBA_ADJ', 				'사바의' UNION ALL
SELECT 'TXT_KEY_CIV5_AZEBA_TEXT', 					'사바(시바라고도 함)는 아라비아 남부(현대 예멘 지역)의 왕국으로 기원전 8세기에서 이웃 힘야르인들에게 정복된 서기 275년 사이에 번성했습니다. 이것이 가장 일반적으로 받아들여지는 날짜이지만, 다양한 학자들이 기원전 1200년경의 가장 빠른 날짜로 더 길거나 짧은 연대기를 주장했습니다. 그러나 대부분은 서기 275년경의 종말에 동의합니다. 전성기에 사바는 아라비아 남부와 지중해의 가자 항구 사이의 향료 경로를 따라 무역을 통해 부유해진 부유한 왕국으로 알려졌습니다. 유명한 여왕인 시바의 여왕 이야기를 포함하여 대부분의 성서 및 꾸란 언급은 사바의 부와 무역에서의 성공을 언급합니다. [NEWLINE][NEWLINE]기원전 8세기 이전에는 이 지역의 무역이 마인 왕국의 미네아인들에 의해 통제되었던 것으로 보이지만 기원전 950년경 사바인들이 이 지역을 지배하고 하드라마우트, 카타반, 카니 항구의 남쪽 이웃에서 북쪽으로 향하는 상품에 세금을 부과했습니다. 사바 무역은 프톨레마이오스 왕조가 육로 여행보다 해로를 장려했던 이집트의 프톨레마이오스 왕조(기원전 323-30년) 동안 타격을 입었고, 사바의 위신은 이웃 힘야르인들에게 정복될 때까지 쇠퇴했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GABORONE', 			'가보로네' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GABORONE_ADJ', 			'보츠와나의' UNION ALL
SELECT 'TXT_KEY_CIV5_GABORONE_TEXT', 				'보츠와나는 아프리카 남부 중앙에 있는 나라입니다. 영토는 대략 삼각형 모양으로 남북으로 약 600마일(965km), 동서로 600마일이며 동쪽 측면이 뾰족한 지점으로 튀어나와 있습니다. 동쪽과 남쪽 국경은 강줄기와 오래된 마차 도로로 표시됩니다. 서쪽 국경은 칼라하리를 통과하는 경도와 위도선이며 북쪽 국경은 직선과 강줄기를 결합합니다. 보츠와나 국경 내에는 포유류, 조류, 파충류, 양서류, 어류의 많은 종을 포함하여 다양한 야생 동물이 있습니다.[NEWLINE][NEWLINE]1966년 독립하기 전 보츠와나는 베추아날란드라고 알려진 영국 보호령이었습니다. 또한 세계에서 가장 가난하고 개발이 덜 된 국가 중 하나였습니다. 국명은 지배적인 민족 그룹인 츠와나(오래된 변형 철자법으로 "베추아나")의 이름을 따서 명명되었습니다. 독립 이후 보츠와나 공화국은 평화롭고 점점 더 번영하는 민주주의 국가로서 국제적 위상을 얻었습니다. 유엔, 영연방, 아프리카 연합(AU), 남부 아프리카 개발 공동체(SADC)의 회원국입니다. SADC 사무국은 보츠와나의 수도 가보로네(1969년까지 가베로네스, 즉 식민지 시대에 그곳에 수도를 두었던 부족장의 이름을 딴 가보로네의 마을로 표기됨)에 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PEGU', 				'페구' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_PEGU_ADJ', 				'페구의' UNION ALL
SELECT 'TXT_KEY_CIV5_PEGU_TEXT', 					'한타와디 왕국(론 홍사르와토이 또는 간단히 페구라고도 함)은 1287년부터 1539년까지, 그리고 1550년부터 1552년까지 하버마(미얀마)를 통치했던 정치체였습니다. 한타와디는 몬어 사용 왕국(1369-1538, 1550-1552)의 수도인 오늘날의 바고인 페구 시의 옛 이름입니다. [NEWLINE]장소로서의 페구에 대한 가장 초기의 현존하는 증거는 파간 말기(1212년 및 1266년)로 거슬러 올라가는데, 당시에는 지방 수도조차 아닌 작은 마을이었습니다. 파간 제국이 붕괴된 후 페구는 1290년대까지 분리된 마르타반 왕국의 일부가 되었습니다. [NEWLINE]이 작은 정착지는 14세기에 이 지역이 몬어 사용 왕국에서 가장 인구가 많은 지역이 되면서 점점 더 중요해졌습니다. 1369년 빈야 우 왕은 페구를 수도로 삼았습니다. 라자다리트 왕의 통치 기간 동안 페구와 아바 왕국은 40년 전쟁을 벌였습니다. 신 소부 여왕의 평화로운 통치는 그녀가 불교 승려 담마제디(1471-1492)를 후계자로 선택하면서 끝났습니다. 담마제디 하에서 페구는 상업과 상좌부 불교의 중심지가 되었습니다. [NEWLINE]이 도시는 1538년 왕국이 멸망할 때까지 수도로 남아 있었습니다. 타빈슈웨티 하의 떠오르는 퉁구 왕조는 훨씬 더 큰 왕국이 자원을 동원할 수 없을 정도로 수많은 습격을 감행했습니다. 왕국은 1550년대에 2년 동안 잠시 부활했지만 타빈슈웨티의 후계자 바인나웅은 1553년에 페구를 확고하게 장악하게 됩니다.' UNION ALL
