SELECT 'TXT_KEY_CITYSTATE_LUXEMBOURG_ADJ', 			'룩셈부르크의' UNION ALL
SELECT 'TXT_KEY_CIV5_LUXEMBOURG_TEXT', 				'룩셈부르크의 역사는 963년 지크프리트 백작이 룩셈부르크시 북동쪽 모퉁이에 있는 곶인 보크피엘스(영어로는 "Bock")를 획득하면서 시작됩니다. 그 위에는 로마 요새로 추정되는 루실린부르후크 요새가 폐허로 남아 있었습니다. 지크프리트는 폐허 부지에 새로운 성을 지었는데, 이 성은 랭스, 아를롱, 트리어로 이어지는 오래된 로마 도로의 일부를 지배하여 무역과 과세의 전망을 제공했습니다. 그 후 몇 년 동안 새로운 성 주변에 작은 마을과 시장이 성장했습니다. 정착지는 곧 첫 번째 부분적인 성벽과 해자 건설로 추가적인 보호를 받았습니다. 아르덴-베르됭 왕조(비게리히)의 지크프리트 후손들은 요새를 확장하고 11세기부터 스스로를 룩셈부르크 백작이라고 부르기 시작했습니다. 1136년 아르덴-룩셈부르크 분파가 멸종되자 백작령은 나무르 가문으로 넘어갔고 궁극적으로 에르메신데 백작 부인에게 넘어갔습니다. 그녀는 룩셈부르크 가문을 시작하여 세 명의 신성 로마 제국 황제를 배출했습니다. [NEWLINE][NEWLINE]수 세기 동안 부르고뉴, 합스부르크, 프랑스, 프로이센을 포함한 다양한 세력의 통제를 받았습니다. 1839년 런던 조약은 룩셈부르크의 독립을 확립하고 국경을 고정하여 영토를 벨기에와 대공국으로 나누었습니다. 중립에도 불구하고 두 차례의 세계 대전 동안 점령되었습니다. 제2차 세계 대전 이후 룩셈부르크는 유엔, NATO, 유럽 연합의 창립 회원국으로 부상하여 금융 부문과 문화유산으로 알려진 번영하고 정치적으로 안정된 국가로 발전했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NYENI', 				'니아니' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_NYENI_ADJ', 				'만덴의' UNION ALL
SELECT 'TXT_KEY_CIV5_NYENI_TEXT', 					'말리 제국 또는 만덴은 1235년경부터 1670년까지 서아프리카에 있었던 제국이었습니다. 제국은 순디아타 케이타에 의해 설립되었으며 통치자, 특히 만사 무사의 부로 유명해졌습니다. 제국에서는 만딩어가 사용되었습니다. 전성기 말리는 서아프리카에서 가장 큰 제국이었습니다. 제국은 만딩을 중심으로 니제르강 상류의 작은 만딩카 왕국으로 시작되었습니다. 11세기와 12세기에 북쪽의 가나 제국 또는 와가두가 쇠퇴한 후 제국으로 발전하기 시작했습니다. 그러나 1507년부터 디아라, 대풀로, 송가이 제국과 같은 이웃 국가들이 말리의 외곽 국경을 잠식했습니다. 만사 마마 마간이 바마나를 정복하려다 실패한 후 1670년 바마나가 수도를 약탈하고 불태웠고 말리 제국은 급속히 붕괴되어 존재하지 않게 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_POMBERUK', 			'폼베룩' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_POMBERUK_ADJ', 			'나린제리의' UNION ALL
SELECT 'TXT_KEY_CIV5_POMBERUK_TEXT', 				'나린제리는 현대 남호주주의 머레이강 하류와 쿠롱을 따라 사는 원주민 그룹입니다. 나린제리는 "라칼린예리"라고 알려진 18개의 영토 씨족으로 구성된 다양한 그룹입니다. 각 라킨예리는 텐디라고 알려진 장로 협의회에 의해 통치되며, 텐디는 루풀리라는 직함을 가진 지도자를 선출하여 전체 나린제리 연맹을 관리합니다. 라칼린예리 간의 결속력 수준은 논쟁의 여지가 있습니다. 일부 학자들은 "나린제리"가 유럽 식민지 개척자들이 부과한 비역사적인 포괄적 용어라고 주장합니다. [NEWLINE][NEWLINE]나린제리는 기원전 8000년경 전통적인 영토에 처음 도착했습니다. 이 땅의 비옥함 덕분에 그들은 주로 사냥과 낚시를 통해 생계를 유지하는 반정주 생활 방식을 유지할 수 있었습니다. 나린제리는 물고기와 에뮤를 잡는 데 사용되는 고품질 그물과 효율적인 오븐 마운드로 유명했습니다. 나가람비라고 알려진 광범위한 금기는 누가 어떤 동물을 먹을 수 있는지 규정합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_UGARIT', 				'우가리트' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_UGARIT_ADJ', 				'우가리트의' UNION ALL
SELECT 'TXT_KEY_CIV5_UGARIT_TEXT', 					'우가리트는 현재 시리아인 지중해 동부 해안에 위치한 고대 도시 국가였습니다. 후기 청동기 시대에 주요 문화 및 경제 중심지로 부상하여 기원전 14세기부터 12세기까지 번성했습니다. [NEWLINE]우가리트의 역사는 주로 우가리트어라는 쐐기 문자로 쓰인 점토판으로 구성된 광범위한 기록 보관소를 통해 알려져 있습니다. 이 서판들은 도시의 정치, 사회, 경제, 종교적 측면에 대한 귀중한 통찰력을 제공합니다. [NEWLINE]우가리트는 작은 정착지로 시작하여 해상 무역 허브로서의 전략적 위치로 인해 점차 중요성이 커졌을 것입니다. 이집트, 키프로스, 아나톨리아, 히타이트 제국을 포함한 다양한 문명과 무역을 했습니다. 이 도시는 번영, 부, 문화 교류로 유명해졌습니다. [NEWLINE]기원전 14세기경 우가리트는 무역로를 통제하고 이 지역에서 동맹을 맺으려는 강력한 히타이트 제국의 영향력 아래 들어갔습니다. 우가리트는 히타이트와 외교 및 경제적 관계를 유지하면서 어느 정도의 독립성을 유지했습니다. [NEWLINE]이 도시는 경제적 번영과 예술적 성취를 누렸던 기원전 13세기에 정점에 도달했습니다. 우가리트어와 문자가 번성했고 도시는 바알, 다곤, 엘을 포함한 다양한 신에게 바쳐진 사원이 있는 종교 예배의 중심지가 되었습니다. [NEWLINE]그러나 우가리트의 번영은 기원전 12세기 초에 갑작스럽게 끝났습니다. 도시는 아마도 침략한 바다 민족, 내부 불안, 자연재해의 조합으로 인해 공격을 받고 파괴되었습니다. 우가리트는 폐허가 되었고 기록 보관소는 도시를 휩쓴 화재로 보존되어 현대 학자들에게 귀중한 역사적, 언어적 정보를 제공했습니다. [NEWLINE]우가리트의 쇠퇴와 파괴는 고대 세계에서 그 명성의 끝을 알렸습니다. 도시는 버려졌고 점차 잊혀졌으며 후속 문명들이 그 폐허 위에 건설되었습니다. [NEWLINE]오늘날 고고학적 발굴을 통해 우가리트의 인상적인 유적이 드러나 한때 번성했던 문명을 엿볼 수 있습니다. 우가리트에서 이루어진 발견은 고대 근동, 무역 네트워크, 사회 구조, 종교적 신념, 쐐기 문자 체계의 발전에 대한 우리의 이해에 크게 기여했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DIEGO_GARCIA', 		'디에고 가르시아' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_DIEGO_GARCIA_ADJ', 		'차고스의' UNION ALL
SELECT 'TXT_KEY_CIV5_DIEGO_GARCIA_TEXT', 			'차고스는 북쪽의 몰디브 술탄국에 의해 처음 발견되었는데, 선원들이 그레이트 차고스 뱅크의 열대 해안에 표류하여 그 땅을 폴하바히라고 명명했습니다. 대항해 시대에 포르투갈 선원들은 군도를 바사스 데 차가스라고 명명했는데, 이는 예수의 십자가형의 성스러운 상처를 가리키는 이름입니다. 그러나 이 섬들은 북쪽과 동쪽의 더 부유한 섬들에 비해 경제적으로 수익성이 없었기 때문에 앞으로 몇 년 동안 황무지로 남았습니다. 1771년 프랑스 제국은 섬에 대한 소유권을 주장하고 코코넛 오일 농장을 설립했습니다. 이것은 영국의 관심을 끌었고, 영국은 1786년에 섬을 차지했고 결국 1814년 나폴레옹이 패배한 후 통제권을 장악했습니다. 이 섬들은 100년 넘게 대영제국의 신민으로 남아 모리셔스의 행정 구역에 흡수되었습니다. 코코넛 농장에서 일했던 노예의 후손들은 해변과 정글에서 스파르타식 삶을 살며 평화롭게 섬에 거주했습니다. 그러나 1965년 모리셔스가 자치권을 부여받으면서 영국은 농장을 제거하고 미군 기지를 설치할 목적으로 군도를 매입했습니다. 1967년에서 1973년 사이에 차고스의 전체 인구는 세이셸이나 모리셔스로 강제 이주되었으며 종종 거친 주택에서 잠을 자고 열악한 생활 조건을 견뎌야 했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GUNGNAE', 			'국내성' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GUNGNAE_ADJ', 			'고구려의' UNION ALL
SELECT 'TXT_KEY_CIV5_GUNGNAE_TEXT', 				'고구려는 고대 한국의 삼국 중 하나로, 기원전 37년 동명왕(주몽이라고도 함)이 한반도 북부와 만주 남부에 건국했습니다. 수 세기 동안 강력한 군사 국가로 확장하여 광대한 영토를 통제하고 동북아시아의 지배적인 세력이 되었습니다. 고구려는 강력한 요새, 진보된 군사 조직, 토착 전통과 중국 문명의 영향을 받은 풍부한 문화로 유명했습니다. 왕국은 중국 왕조 및 이웃 한국 국가, 특히 백제 및 신라와 자주 충돌했습니다. 5세기 광개토대왕과 그의 아들 장수왕 치하의 전성기에 고구려는 만주와 북한의 대부분을 통치했습니다. 그러나 내부 분쟁과 당나라와 신라 동맹의 외부 압력으로 인해 서기 668년에 멸망했습니다. 고구려의 유산은 한국 문화, 정체성, 역사적 의식을 깊이 형성하여 힘과 독립을 상징합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MACACO', 				'마카코' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MACACO_ADJ', 				'팔마리스의' UNION ALL
SELECT 'TXT_KEY_CIV5_MACACO_TEXT', 					'팔마리스는 식민지 남미의 오지에서 주로 도망친 노예들로 구성된 임시 사회인 킬롬보였습니다. 이러한 공동체 중 더 큰 것은 현대 아프리카 통치 스타일을 기반으로 한 조직화된 왕국의 형태를 취했으며 심지어 자체적인 세습 군주제를 시작했습니다. 팔마리스는 1605년 설립부터 1694년 최종 패배까지 거의 1세기 동안 지속된 킬롬보 중 단연 가장 크고 성공적이었습니다. 팔마리스 인구 추정치는 전성기에 10,000명에서 20,000명 사이로 다양합니다. 팔마리스는 포르투갈 식민 당국의 습격을 자주 받았기 때문에 문화사에서는 카포에이라로 알려진 아프로-브라질 무술의 기원지로 여겨집니다. 포르투갈의 설명에 따르면 "네덜란드 침략자보다 킬롬보를 물리치기가 더 어렵다"고 합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANTHIMBA', 			'만팀바' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MANTHIMBA_ADJ', 			'마라비의' UNION ALL
SELECT 'TXT_KEY_CIV5_MANTHIMBA_TEXT', 				'마라비는 16세기에 말라위, 모잠비크, 잠비아의 현재 국경에 걸쳐 있던 왕국이었습니다. 오늘날의 이름 "말라위"는 "불꽃"을 의미하는 체와어 "말라위"에서 유래했다고 합니다. [NEWLINE]가장 넓었을 때 국가는 북쪽의 통가와 툼부카 사람들의 지역에서 남쪽의 로어 샤이어까지, 그리고 서쪽으로는 루앙와와 잠베지 강 계곡까지 영토를 포함했습니다. 마라비의 통치자들은 음왈레 모계 씨족에 속했으며 칼롱가라는 칭호를 가졌습니다. 그들은 세속/행정 수도인 만팀바에서 통치했으며 국가 수립의 원동력이었습니다. 한편 전통적으로 치료사, 현자, 야금술사를 제공했던 부계 반다 씨족은 은타카타카 근처의 수도 만캄바에서 종교 문제를 담당했습니다. [NEWLINE]포르투갈과의 접촉 후 무역이 강화되었습니다. 여기에는 카미 유형의 구슬과 포르투갈 중개인을 통해 수입된 중국 도자기와 같은 품목이 포함되었습니다. 19세기에 국가는 쇠퇴했고 마라비는 이웃 야오족의 습격을 자주 받아 노예로 팔려갔습니다. 데이비드 리빙스턴은 1859년 니아사 호수를 방문했고 다른 개신교 선교사들이 곧 뒤를 따랐습니다. ' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ORISTANO', 			'오리스타노' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ORISTANO_ADJ', 			'아르보레아의' UNION ALL
SELECT 'TXT_KEY_CIV5_ORISTANO_TEXT', 				'아르보레아 왕국으로도 알려진 아르보레아 주디카트는 이탈리아 해안의 사르데냐섬에 위치한 중세 국가였습니다. 11세기부터 15세기까지 존재했으며 섬의 역사에서 중요한 역할을 했습니다. [NEWLINE]아르보레아 주디카트의 기원은 칼리아리 주디카트로 거슬러 올라갈 수 있는데, 이는 주디카트 또는 주디카티로 알려진 여러 작은 국가로 분열된 초기 정치적 실체였습니다. 아르보레아는 가장 저명한 주디카트 중 하나로 부상하여 결국 독립을 얻었습니다. [NEWLINE]주디치 또는 판사의 통치하에 아르보레아 주디카트는 번성하여 "카르타 데 로그"로 알려진 독특한 법률 시스템을 개발했습니다. 14세기 엘레오노르 판사가 제정한 이 법전은 통치를 위한 포괄적인 틀을 제공하고 아르보레아 사람들을 위한 일련의 법률과 권리를 확립했습니다. [NEWLINE]아르보레아는 군사적 정복과 외교를 통해 영토를 확장했으며 때로는 다른 사르데냐 주디카트 및 섬을 장악하려는 외세와 충돌했습니다. 어느 정도의 자치권을 유지하면서 동맹을 맺고 이웃 국가와 무역을 했습니다. [NEWLINE]아르보레아 주디카트는 피터 4세 판사의 통치하인 14세기에 권력과 영향력의 정점에 도달했습니다. 그의 통치 기간 동안 주디카트는 외세로부터 독립을 주장하고 아라곤 왕국의 섬 정복 시도에 성공적으로 저항했습니다. [NEWLINE]그러나 아르보레아는 다음 세기에 내부 갈등과 외부 압력에 직면했습니다. 주디카트는 사르데냐에 대한 통제권을 강화하려는 아라곤 왕국의 확장에 직면하여 쇠퇴를 겪었습니다. 1410년 아르보레아의 마지막 독립 판사인 윌리엄 3세가 아라곤 군대에 체포되어 아르보레아의 정치적 독립이 사실상 끝났습니다. [NEWLINE]그 후 아르보레아는 사르데냐 왕국의 일부가 되었으며 결국 스페인 합스부르크 왕가와 나중에 사보이 왕가의 통치하에 들어갔습니다. 카르타 데 로그를 포함한 아르보레아의 독특한 법적, 문화적 유산은 사르데냐에 지속적인 영향을 남겼습니다. [NEWLINE]오늘날 아르보레아 주디카트의 역사와 문화유산은 사르데냐에서 인정받고 기념되며 섬의 과거에서 이 중요한 시기를 기념하는 다양한 유적지와 축제가 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PONTOTOC', 			'폰토톡' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_PONTOTOC_ADJ', 			'치카소의' UNION ALL
SELECT 'TXT_KEY_CIV5_PONTOTOC_TEXT', 				'치카소족은 원래 현재 미시시피 북부와 앨라배마에 거주했던 머스코기어족 계통의 북미 인디언 부족입니다. 초기 역사에서 치카소족과 촉토족은 단일 부족이었을 수 있습니다. 전통적으로 치카소족은 자신들이 주장하는 광대한 영토를 순찰하고 북쪽 멀리 있는 부족들을 습격하는 반유목 민족이었습니다. 많은 정복 민족과 마찬가지로 그들은 이 부족들의 잔재를 자신들의 문화에 통합했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PURUKCAHU', 			'푸룩 카후' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_PURUKCAHU_ADJ', 			'다약의' UNION ALL
SELECT 'TXT_KEY_CIV5_PURUKCAHU_TEXT', 				'다약족은 보르네오의 원주민 그룹 중 하나입니다. 주로 보르네오 중부 및 남부 내륙에 위치한 200개 이상의 강변 및 언덕 거주 소수 민족 하위 그룹을 가리키는 느슨한 용어입니다. 이 용어는 다양한 방언, 관습, 법률, 영토 및 문화를 포괄하지만 공통적인 특징을 쉽게 식별할 수 있습니다. 전통적으로 다약족은 정령 숭배자였지만 역사적으로 이슬람과 기독교로의 대량 개종이 있었습니다. 다약족의 역사는 주로 구전 역사 전통에 뿌리를 두고 있지만 파판 투라이(나무 기록)에 기록된 저작물과 공통적인 문화적 관습의 전승도 있습니다. 다약족 기원에 대한 저명한 설명 중에는 중부 칼리만탄의 응가주 다약족의 신화적 구전 서사시인 "테텍 타툼"이 있습니다. 이 서사시는 다약족의 조상이 하늘에서 내려와 내륙에서 보르네오 하류 해안으로 이동했다고 이야기합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SCODRA', 				'스코드라' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SCODRA_ADJ', 				'일리리아의' UNION ALL
SELECT 'TXT_KEY_CIV5_SCODRA_TEXT', 					'일리리아인은 고대에 발칸반도 서부 일부에 거주했던 인도유럽 부족 그룹이었습니다. 일리리아인이 거주했던 영토는 그리스와 로마 작가들에게 일리리아로 알려지게 되었으며, 이들은 서쪽의 아드리아해, 북쪽의 드라바강, 동쪽의 푸룩 카후바강, 남쪽의 아오스강 하구 사이의 크로아티아, 보스니아 헤르체고비나, 슬로베니아, 몬테네그로, 코소보, 세르비아 일부, 알바니아 중부 및 북부 대부분에 해당하는 영토를 식별했습니다. 일리리아인에 대한 최초의 설명은 지중해의 해안 통로를 묘사한 기원전 4세기 중반의 고대 그리스 텍스트인 위-스킬락스의 페리플러스에서 나옵니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TETOUAN', 			'테투안' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_TETOUAN_ADJ', 			'테투안의' UNION ALL
SELECT 'TXT_KEY_CIV5_TETOUAN_TEXT', 				'테투안의 역사는 마르틸 계곡 남쪽 기슭의 현재 테투안 근처에 위치한 타무다라는 모리타니 베르베르 정착지로서의 기원까지 2000년 이상 거슬러 올라갑니다. 이 유적지는 나중에 페니키아 무역소가 되었습니다. 아우구스투스 황제 시대에 타무다는 로마 속주 모리타니 팅기타나의 일부가 되었습니다. 1286년 마린 왕조는 그곳에 카스바와 모스크를 지었습니다. 최초의 대규모 건축 프로젝트는 1305년 마린 왕조의 아부 타비트 아미르 왕에 의해 정착지가 확장되었을 때 이루어졌습니다. 그는 그곳을 요새화하고 최근 마린 왕조의 반항적인 구성원의 지배하에 들어간 세우타에 대한 공격 기지로 삼았습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TILANTONGO', 			'틸란통고' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_TILANTONGO_ADJ', 			'믹스텍의' UNION ALL
SELECT 'TXT_KEY_CIV5_TILANTONGO_TEXT', 				'믹스텍 또는 믹스테코스는 멕시코 오악사카주와 푸에블라주의 라 믹스테카로 알려진 지역과 오악사카주, 게레로주, 푸에블라주의 일부를 포함하는 게레로주의 레기온 몬타냐스 및 레기온 코스타 치카에 거주하는 멕시코의 원주민입니다. 콜럼버스 이전 시대에 수많은 믹스텍 도시 국가들이 서로 경쟁하고 사포텍 왕국들과 경쟁했습니다. 주요 믹스텍 정치체는 11세기에 틸란통고의 영주이자 고원과 저지대 정치체를 단일 국가로 통합한 유일한 믹스텍 왕인 여덟 사슴 재규어 발톱의 지도하에 명성을 얻은 투투테펙이었습니다. 멕시코의 나머지 원주민들과 마찬가지로 믹스텍은 16세기에 스페인 침략자들과 그들의 원주민 동맹들에게 정복당했습니다. 콜럼버스 이전 믹스텍의 수는 약 150만 명이었습니다. 오늘날 멕시코에는 약 80만 명의 믹스텍 사람들이 있으며 미국에도 많은 인구가 있습니다. 믹스텍이라는 용어는 나후아틀어 mixtecah, "구름 사람들"에서 유래했습니다. 믹스텍 사람들이 자신을 부르는 이름은 여러 가지가 있습니다: ñuù savi, nayívi savi, ñuù davi, nayivi davi 등. 이 모든 명칭은 "비의 땅"으로 번역될 수 있습니다.' UNION ALL
