SELECT 'TXT_KEY_CIV5_CAHUACHI_TEXT', 				'나스카 문화는 기원전 100년경부터 서기 800년경까지 번성했던 콜럼버스 이전 페루 문화입니다. 복잡한 직물로 유명한 이전 파라카스 문화의 영향을 많이 받은 나스카는 도자기, 직물, 지상화(가장 흔한 것은 나스카 라인)를 포함한 인상적인 공예품과 기술 컬렉션을 만들었습니다. 그들은 또한 오늘날까지 기능하는 방대한 지하 수로 시스템을 만들었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CAIRO', 				'카이로' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_CAIRO_ADJ', 				'파티마의' UNION ALL
SELECT 'TXT_KEY_CIV5_CAIRO_TEXT', 					'파티마 칼리프조는 909년부터 1171년까지 광대한 제국을 통치했던 이슬람 왕조로, 예언자 무함마드의 딸 파티마의 후손이라고 주장하는 시아파 이슬람의 이스마일파 추종자들에 의해 북아프리카에서 설립되었습니다. 처음에 현재의 튀니지에 설립된 파티마 왕조는 북아프리카, 시칠리아, 레반트 전역으로 통제권을 확장하여 결국 서기 969년 카이로를 건설하고 정치 및 문화 수도로 삼았습니다. 칼리프조는 무역, 학문, 종교적 관용의 중심지로 번성하여 과학, 의학, 건축, 예술의 발전을 촉진했습니다. 파티마 왕조는 알 아즈하르 모스크와 같은 기념비적인 구조물을 건설했으며, 이는 세계 최고의 이슬람 학습 센터 중 하나가 되었습니다. 그러나 내부 분열, 경제적 어려움, 셀주크와 십자군의 군사적 압력 증가로 국가가 약화되어 결국 쇠퇴하고 1171년 살라딘 휘하의 수니파 아이유브 왕조로 대체되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CAMUTINS', 			'카무틴스' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_CAMUTINS_ADJ', 			'마라조아라의' UNION ALL
SELECT 'TXT_KEY_CIV5_CAMUTINS_TEXT', 				'정교한 다색 장례 도자기와 수많은 기념비적인 흙무덤으로 19세기부터 알려진 브라질 아마존 하구의 마라조아라 문화는 초기 전문 고고학자들에 의해 안데스 산맥의 침략으로 인한 것으로 여겨졌습니다. 열대 우림은 많은 인구와 복잡한 문화를 지탱하기에는 너무 열악하다고 여겨졌기 때문입니다. 그러나 마라조아라의 서식지는 테라 피르메(고지대) 열대 우림 저지대가 아니라 범람원이므로 서식지의 영향이 이전에 가정했던 것만큼 제한적일 필요는 없습니다. 이 문화는 이제 24개의 방사성 탄소 연대 측정으로 연대가 측정되었으며, 이는 문화가 관련 안데스 문화보다 이르다는 것을 보여주며 사람들의 신체 인류학은 안데스인이 아닌 아마존 인구와 관련이 있습니다. 따라서 마라조아라는 이제 열대 저지대의 지역적 발전으로 추정되어야 합니다. 마라조아라 마운드는 초기 고고학자들에 의해 순수하게 의식적인 것으로 특징지어졌지만 최근의 지구물리학적 조사와 발굴에 따르면 인접한 묘지와 쓰레기장이 있는 흙, 기둥, 초가 롱하우스로 이루어진 전체 마을을 위한 대형 플랫폼임이 밝혀졌습니다. 마운드에 있는 물고기 뼈, 씨앗, 이국적인 암석 도구는 낚시, 채집, 무역, 원예의 혼합 경제를 나타내며 발굴 과정에서 여러 탄화된 옥수수 표본이 회수되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DONGOLA', 			'동골라' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_DONGOLA_ADJ', 			'마쿠리아의' UNION ALL
SELECT 'TXT_KEY_CIV5_DONGOLA_TEXT', 				'마쿠리아는 현재 수단 북부와 이집트 남부의 누비아 지역에 위치한 중세 기독교 왕국으로 서기 6세기부터 14세기까지 번성했습니다. 수도 동골라를 중심으로 한 마쿠리아는 고대 누비아 왕국이 쇠퇴한 후 등장하여 아마도 비잔틴과 콥트의 영향을 통해 기독교를 받아들여 나일 계곡의 신앙 요새가 되었습니다. 이 왕국은 놀라운 외교적, 군사적 회복력, 특히 7세기 초기 아랍-무슬림 침략에 대한 성공적인 방어로 가장 잘 알려져 있으며, 이로 인해 이집트와 장기적인 평화 및 무역 협정인 바크트 조약이 체결되어 수 세기 동안 마쿠리아의 독립이 보존되었습니다. 전성기 동안 마쿠리아는 농업, 무역, 숙련된 장인 정신을 바탕으로 번영하는 경제를 유지했으며 독특한 누비아 기독교 문화를 발전시켰습니다. 그러나 내부 분쟁, 환경적 압력, 이슬람 영향력의 증가로 점차 왕국이 약화되어 쇠퇴하고 결국 14세기 무슬림 세력에 흡수되었습니다.' UNION ALL
