SELECT 'TXT_KEY_CITYSTATE_GONDAR_ADJ', 				'세미엔의' UNION ALL
SELECT 'TXT_KEY_CIV5_GONDAR_TEXT', 					'베타 이스라엘 왕국이라고도 불리는 세미엔 왕국은 에티오피아 제국 북서부에 집중된 베타 이스라엘 인구의 고대 왕국으로 1627년 에티오피아 황제 수세니오스 1세 통치 기간에 끝났습니다. 왕국 설립의 정확한 시기에 대해서는 의견이 분분합니다. 에티오피아 북서부에는 유대인 통치하에 있던 여러 지역이 선행되었습니다. 유대-에티오피아 전통은 세미엔 왕국의 설립을 4세기, 악슘 왕국이 에자나 왕 통치 기간에 기독교로 개종한 직후로 잡습니다. [NEWLINE][NEWLINE]베타 이스라엘 왕국의 황금기는 에티오피아 전통에 따르면 유대 왕국이 번성했던 858-1270년 사이에 일어났습니다. 그 기간 동안 세계 유대인들은 왕국을 방문한 것으로 보이는 엘다드 하-다니의 이야기를 처음 들었습니다. 마르코 폴로와 투델라의 벤야민도 그 기간의 저술에서 독립적인 에티오피아 유대 왕국을 언급합니다. 이 기간은 기독교 솔로몬 왕조의 부상으로 끝납니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GROZNY', 				'그로즈니' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GROZNY_ADJ', 				'바이나흐의' UNION ALL
SELECT 'TXT_KEY_CIV5_GROZNY_TEXT', 					'바이나흐족은 캅카스 산맥에 사는 민족 집합인 나흐족의 유일한 생존 분파입니다. 바이나흐족의 두 주요 그룹은 체첸인과 인구시인으로, 현재 더 큰 러시아 공화국 내의 각 민족 공화국에 주로 거주하고 있습니다. 바이나흐족은 고대 후르리인 및 우라르투인과 친척일 가능성이 있는 매우 오래된 민족으로, 스키타이인, 몽골인, 러시아인과 같은 그들보다 더 큰 세력의 위협을 자주 받았으며 문화와 생활 방식을 방어하고 보존하기 위해 종종 싸웠습니다. 전통적으로 바이나흐 사회 구조는 투크훔으로 알려진 군사-정치 연합을 형성한 테이프라고 알려진 고도로 민주적인 씨족을 기반으로 했습니다. 국가 규모로 기능하는 인민 의회도 있었습니다. 수많은 잔학 행위에도 불구하고 체첸인과 인구시인은 여전히 강력한 정체성과 평등과 자유에 대한 열렬한 믿음을 유지하고 있으며, 이는 그들의 전통적인 생활 방식에 필수적입니다.' UNION ALL
