SELECT 'TXT_KEY_CIV5_SOMBAKE_TEXT', 				'데네족은 주로 현재 캐나다의 광활한 얼어붙은 북부 지역 출신의 원주민이지만, 현재 미국에 속한 특정 지역, 특히 알래스카주에도 살았습니다. 치페와이언, 틀리초, 옐로나이프, 슬라비, 사투족 등 다양한 부족으로 구성되어 있지만 데네족의 범위는 이 그룹에만 국한되지 않습니다. 그렇긴 하지만, 데네족과 관련된 많은 부족이 멸종되었습니다. 예를 들어 알래스카 국경 근처의 포틀랜드 운하 지역에 위치했던 체차우트족이 있습니다. 데네족은 그들이 데넨데라고 부르는 노스웨스트 준주에 정착한 최초의 사람들이었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TURA', 				'투라' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_TURA_ADJ', 				'에벤키의' UNION ALL
SELECT 'TXT_KEY_CIV5_TURA_TEXT', 					'에벤키족은 북아시아의 원주민으로 전통적으로 러시아 시베리아의 광대한 지역과 중국 동북부 및 몽골 일부에 거주합니다. 퉁구스어족에 속하는 에벤키족은 역사적으로 반유목 순록 목축업자, 사냥꾼, 덫 사냥꾼이었으며 자연환경에 대한 깊은 지식을 통해 타이가와 툰드라에서 생존하는 데 능숙했습니다. 그들의 문화는 자연과의 조화와 정령에 대한 경외심을 강조하는 샤머니즘 신앙이 풍부합니다. 에벤키족은 17세기 러시아의 동진 확장 중에 러시아 탐험가 및 상인들과 처음 접촉했으며, 이는 모피 무역과 러시아 제국으로의 최종 편입을 포함하여 상당한 문화적, 경제적 변화를 가져왔습니다. 소련 시대의 정책은 강제 정착과 집단화를 통해 그들의 전통적인 생활 방식을 더욱 변화시켰습니다. 오늘날 에벤키족은 문화 보존 및 토지에 대한 환경 위협과 관련된 문제에 계속 직면하고 있지만 북부 유라시아의 문화 및 민족 모자이크의 중요한 부분으로 남아 있습니다.' UNION ALL
