SELECT 'TXT_KEY_CITYSTATE_TULA', 				'툴라' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_TULA_ADJ', 				'톨텍의' UNION ALL
SELECT 'TXT_KEY_CIV5_TULA_TEXT', 					'톨텍은 초기 후고전기 동안 메소아메리카를 지배했던 콜럼버스 이전 문명이었습니다. 톨텍은 메소아메리카의 가장 큰 미스터리 중 하나이며, 그들에 관한 정보는 아즈텍 신화와 고고학에서 파생된 것입니다. 나후아틀 신화는 톨텍이 장인과 군인의 제국이었으며 기술 및 문화 혁명의 시대를 열었고 아즈텍인들이 모방하고 싶어 했다고 주장합니다. 현대 학자들은 톨텍 "제국"의 존재에 회의적이지만 고고학은 역사적 수도 툴라를 중심으로 강력한 왕국이 있었음을 보여줍니다. 증거에 따르면 툴라는 수익성 있는 무역 네트워크에 접근할 수 있었으며 이 유적지에는 제국 메소아메리카 국가의 전형적인 단지, 궁전 및 도상학이 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ZENU', 				'제누' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ZENU_ADJ', 				'제누의' UNION ALL
SELECT 'TXT_KEY_CIV5_ZENU_TEXT', 					'시누라고도 알려진 제누족은 콜롬비아 북부의 원주민으로 조상 땅은 시누, 산호르헤, 카우카강의 비옥한 강 계곡에 있습니다. 그들의 문명은 대략 기원전 200년에서 서기 1600년 사이에 번성하여 아메리카 대륙에서 가장 정교한 콜럼버스 이전 수력 시스템 중 하나인 광대한 운하 네트워크와 집약적 농업 및 인구 밀집을 지원하는 밭두렁을 개발했습니다. 제누족은 또한 숙련된 금세공인으로 복잡한 사회적, 영적 삶을 반영하는 정교한 금속 세공품을 생산했습니다. 16세기 스페인이 도착하면서 정치 구조가 붕괴되었고 많은 공동체가 이주하거나 동화되었습니다. 수 세기 동안의 소외에도 불구하고 제누족은 직조 및 공동체 거버넌스를 포함한 강력한 문화적 전통을 유지해 왔으며 오늘날 콜롬비아에서 원주민 그룹으로 공식 인정받아 놀라운 공학 및 예술성의 유산을 보존하면서 토지와 문화적 권리를 되찾고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_HALICARNASSUS', 		'할리카르나소스' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_HALICARNASSUS_ADJ', 		'카리아의' UNION ALL
SELECT 'TXT_KEY_CIV5_HALICARNASSUS_TEXT', 			'카리아는 아나톨리아 서부 지역으로 이오니아 중부에서 남쪽으로 리키아까지, 동쪽으로 프리기아까지 해안을 따라 뻗어 있었습니다. 이오니아와 도리아 그리스인들은 서쪽을 식민지화하고 카리아 인구와 합류하여 그곳에 그리스가 지배하는 국가를 형성했습니다. [NEWLINE]카리아는 기원전 545년 페르시아 아케메네스 제국에 사트라피(속주)로 편입되었습니다. 가장 중요한 도시는 할리카르나소스였으며, 그곳에서 군주인 리그다미드 왕조(기원전 520-450년경)의 폭군들이 통치했습니다. 다른 주요 도시로는 라트무스(라트무스 아래 헤라클레아로 재건됨), 안티오키아, 민두스, 라오디게아, 알린다, 알라반다가 있습니다. 카리아는 페르시아 통치에 대항하여 이오니아 반란(기원전 499-493년)에 참여했습니다.[NEWLINE][NEWLINE]제2차 페르시아의 그리스 침공(기원전 480-479년) 동안 카리아의 도시들은 크세르크세스 1세의 동맹이었으며 아르테미시움 해전과 살라미스 해전에서 싸웠는데, 할리카르나소스의 여왕 아르테미시아가 70척의 카리아 선박 부대를 지휘했습니다. 테미스토클레스는 아르테미시움과 살라미스 해전 전에 이오니아인과 카리아인을 페르시아 연합에서 분리하려고 시도했습니다. 그는 그들에게 와서 자기 편이 되거나 전투에 참여하지 말라고 말했고, 만약 반란을 일으킬 수 없을 정도로 강한 강요에 묶여 있다면 전투가 시작될 때 일부러 느슨하게 하라고 말했습니다. 플루타르코스는 그의 저서 "비교 열전"의 테미스토클레스의 생애에서 다음과 같이 썼습니다. "파니아스는 테미스토클레스의 어머니가 트라키아인이 아니라 카리아 여성이었고 그녀의 이름은 에우테르페라고 썼으며, 네안테스는 그녀가 카리아의 할리카르나소스 출신이라고 덧붙였다."[NEWLINE][NEWLINE]기원전 479년 페르시아의 그리스 침공이 실패한 후 카리아의 도시들은 아테네가 주도하는 델로스 동맹의 구성원이 되었지만 기원전 428년경부터 약 1세기 동안 아케메네스 통치로 돌아갔습니다. 아케메네스 통치하에 카리아 왕조 마우솔로스는 크산토스 삼국어 비문에 나타난 것처럼 픽소다루스가 여전히 보유하고 있던 영토인 이웃 리키아를 장악했습니다.[NEWLINE][NEWLINE]할리카르나소스는 기원전 377-353년 카리아의 사트라프였던 마우솔로스를 위해 그의 아내 카리아의 아르테미시아 2세가 헌정한 유명한 마우솔레움이 있던 곳이었습니다. 이 기념물은 고대 세계 7대 불가사의 중 하나가 되었으며, 로마인들은 웅장한 무덤을 마우솔레움이라고 불렀습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ELEA', 				'엘레아' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ELEA_ADJ', 				'엘레아의' UNION ALL
SELECT 'TXT_KEY_CIV5_ELEA_TEXT', 					'벨리아는 로마인들이 기원전 540년 현재 터키 서부 해안인 이오니아의 페르시아 침공을 피해 도망친 그리스인들이 세운 고대 마을 엘레아에 붙인 이름입니다.[NEWLINE]이 마을은 티레니아해를 내려다보는 곶에 지어졌습니다. 엘레아에서는 유명한 철학자 파르메니데스가 창시하고 제논, 멜리소스, 크세노파네스, 레우키포스와 같은 철학자들이 계승한 엘레아 철학 학파가 시작되었습니다. [NEWLINE]수 세기 동안 벨리아-엘레아는 철학과 의학 분야에서 문화의 중심지였습니다. 기원전 88년 이 마을은 로마 마을이 되었고 그 후 바다에서 가져온 모래로 두 항구가 덮이면서 쇠퇴했습니다. 주변 지역은 습지에 삼켜졌고 주민들은 해안을 떠나 바다에서 더 멀리 정착하여 오늘날에도 노비 벨리아라고 불리는 마을을 세웠습니다. [NEWLINE][NEWLINE]1998년 칠렌토 및 발로 디 디아노 국립공원은 파에스툼과 벨리아의 고고학 유적지, 파둘라의 체르토사와 함께 유네스코 세계문화유산 목록에 포함되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SANGGYEONG', 			'상경' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SANGGYEONG_ADJ', 			'발해의' UNION ALL
SELECT 'TXT_KEY_CIV5_SANGGYEONG_TEXT', 				'발해 왕국은 반유목 말갈족, 거란족, 한국어 사용 공동체의 정치적 연합으로, 오랫동안 지속된 고구려 왕국을 계승하여 전 고구려 장군이자 말갈 족장인 대조영(재위 699 - 719년)이 건국한 때부터 926년 거란 연합에 정복될 때까지 지속되었습니다. 전성기에는 영토가 현대 러시아 극동 깊숙이 뻗어 있었고 한반도 북부를 포함했으며 중국 북동부의 랴오강까지 확장되었습니다. 중국, 일본, 한국 학자들에 의해 각각 당나라 속국, 일본 천황의 꼭두각시, 한민족 국가로 다양하게 분류되지만, 고고학, 언어학, 역사학에서 입증된 바와 같이 발해는 11세기 중반 최종 후계 국가인 흥요국이 멸망할 때까지 지속될 공통의 정체성을 확립한 독특한 다민족 국가 형성 실험이었습니다.' UNION ALL
