SELECT 'TXT_KEY_CITYSTATE_NELEMNOYE_ADJ', 			'유카기르의' UNION ALL
SELECT 'TXT_KEY_CIV5_NELEMNOYE_TEXT', 				'유카기르인은 시베리아 북동부의 원주민으로 주로 콜리마강 유역과 러시아 극동의 다른 지역에 거주합니다. 역사적으로 유카기르인은 사냥, 낚시, 순록 목축을 기반으로 한 생활 방식을 가진 이 지역의 지배적인 그룹 중 하나였습니다. 그들은 시베리아에서 가장 오래된 언어 중 하나로 간주되는 유카기르어족 내의 여러 언어를 사용했습니다. 중세 시대에 그들은 이웃 민족과 무역을 했으며 비교적 자율적으로 살았습니다. 그러나 17세기 러시아 탐험가와 상인이 도착한 후 그들의 수와 문화적 명성은 쇠퇴하기 시작했습니다. 러시아 모피세(야삭)의 부과와 천연두와 같은 질병의 확산은 인구를 크게 줄이고 전통적인 생활 방식을 혼란에 빠뜨렸습니다. [NEWLINE][NEWLINE]20세기까지 유카기르인은 소수 민족이 되었으며 결혼과 사회정치적 압력으로 인해 야쿠트인과 에벤키인과 같은 이웃 그룹에 동화되었습니다. 소련 정책은 유카기르인이 종종 집단 농장으로 이주되고 전통 관행이 억압되면서 소외에 더욱 기여했습니다. 오늘날 유카기르인이라고 밝히는 사람은 수백 명에 불과하며 두 가지 주요 방언인 툰드라와 콜리마 유카기르어는 심각한 멸종 위기에 처해 있습니다. 구전 전통, 민속, 자연환경과의 연결을 보존하는 데 대한 관심이 높아지면서 언어와 문화를 활성화하려는 노력이 이루어지고 있습니다. 유카기르인은 이제 러시아의 원주민 소수 민족 중 하나로 인정받아 문화적, 경제적 권리를 보호하기 위해 고안된 특정 법적 보호의 혜택을 받고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ORUGALLU', 			'오루갈루' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ORUGALLU_ADJ', 			'카카티야의' UNION ALL
SELECT 'TXT_KEY_CIV5_ORUGALLU_TEXT', 				'카카티야 왕조는 12세기에서 14세기 사이에 데칸 동부 대부분을 통치했던 인도 왕조였습니다. 초기 카카티야 통치자들은 2세기 이상 라슈트라쿠타와 서부 찰루키아의 봉신으로 봉사했습니다. 그들은 1163년 프라타파루드라 1세 하에서 주권을 장악했습니다. 가나파티 데바는 1230년대에 카카티야 영토를 크게 확장했습니다. 가나파티 데바는 루드라마 데비가 계승하여 야다바의 공격을 성공적으로 격퇴했습니다. 1310년 와랑갈 포위 공격이 성공한 후 프라타파루드라 2세는 델리에 연공을 바쳐야 했습니다. 1323년 울루그 칸의 또 다른 공격으로 카카티야 군대의 거센 저항이 있었지만 결국 패배했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MATURUCA', 			'마투루카' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MATURUCA_ADJ', 			'마쿠시의' UNION ALL
SELECT 'TXT_KEY_CIV5_MATURUCA_TEXT', 				'마쿠시, 마쿠시, 마쿠시, 마쿠시, 마쿠시, 마쿠시, 테우에이아, 테웨야 사람들은 가이아나 남부, 브라질 북부, 베네수엘라 동부의 국경 지대에 사는 원주민입니다. 그들의 구전 역사는 그들을 태양의 후손으로 묘사하며 식민지화 이전에는 반유목민이었습니다. [NEWLINE]마쿠시는 트랙과 길로 연결된 마을에 살며 집은 중앙 안뜰 주위에 지어졌습니다. 마쿠시는 이동 경작 및 물고기 중독과 같은 사냥 및 농업 방법을 실천합니다. 이 지역의 다른 원주민 그룹과 마찬가지로 마쿠시 전통 생활은 마쿠시 문화에서 키세라로 알려진 쓴 카사바에 크게 의존합니다. 이 식물과 관련된 작업은 일반적으로 성별로 나뉩니다. 남성은 전통적으로 땅을 개간하고 여성은 돌보고 수확합니다. 결혼하면 마쿠시 부부는 아내 가족의 마을에 살며 장인은 마쿠시 친족 관계에서 매우 중요합니다. [NEWLINE]마쿠시에 대한 최초의 기록은 1740년 브라질인들에게 로우렌수 벨포르테로 알려진 아일랜드인 란셀롯 벨포르테가 이끄는 루소-브라질 노예 습격의 맥락에서였습니다. 1700년대부터 1800년대 후반까지 마쿠시는 브라질의 습격으로 북쪽으로, 네덜란드와 영국의 대리인인 카리브족과 아카와이오족에 의해 남쪽으로 밀려나 루푸누니 사바나로 영토가 제한되었습니다. 마쿠시가 자신의 동족을 노예로 팔았다는 보고가 있지만, 이는 강압에 의한 것이라는 점도 지적되었습니다. 1800년대에 마쿠시는 "해먹, 다양한 공예품, 강력한 형태의 큐라레 생산을 전문으로" 했으며, 이는 종종 카사바 강판과 취관을 대가로 이 지역의 다른 아메리카 원주민 그룹과 거래되었습니다.' UNION ALL
