SELECT 'TXT_KEY_CITYSTATE_ASHDOD_ADJ', 				'블레셋의' UNION ALL
SELECT 'TXT_KEY_CIV5_ASHDOD_TEXT', 					'블레셋 사람들은 기원전 12세기, 이스라엘 사람들이 도착할 무렵 팔레스타인 남부 해안에 정착한 그리스 기원의 사람들이었습니다. 성서 전통에 따르면 블레셋 사람들은 캅톨(아마도 크레타)에서 왔습니다. 그들은 기원전 1190년경 아나톨리아, 키프로스, 시리아를 황폐화시킨 후 이집트를 침공한 바다 민족 중 하나인 prst로 이집트 기록에 언급되어 있습니다. 이집트인들에게 격퇴당한 후 그들은 요파(현대 텔아비브-야포)에서 가자 지구까지 남쪽으로 팔레스타인 해안 평야를 점령했습니다. 이 지역에는 블레셋 연맹의 5개 도시(펜타폴리스)(가자, 아스켈론[아스칼론], 아스도드, 가드, 에크론)가 포함되어 있었으며 블레셋 땅, 즉 블레셋 사람들의 땅으로 알려졌습니다. 나중에 그리스인들이 나라 전체를 팔레스타인이라고 부르게 된 것은 이 명칭에서 유래했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ITHACA', 				'알랄코메나이' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ITHACA_ADJ', 				'이타카의' UNION ALL
SELECT 'TXT_KEY_CIV5_ITHACA_TEXT', 					'이타카는 그리스 본토 서해안에 위치한 이오니아해의 작은 그리스 섬으로, 호메로스의 오디세이아의 영웅 오디세우스의 전설적인 고향으로 유명합니다. 섬의 험준한 언덕, 깊은 만, 올리브로 뒤덮인 경사면은 오랫동안 트로이 전쟁 후 오디세우스의 귀향이라는 서사시와 연관되어 서양 문학에서 갈망, 인내, 귀환의 강력한 상징이 되었습니다. 역사적으로 이타카는 청동기 시대부터 사람이 거주했으며 미케네 세계의 일부였을 가능성이 높으며 고대 해상 무역로에서 작지만 전략적으로 위치한 섬 역할을 했습니다. 나중에 로마, 비잔틴, 베네치아, 영국을 포함한 다양한 세력의 통제를 받다가 1864년 나머지 이오니아 제도와 함께 현대 그리스의 일부가 되었습니다. 오늘날 이타카는 자연의 아름다움, 고요한 마을, 깊은 신화적 유산으로 유명하며 역사와 호메로스 모험의 시대를 초월한 정신을 모두 찾는 방문객을 끌어들입니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_NGYLVO', 				'응길보' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_NGYLVO_ADJ', 				'니브흐의' UNION ALL
SELECT 'TXT_KEY_CIV5_NGYLVO_TEXT', 					'니브흐족은 러시아 극동의 원주민으로 주로 사할린섬 북부와 아무르강 하류 유역에 거주합니다. 전통적으로 그들은 반유목 사냥꾼, 어부, 채집가로 살았으며 이 지역의 풍부한 연어와 기타 해양 자원에 크게 의존했습니다. 니브흐족은 풍부한 구전 전통, 복잡한 장인 정신, 환경과 밀접하게 연결된 정령 숭배 신앙을 가진 독특한 문화를 발전시켰습니다. 그들은 17세기 러시아 탐험가들이 무역을 시작하고 아무르 유역의 원주민들로부터 공물을 징수하기 시작할 때까지 외부 그룹과 제한적으로 접촉했습니다. 이 초기 접촉은 종종 전통 경제를 혼란에 빠뜨리고 사회에 외국의 영향을 도입했습니다. [NEWLINE][NEWLINE]소련 시대에 니브흐족은 상당한 문화적, 사회적 격변을 겪었습니다. 집단화 및 강제 정착 정책은 전통적인 생활 방식을 변화시켰습니다. 또한 원주민 인구를 동화시키려는 노력에는 모국어와 전통 억압이 포함되었습니다. 그 결과 알려진 언어적 친척이 없는 고립어로 간주되는 니브흐어는 멸종 위기에 처하게 되었고 러시아어가 주 언어로 지배하게 되었습니다. 이러한 어려움에도 불구하고 니브흐족은 문화적 정체성의 요소를 유지했으며 최근의 이니셔티브는 언어와 전통을 활성화하려고 노력했습니다. 오늘날 니브흐족은 러시아의 원주민 소수 민족 중 하나로 인정받고 있으며 현대의 도전 속에서 유산을 보존하기 위한 노력이 진행 중입니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CAILIN', 				'카일린' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_CAILIN_ADJ', 				'초노의' UNION ALL
SELECT 'TXT_KEY_CIV5_CAILIN_TEXT', 					'초노 또는 과이테코는 칠로에, 과이테카스, 초노스 군도의 유목 원주민 또는 민족 그룹이었습니다. 초노 사람들은 카누를 타고 여행하는 수렵 채집인으로 살았습니다. 스페인 소스에서 초노에 대해 알려진 것의 대부분은 윌리체(남부 마푸체) 세계관을 통해 걸러지는데, 윌리체와 윌리체 언어가 초노와 소통하는 데 사용되었기 때문입니다. 초노 사람들은 칠로에 군도의 최초의 민족적으로 식별 가능한 거주자로 여겨지며, 이는 초노가 칠로에의 풍부한 조개무덤 대부분을 남긴 사람들이라는 가정으로 이어졌습니다. 스페인 사람들이 도착했을 때 군도의 주요 원주민 언어는 벨리체였음에도 불구하고 칠로에에는 초노 어원을 가진 다양한 지명이 있습니다. 따라서 일부 역사학자들은 오소르노 해안과 양키우에 호수 북쪽까지의 장소가 한때 초노 유목 범위 내에 있었다고 생각합니다. 초노 사람들은 1553년 프란시스코 데 울로아의 해군 원정대가 그들의 땅에 도착했을 때 처음으로 유럽인을 만났습니다. 16세기 후반과 17세기 초반에 초노를 칠로에의 스페인 영토로 데려오기 위한 다양한 스페인 침략이 있었습니다. 이러한 침략은 "원주민 반란군"의 노예화를 합법화한 스페인 펠리페 3세의 1608년 법령 이후 노골적인 노예 습격으로 바뀌었습니다. 초노 땅에 대한 관심은 1740년대 스페인 사람들이 파타고니아 서부의 웨이저섬에서 영국 군함 HMS 웨이저호의 난파 소식을 알게 되었을 때 다시 일어났습니다. 해적과 해적의 위협으로 인해 스페인 당국은 적들이 원주민들로부터 어떤 지원도 받지 못하도록 초노와 과이테카 군도의 인구를 줄이도록 명령했습니다. 이로 인해 인구가 북쪽의 칠로에 군도로 이동하고 일부 초노는 타이타오 반도 남쪽으로 이동하여 사실상 영토의 인구가 감소했습니다. 칠로에의 초노는 결국 그곳의 메스티소와 원주민 윌리체 인구에 흡수되었습니다. 초노는 18세기 이후 역사 기록에서 거의 사라졌지만 산발적인 언급은 남아 있었습니다. 초노와 강력한 역사적 연관성이 있는 라이텍섬 주민들은 평균 80%의 원주민 유전적 혼합을 가지고 있습니다. 멜링카 주민들이 여행할 때 개를 배에 태우는 관습은 초노 전통에 뿌리를 두고 있을 수 있습니다.' UNION ALL
