SELECT 'TXT_KEY_CITYSTATE_PAPEETE_ADJ', 			'타히티의' UNION ALL
SELECT 'TXT_KEY_CIV5_PAPEETE_TEXT', 				'프랑스령 폴리네시아에서 가장 큰 섬인 타히티는 기원전 200년경 동남아시아나 인도네시아에서 피지, 사모아, 통가 군도를 거쳐 긴 이주 끝에 정착되었습니다. 수백 킬로미터의 바다를 건너는 이 이주는 길이가 20~30미터에 달하고 가족과 가축을 운송할 수 있는 아웃리거 카누를 사용하여 가능했습니다. [NEWLINE][NEWLINE]타히티 사회는 다양한 씨족 간의 친족 관계와 군사력을 기반으로 한 추장국과 영토로 구성되었습니다. 씨족은 추장(알리이 라히), 귀족(아리이), 하급 추장이 이끌었습니다. 이 문화는 번성했고 타히티는 종교 의식을 위한 마라에(사원) 건설로 특징지어지는 폴리네시아 항해와 영성의 중심지가 되었습니다. [NEWLINE]유럽과의 접촉은 18세기에 1767년 새뮤얼 월리스와 1769년 제임스 쿡을 포함한 영국 탐험가들의 도착으로 시작되었고 프랑스인들이 뒤를 따랐습니다. 이러한 만남은 기독교 도입, 신기술, 지역 인구에 큰 영향을 미친 질병을 포함하여 극적인 변화를 가져왔습니다. [NEWLINE][NEWLINE]19세기 중반까지 타히티는 프랑스의 통제하에 들어갔고 1842년 프랑스 보호령이 되었으며 나중에 1880년 공식 식민지가 되었습니다. 프랑스의 영향력은 인프라 개발을 가져왔지만 전통적인 타히티 문화를 억압하기도 했습니다. 저항 기간에도 불구하고 타히티를 포함한 프랑스령 폴리네시아는 1946년 프랑스의 해외 영토가 되어 주민들에게 프랑스 시민권을 부여했습니다. [NEWLINE]오늘날 타히티는 폴리네시아 전통과 프랑스 문화 요소가 독특하게 혼합되어 있으며 경제는 관광, 흑진주 양식, 프랑스 정부 지원에 의존합니다. 이 섬은 활기찬 문화유산, 놀라운 자연의 아름다움, 현대적 정체성을 계속 형성하는 역사로 유명합니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANGAAS', 			'망가스' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MANGAAS_ADJ', 			'바누아투의' UNION ALL
SELECT 'TXT_KEY_CIV5_MANGAAS_TEXT', 				'바누아투는 약 3300년 전에 정착한 라피타 문화에 의해 처음 정착되었습니다. 그들은 주목할 만한 도자기를 가져왔고 에파테, 말라쿨라, 아오레에서 거주 흔적이 발견되었습니다. 바누아투에서 그들은 피지와 사모아로 항해했습니다. 그러나 시간이 지남에 따라 라피타의 단결력은 약해졌고 결국 바누아투는 멜라네시아의 나머지 지역과 고립되었습니다. 바누아투는 1606년 페드로 페르난데스 데 키로스가 처음 방문했는데, 그는 자신이 "테라 오스트랄리스"에 상륙했다고 믿고 스페인을 위해 섬을 차지했습니다. 그러나 스페인의 영향력은 곧 사라졌고 스페인 사람들은 섬을 떠났습니다. 유럽인들은 1768년 루이 앙투안 드 부갱빌이 방문할 때까지 바누아투를 다시 방문하지 않았습니다. 제임스 쿡은 1774년 방문했을 때 바누아투를 "뉴헤브리디스"라고 명명했으며 독립할 때까지 그 이름이 사용되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_TARTESSOS', 			'타르테소스' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_TARTESSOS_ADJ', 			'타르테소스의' UNION ALL
SELECT 'TXT_KEY_CIV5_TARTESSOS_TEXT', 				'타르테소스는 이베리아반도 남부의 고대 문명으로, 기원전 9세기에서 6세기 사이에 현재의 스페인 안달루시아에서 번성했습니다. 부유하고 세련된 사회로 알려진 타르테소스는 종종 과달키비르강 주변 지역과 관련이 있습니다. 그 사람들은 야금술에 능숙하여 금, 은, 청동을 생산하여 지중해 세계에서 유명해졌습니다. 타르테소스는 기원전 1100년경에 도착한 페니키아 정착민들과 무역을 하여 동양의 문화적, 기술적 영향을 도입했습니다. 문명의 명성은 그리스와 로마 소스에 언급되어 있으며, 전설에서는 종종 아르간토니오스로 확인되는 반신화적인 왕이 통치하는 막대한 부의 땅으로 묘사합니다. [NEWLINE][NEWLINE]기원전 6세기까지 타르테소스는 아마도 내부 불안정, 카르타고의 부상, 지중해 무역로의 변화로 인해 쇠퇴하기 시작했습니다. 고고학적 증거와 고대 문헌에 따르면 그 사회는 결국 다른 이베리아 문화에 흡수되거나 대체되었습니다. 정확한 위치는 불확실하지만 일부 학자들은 갑작스러운 소멸로 인해 타르테소스를 아틀란티스 신화와 연결합니다. 현대 연구는 이 수수께끼 같은 문명을 조명하는 유물과 유적지를 계속 발굴하여 고대 지중해와 이베리아 원주민 사이의 문화적, 경제적 가교로서의 역할을 드러내고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_AGADEZ', 				'아가데즈' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_AGADEZ_ADJ', 				'아가데즈의' UNION ALL
SELECT 'TXT_KEY_CIV5_AGADEZ_TEXT', 					'아이르 술탄국은 현재 니제르의 아이르 산맥 지역에 위치한 역사적인 왕국이었습니다. 15세기에 등장하여 사하라 무역 네트워크에서 중요한 역할을 했습니다. [NEWLINE]아이르 술탄국은 이 지역의 유목 목축업자이자 상인이었던 투아레그족에 의해 설립되었습니다. 아메노칼로 알려진 아이르의 술탄은 이 지역의 투아레그 부족에 대해 상당한 정치적, 종교적 권위를 가졌습니다. 그들은 술탄국의 수도 역할을 했던 아가데즈 시에서 통치했습니다. [NEWLINE]아이르의 술탄은 사하라 사막을 서아프리카 및 북아프리카와 연결하는 중요한 무역로를 통제했습니다. 그들은 소금, 금, 상아, 노예 및 기타 상품의 교환을 촉진했습니다. 술탄국은 이러한 수익성 있는 무역로를 통제하여 부유하고 강력해졌습니다. [NEWLINE]역사 전반에 걸쳐 아이르 술탄국은 이웃 제국과 국가로부터 다양한 도전에 직면했습니다. 종종 송가이 제국, 풀라니 국가 및 기타 지역 강대국과의 동맹 및 갈등을 헤쳐나가야 했습니다. [NEWLINE]19세기에 술탄국은 유럽 식민지 열강과 접촉하게 되었습니다. 처음에는 프랑스의 식민지 침략에 저항했지만 결국 프랑스의 영향력에 굴복했습니다. 1904년 아이르 술탄국은 공식적으로 프랑스 식민 제국의 일부가 되었습니다. [NEWLINE]식민지화 이후 술탄의 전통적인 권력은 약화되었지만 식민지 행정의 틀 내에서 어느 정도 영향력을 유지했습니다. 이 지역은 더 큰 프랑스령 서아프리카의 일부가 되었고 나중에 1960년 독립한 후 니제르가 되었습니다. [NEWLINE]오늘날 아이르 술탄국은 투아레그족과 니제르 국가에 문화적, 역사적 중요성을 지니고 있습니다. 투아레그족은 음악, 장인 정신, 독특한 유목 생활 방식을 포함한 고유한 문화적 전통을 계속 유지하고 있습니다. 아가데즈 시는 역사적인 건축물과 투아레그 유산에서의 역할로 알려진 중요한 문화 중심지이자 유네스코 세계문화유산으로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GONUR', 				'고누르 데페' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GONUR_ADJ', 				'옥수스의' UNION ALL
SELECT 'TXT_KEY_CIV5_GONUR_TEXT', 					'박트리아-마르기아나 고고학적 복합체(BMAC)라고도 알려진 옥수스 문명은 대략 기원전 2300년에서 1700년 사이에 중앙아시아에서 번성했던 청동기 시대 문화로, 현대 투르크메니스탄, 우즈베키스탄, 아프가니스탄 북부, 이란 일부에 걸쳐 있었습니다. 무르가브강과 아무다리야(옥수스)강의 비옥한 오아시스를 중심으로 요새화된 도시, 기념비적 건축물, 정교한 금속 세공품, 메소포타미아, 인더스 계곡, 이란 고원을 연결하는 활발한 무역 네트워크를 특징으로 하는 선진 도시 정착지를 개발했습니다. 옥수스 사람들은 관개 기반 농업을 실천하고 복잡한 사회 및 영적 시스템을 암시하는 독특한 도자기, 인장, 종교 유물을 특징으로 하는 풍부한 물질문화를 유지했습니다. 문명은 결국 쇠퇴했지만(아마도 환경 변화, 무역로의 변화, 인도-이란 민족의 이주로 인해), 그 영향력은 지속되어 후기 중앙아시아 및 페르시아 문명의 문화적 토대에 기여했습니다. 옥수스 유적지는 1969-1979년 아프가니스탄 북부에서 발굴 작업을 하던 소련 고고학자 빅토르 사리아니디에 의해 발견되고 명명되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_ISCA', 				'이스카' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_ISCA_ADJ', 				'둠노니아의' UNION ALL
SELECT 'TXT_KEY_CIV5_ISCA_TEXT', 					'디프네인트라고도 알려진 둠노니아는 현재 영국 남서부의 콘월과 데본 일부에 위치한 중세 왕국이었습니다. 서기 5세기부터 9세기까지 존재했으며 켈트족 둠노니 부족과 관련이 있었습니다. [NEWLINE]둠노니아의 역사는 광범위하게 기록되어 있지 않지만 영국의 로마 영향력이 약해지면서 로마 이후 시대에 설립된 것으로 여겨집니다. 켈트족인 둠노니족은 로마 철수 후에도 이 지역에 대한 통제권을 유지하고 고유한 문화적, 정치적 정체성을 계속 유지했을 가능성이 큽니다. [NEWLINE]둠노니아는 주로 농촌 및 농업 사회였으며 인구는 농업, 어업, 무역에 종사했습니다. 웨일스와 브르타뉴와 같은 다른 켈트 지역과 긴밀한 관계를 맺고 문화적, 언어적 연결을 유지했습니다. [NEWLINE]둠노니아 왕국은 존재하는 동안 다양한 외부 압력에 직면했습니다. 영국에서 영토를 확장하고 있던 앵글로색슨족을 포함한 이웃 왕국과의 침략과 갈등을 자주 겪었습니다. 앵글로색슨족의 침략은 결국 둠노니아의 분열과 쇠퇴로 이어졌습니다. [NEWLINE]9세기까지 둠노니아는 앵글로색슨 왕조가 통치하는 확장하는 웨섹스 왕국에 흡수되거나 통합되었습니다. 둠노니아가 더 큰 웨섹스 왕국으로 통합되면서 둠노니아라는 별개의 정치적 실체는 끝났습니다. [NEWLINE]그럼에도 불구하고 둠노니아의 문화적 유산은 콘월과 그 인근 지역에서 지속되었습니다. 웨일스어 및 브르타뉴어와 밀접한 관련이 있는 콘월어는 중세 후기까지 콘월 일부 지역에서 계속 사용되었습니다. 콘월 민속, 전통, 지명에도 고대 둠노니아 문화의 흔적이 남아 있습니다. [NEWLINE]최근 몇 년 동안 콘월어 정체성과 문화에 대한 관심이 부활하여 콘월어를 보존 및 부활시키고 둠노니아 유산에 대한 인식을 증진하려는 노력이 있었습니다. 오늘날 콘월은 영국 내에서 독특한 문화적 정체성을 유지하고 있으며 둠노니아는 역사적 유산의 중요한 부분으로 인정받고 있습니다.' UNION ALL
