SELECT 'TXT_KEY_CITYSTATE_SA_HUYN_ADJ', 			'사후인의' UNION ALL
SELECT 'TXT_KEY_CIV5_SA_HUYN_TEXT', 				'사후인 문화는 기원전 1000년경부터 서기 200년까지 베트남 중부와 남부에서 번성했던 고대 철기 시대 문명으로 초기 베트남 국가의 부상보다 앞서 있습니다. 독특한 독무덤 관행, 정교한 청동 및 철 도구, 고도로 장식된 도자기로 유명하며, 이는 진보된 장인 정신과 복잡한 사회를 나타냅니다. 사후인 사람들은 해안 및 내륙 무역에 종사하여 수입 구슬, 조개껍데기 및 기타 유물의 발견으로 입증된 바와 같이 필리핀, 인도네시아, 태국을 포함한 동남아시아 전역의 지역과 연결되었습니다. 그들의 사회는 조상 숭배와 정교한 장례 의식을 포함하여 강력한 영적 및 의식 전통을 가진 작은 공동체로 조직된 것으로 보입니다. 문화는 점차 후속 비엣 및 참파 문명으로 진화하거나 영향을 미쳐 베트남의 고고학 및 문화사에 지속적인 유산을 남겼습니다.' UNION ALL
