SELECT 'TXT_KEY_CIV5_WAITIKUBULI_TEXT', 			'섬 카리브족 또는 단순히 카리브족으로도 알려진 칼리나고족은 카리브해 소앤틸리스 제도의 원주민입니다. 스페인과 접촉할 당시 카리브족은 카리브해의 지배적인 그룹 중 하나였으며 카리브해라는 이름은 그들에게서 유래했습니다. 그들은 윈드워드 제도, 도미니카, 그리고 아마도 남부 리워드 제도 전역에 살았습니다. 역사적으로 그들의 조상은 이그네리로 알려진 이전 거주자들로부터 섬을 정복한 본토 카리브족이라고 생각되었습니다.[NEWLINE][NEWLINE]초기 식민지 시대에 카리브족은 이웃 섬을 습격하는 전사로 명성을 얻었습니다. 초기 유럽인들은 그들이 식인 풍습을 실천했다고 주장했습니다. "식인종(cannibal)"이라는 단어는 그들의 이름이 변형된 것에서 유래했습니다. 오늘날 카리브족과 그 후손들은 앤틸리스 제도에 계속 살고 있습니다. [NEWLINE][NEWLINE]신대륙의 대부분의 원주민과 마찬가지로 칼리나고족은 아메리카의 유럽 식민지화와 유럽 정복으로 큰 고통을 겪었으며 그 후손들은 현재 카리브해와 남미 전역에 흩어져 있으며 가장 큰 그룹은 영국이 그들을 위해 보호구역을 설립한 도미니카섬에 살고 있습니다.[NEWLINE][NEWLINE]오늘날 카리브족은 문화를 보존하고 자녀와 다른 사람들에게 전통에 대해 교육하며 정체성을 유지하는 동시에 현대 사회의 일원이 되기 위해 노력하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LUANGPRABANG', 		'루앙프라방' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_LUANGPRABANG_ADJ', 		'라오의' UNION ALL
SELECT 'TXT_KEY_CIV5_LUANGPRABANG_TEXT', 			'고고학적 증거에 따르면 메콩강을 따라 정착한 사람들은 기원전 3000년경에 농업, 야금술, 도자기 제작을 배웠지만 오늘날 라오스라는 이름을 가진 땅의 초기 역사에 대해서는 알려진 바가 거의 없습니다. 저지대 라오족은 8세기에 남쪽으로 밀려난 태국 부족의 후손으로 여겨집니다. 전승에 따르면 란쌍("백만 마리의 코끼리")이라는 왕국은 756년 쿤로 왕에 의해 세워졌습니다. 1353년 캄푸치아의 앙코르 궁정에서 자랐고 크메르 군대와 함께 돌아온 파응움에 의해 재통일되었습니다. 그는 또한 라오스에 소승 불교를 도입한 것으로 알려져 있습니다. 란쌍은 크메르, 버마, 베트남, 태국과 간헐적인 전쟁을 벌였으며 효과적인 행정 시스템, 정교한 군사 조직, 이웃 국가와의 활발한 상업을 발전시켰습니다. 1707년 내부 불화로 인해 란쌍은 북쪽의 루앙프라방(현재의 상부 라오스)과 남쪽의 비엔티안(하부 라오스)이라는 두 왕국으로 분열되었습니다. 강력한 이웃 국가들은 이 분열을 이용하여 이 지역을 침공했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KANONWALOHALE', 		'카논왈로할레' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_KANONWALOHALE_ADJ', 		'오나이다의' UNION ALL
SELECT 'TXT_KEY_CIV5_KANONWALOHALE_TEXT', 			'하우데노사우니 연맹(이로쿼이 연맹이라고도 함)의 원래 5개 국가 중 하나인 오나이다족은 현재 미국의 북동부 삼림 지대에 뿌리를 둔 긴 역사를 가지고 있습니다. 전통적으로 그들은 현대 뉴욕주 중부 주변 지역에 거주했습니다. "서 있는 돌의 사람들"로 알려진 오나이다족은 위대한 평화의 법을 통해 회원국 간의 평화와 단결을 유지하기 위해 설립된 연맹에서 중심적인 역할을 했습니다. 그들은 씨족 어머니와 추장 협의회가 통치하는 모계 사회를 실천했으며 농업, 사냥, 낚시를 통해 생계를 유지했습니다. 17세기 유럽과의 접촉은 무역 관계, 기독교 확산, 식민지 시대의 갈등을 포함한 중대한 변화를 가져왔습니다. [NEWLINE][NEWLINE]미국 독립 전쟁 동안 오나이다족은 하우데노사우니 중 유일하게 미국 식민지 개척자 편에 서서 중추적인 오리스카니 전투를 포함하여 결정적인 지원을 제공했습니다. 그러나 이 동맹은 전쟁 중에 그들의 땅과 마을이 황폐화되면서 큰 대가를 치렀습니다. 전후 조약은 종종 그들의 땅을 빼앗아 이주와 소외로 이어졌습니다. 19세기까지 많은 오나이다족이 위스콘신, 온타리오 및 기타 지역으로 이주했지만 일부는 뉴욕에 남았습니다. 오늘날 오나이다 국가는 문화, 언어, 전통을 활성화하고 있으며 미국과 캐나다의 공동체는 유산의 관리자 역할을 하고 주권과 자결권을 증진하는 데 중요한 역할을 하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PSKOV', 				'프스코프' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_PSKOV_ADJ', 				'프스코프의' UNION ALL
SELECT 'TXT_KEY_CIV5_PSKOV_TEXT', 					'프스코프 공화국은 현재 러시아 북서부의 프스코프 시를 중심으로 한 중세 루스 정치체였습니다. 12세기에 자치 지역으로 등장하여 노브고로드 공화국과의 관계에서 성장했습니다. 14세기까지 프스코프는 더 큰 독립을 달성하여 한자 동맹 경로를 따라 중요한 무역 허브로 자리 잡았습니다. 베체(인민 의회)를 통해 통치되는 공화국은 참여 민주주의의 한 형태를 실천했으며, 엄격한 베체 감독하에 군사 지도자이자 사법 인물로 봉사한 공작을 포함한 선출직 관리가 있었습니다. 프스코프의 전략적 위치와 상징적인 프스코프 크렘린(크롬)과 같은 잘 요새화된 건축물은 수많은 외세의 침략, 특히 리보니아 기사단과 리투아니아의 침략을 견딜 수 있게 했습니다. [NEWLINE][NEWLINE]자치권에도 불구하고 프스코프 공화국은 모스크바의 중앙 집권 세력으로부터 점점 더 큰 압력에 직면했습니다. 1510년 모스크바의 바실리 3세 대공은 프스코프를 합병하여 독립을 끝내고 중앙 집권화된 러시아 국가에 편입시켰습니다. 합병은 프스코프의 독특한 정치적 정체성의 쇠퇴를 알렸지만 건축 및 문화 유산은 러시아 역사에 계속 영향을 미쳤습니다. 오늘날 교회와 요새를 포함한 프스코프의 중세 기념물은 격동의 중세 시대 동안 무역, 통치, 회복력의 중심지로서의 풍부한 유산을 상기시켜 줍니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_YAMBIO', 				'얌비오' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_YAMBIO_ADJ', 				'잔데의' UNION ALL
SELECT 'TXT_KEY_CIV5_YAMBIO_TEXT', 					'아잔데족(잔데어로는 "잔데"의 복수형)은 북중부 아프리카의 민족 그룹입니다. 그들은 주로 콩고 민주 공화국 북동부, 남수단 중남부 및 남서부, 중앙아프리카 공화국 남동부에 거주합니다. 19세기 초 반디아 사람들은 붕가라를 통치했고 두 그룹은 아잔데 사람이 되었습니다. 그들은 현재 중앙아프리카 공화국 남동부의 사바나에 살았습니다. 왕이 죽은 후 왕의 아들들은 계승을 위해 싸웠습니다. 패배한 아들은 종종 이웃 지역에 왕국을 세워 아잔데 왕국을 동쪽과 북쪽으로 확장했습니다. 수단의 습격은 19세기 후반에 북쪽 확장의 일부를 중단시켰습니다. 아잔데족은 벨기에, 프랑스, 앵글로-이집트 수단에 의해 분열되었습니다. 아잔데라는 단어는 "많은 땅을 소유한 사람들"을 의미하며 정복 전사로서의 역사를 나타냅니다. 변형 철자로는 Adio, Zande, Zandeh, A-Zandeh 및 Sandeh가 있습니다. 니암-니암이라는 이름은 18세기와 19세기 초에 외국인들이 아잔데족을 지칭하기 위해 자주 사용했습니다. 이 이름은 아마도 딩카어에서 유래했을 것이며 그 언어로 "대식가"를 의미하며 식인 성향을 나타내는 것으로 추정됩니다. 아잔데족에 대한 이 이름은 남수단의 다른 부족들이 사용하다가 나중에 서양인들이 채택했습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PAVIA', 				'파비아' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_PAVIA_ADJ', 				'롬바르드의' UNION ALL
SELECT 'TXT_KEY_CIV5_PAVIA_TEXT', 					'롬바르드족 또는 랑고바르드족은 568년부터 774년까지 이탈리아를 통치한 게르만 부족이었습니다. 롬바르드족은 새로운 땅을 찾아 이주하기 전에 스칸디나비아 남부에 거주했던 윈닐리라는 작은 부족의 후손입니다. 5세기 말까지 그들은 다뉴브강 북쪽의 현대 오스트리아와 대략 일치하는 지역으로 이동했습니다. 롬바르드 왕 아우도인은 551년 또는 552년에 게피드 지도자 투리신트를 패배시켰습니다. 그의 후계자 알보인은 결국 567년 아스펠트 전투에서 게피드족을 파괴했습니다. 이 승리 후 알보인은 비잔틴 제국과 동고트 왕국 사이의 긴 고트 전쟁(535-554) 이후 심각하게 인구가 감소하고 황폐해진 이탈리아로 백성을 이끌기로 결정했습니다. 롬바르드족에는 수많은 색슨족, 헤룰족, 게피드족, 불가르족, 튀링겐족, 동고트족이 합류했으며 그들의 이탈리아 침공은 거의 저항을 받지 않았습니다. 569년 말까지 그들은 572년에 함락된 파비아를 제외하고 포강 북쪽의 모든 주요 도시를 정복했습니다. 동시에 그들은 이탈리아 중부와 남부 지역을 점령했습니다. 그들은 이탈리아에 롬바르드 왕국을 세웠고 나중에 레그눔 이탈리쿰("이탈리아 왕국")으로 명명되었으며 8세기 통치자 리우트프란트 하에서 정점에 도달했습니다. 774년 왕국은 프랑크 왕 샤를마뉴에게 정복되어 그의 제국에 통합되었습니다. 그러나 롬바르드 귀족들은 11세기 노르만인들에게 정복되어 시칠리아 백작령에 추가될 때까지 이탈리아 반도 일부를 계속 통치했습니다. 그들의 유산은 지역 이름인 롬바르디아에서 분명하게 드러납니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_GHAZNI', 				'가즈니' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_GHAZNI_ADJ', 				'준빌의' UNION ALL
SELECT 'TXT_KEY_CIV5_GHAZNI_TEXT', 					'준빌 왕조는 현재 아프가니스탄 남부의 자불리스탄 지역을 통치했던 왕조로 서기 7세기에서 9세기까지 번성했습니다. 준빌은 사원에서 숭배되는 태양신인 주신 준의 이름을 따서 명명되었으며, 힌두교, 불교, 지역 정령 숭배의 영향을 포함한 이 지역의 혼합적인 이슬람 이전 종교 전통을 반영합니다. 왕조는 사산 제국, 아랍 칼리프조, 카불 샤히와 같은 이웃 강대국의 정치적 압력을 헤쳐나가면서 반독립적인 통제권을 행사했습니다. 준빌은 요새화된 도시와 인도 아대륙과 중앙아시아를 연결하는 무역로 네트워크를 유지하여 지역 상업과 문화 교류에 기여했습니다. 그들의 통치는 9세기 이슬람의 확장으로 점차 끝났지만 그들의 유산은 아프가니스탄 남부의 역사적, 종교적 기억 속에 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_UJJAIN', 				'카나우지' UNION ALL  -- Ujjain
SELECT 'TXT_KEY_CITYSTATE_UJJAIN_ADJ', 				'구르자라-프라티하라의' UNION ALL
SELECT 'TXT_KEY_CIV5_UJJAIN_TEXT', 					'구르자라-프라티하라 왕조는 서기 8세기에서 11세기까지 인도 북부와 서부 대부분을 통치했던 저명한 인도 왕조로, 아랍의 침략에 저항하고 정치적 안정과 문화적 성장의 시기를 조성한 역할로 알려져 있습니다. 현대 라자스탄과 구자라트 지역에서 기원한 프라티하라는 카나우지에 수도를 세웠으며, 이곳은 행정, 무역, 예술의 주요 중심지가 되었습니다. 왕조는 나가바타 2세와 미히라 보자와 같은 통치자 하에서 정점에 도달하여 영토를 확장하고 힌두 사원과 학문을 후원하여 초기 중세 인도 문화의 번영에 기여했습니다. 구르자라-프라티하라는 또한 인도 북부의 통제권을 놓고 벵골의 팔라 왕조 및 데칸의 라슈트라쿠타 왕조와의 삼국 투쟁에서 중요했습니다. 내부 분열과 외부 침략으로 인한 11세기의 쇠퇴는 지역 왕국의 부상을 위한 길을 열었지만 그들의 유산은 건축, 비문, 인도 북부 정치적 정체성의 통합에 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_SUSA', 				'수사' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_SUSA_ADJ', 				'엘람의' UNION ALL
SELECT 'TXT_KEY_CIV5_SUSA_TEXT', 					'엘람은 현대 이란의 서쪽 끝과 남서쪽을 중심으로 한 고대 문명으로, 현재의 후제스탄과 일람주 저지대뿐만 아니라 이라크 남부의 작은 부분까지 뻗어 있었습니다. 현대 이름 엘람은 수메르어 음역 elam(a)와 나중의 아카드어 elamtu, 엘람어 haltamti에서 유래했습니다. 엘람 국가는 고대 근동의 주요 정치 세력 중 하나였습니다. 고전 문학에서 엘람은 수도 수사에서 유래한 이름인 수시아나로도 알려졌습니다. 엘람은 금석병용기 시대 초기 도시화의 일부였습니다. 기원전 3000년경 문자 기록의 출현은 약간 더 이른 기록이 발견된 수메르 역사와도 평행을 이룹니다. 구 엘람 시대(중기 청동기 시대)에 엘람은 안샨을 중심으로 한 이란 고원의 왕국들로 구성되었으며, 기원전 2천 년 중반부터는 후제스탄 저지대의 수사를 중심으로 했습니다. 그 문화는 엘람을 계승한 페르시아 아케메네스 왕조 동안 중요한 역할을 했으며, 당시 엘람어는 공식적으로 사용되는 언어 중 하나로 남아 있었습니다. 엘람어는 일반적으로 다른 언어와 관련이 없는 고립어로 간주됩니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BOINNE', 				'브루 나 보인' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_BOINNE_ADJ', 				'보인의' UNION ALL
SELECT 'TXT_KEY_CIV5_BOINNE_TEXT', 					'브루 나 보인("보인의 궁전" 또는 더 정확하게는 "보인 계곡") 또는 보인 계곡 무덤은 아일랜드 미스주 보인강 굽이에 위치한 지역입니다. 이곳에는 노스, 뉴그레인지, 다우스의 대형 거석 통로 무덤과 약 90개의 추가 기념물을 포함하여 신석기 시대의 세계에서 가장 중요한 선사 시대 풍경 중 하나가 있습니다. 이 유적지와 관련된 고고학적 문화를 "보인 문화"라고 합니다. 1993년부터 이 유적지는 유네스코가 지정한 세계문화유산이 되었으며 2013년부터 "브루 나 보인 - 보인 굽이의 고고학적 앙상블"로 알려져 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_BUKHARA', 			'부하라' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_BUKHARA_ADJ', 			'부하라의' UNION ALL
SELECT 'TXT_KEY_CIV5_BUKHARA_TEXT', 				'샤이반 왕조 또는 시반 왕조(또는 더 정확하게는 아불 하이르-시반 왕조)는 15세기에 현대 카자흐스탄 대부분, 우즈베키스탄 대부분, 러시아 남부 일부(시베리아 포함)를 통치했던 중앙아시아의 페르시아화된 튀르크-몽골 왕조였습니다. 그들은 주치의 다섯 번째 아들이자 칭기즈 칸의 손자인 시반의 부계 후손이었습니다. 14세기 중반까지 그들은 오즈 베그 칸과 같은 시반의 형제 바투 칸과 오르다 칸의 후손들의 권위를 인정했습니다. 샤이반 왕조는 원래 우랄 산맥 남동쪽의 회색 호르드(우즈베크인의 이름을 따서 우즈베크라고도 함)를 이끌었고 1282년에 이슬람으로 개종했습니다. 전성기에 칸국은 현대 아프가니스탄 일부와 중앙아시아의 다른 지역을 포함했습니다.[NEWLINE][NEWLINE]샤이반 왕조가 통치한 또 다른 국가는 시비르 칸국으로 1563년에 왕위를 차지했습니다. 마지막 칸인 쿠춤은 1598년 러시아인들에 의해 폐위되었습니다. 그는 부하라로 탈출했지만 그의 아들과 손자들은 차르에 의해 모스크바로 끌려갔고 결국 시비르스키라는 성을 갖게 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MUARO_JAMBI', 		'무아로 잠비' UNION ALL 
SELECT 'TXT_KEY_CITYSTATE_MUARO_JAMBI_ADJ', 		'스리비자야의' UNION ALL
SELECT 'TXT_KEY_CIV5_MUARO_JAMBI_TEXT', 			'무아로 잠비는 인도네시아 수마트라섬 잠비주에 위치한 고대 고고학 유적지입니다. 서기 7세기에서 13세기 사이에 번성했던 것으로 여겨지며, 이 기간 동안 해양 동남아시아를 지배했던 불교 스리비자야 제국의 주요 중심지였습니다. 바탕 하리강을 따라 약 12제곱킬로미터의 면적을 차지하는 무아로 잠비는 벽돌 사원(찬디), 해자, 운하, 거주 지역을 포함하여 확인된 구조물이 82개 이상 있습니다. 이곳은 무역, 문화, 교육의 허브 역할을 했으며 지역 전역, 특히 인도와 중국의 학자와 순례자들을 끌어들였습니다. 이 유적지는 강력한 대승 불교의 영향을 반영하며 동남아시아 전역에 불교를 전파하는 데 역할을 한 것으로 여겨집니다. [NEWLINE][NEWLINE]무아로 잠비의 쇠퇴는 스리비자야 제국의 몰락과 자바 마자파힛 왕국과 같은 다른 정치 세력의 부상과 관련이 있는 것으로 생각됩니다. 시간이 지남에 따라 이 유적지는 버려지고 20세기 초 재발견될 때까지 울창한 정글로 뒤덮여 잊혀졌습니다. 오늘날 무아로 잠비는 인도네시아에서 가장 중요한 고고학 유적지 중 하나로 인정받고 있으며 이 지역의 고대 역사와 해양 네트워크에 대한 귀중한 통찰력을 제공합니다. 스리비자야 시대의 문화적, 경제적 성취에 대한 증거로 서 있는 폐허를 보존하고 연구하려는 노력이 진행 중입니다.' UNION ALL
