SELECT 'TXT_KEY_CIV5_SAGALA_TEXT', 					'인도-그리스인은 알렉산더 대왕 제국의 분열 이후 기원전 2세기와 서기 1세기 초 사이에 현재의 아프가니스탄, 파키스탄, 인도 북서부 일부에 왕국을 세운 헬레니즘 통치자들의 연속이었습니다. 그리스-박트리아 왕국에서 유래한 그들은 데메트리오스 1세와 메난드로스 1세(밀린다)와 같은 왕들 하에서 인도 아대륙으로 통제권을 확장했으며, 후자는 밀린다팡하에 기록된 불교 현자 나가세나와의 대화로 유명합니다. 인도-그리스인은 그리스와 인도의 문화, 종교, 예술적 전통을 혼합한 것으로 유명합니다. 이는 이중 언어 주화와 그리스 사실주의의 영향을 받은 초기 불상 표현에서 볼 수 있습니다. 그들의 통치는 헬레니즘 예술과 사상이 남아시아로 확산되는 것을 촉진했으며 간다라에서 그리스-불교 문화의 후기 발전에 기여했습니다. 결국 인도-스키타이와 쿠샨 세력에 흡수되었지만 인도-그리스인은 동서양 문화 융합의 지속적인 유산을 남겼습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_QARNAWU', 			'카르나우' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_QARNAWU_ADJ', 			'미네아의' UNION ALL
SELECT 'TXT_KEY_CIV5_QARNAWU_TEXT', 				'미네아인이라고도 알려진 마인은 현재 예멘 북부에서 기원전 8세기와 2세기 사이에 번성했던 고대 남아라비아 민족이었습니다. 수도 카르나우(현대 마인)를 중심으로 그들은 고대 아라비아에서 가장 초기이자 가장 번영한 왕국 중 하나를 세웠으며 아라비아 남부와 지중해 및 메소포타미아를 연결하는 향료 경로를 따라 무역으로 번성했습니다. 마인은 주요 대상 도시를 통제하고 사바 및 카타반과 같은 이웃 왕국과 동맹을 맺어 유향, 몰약, 향신료 수출을 촉진했습니다. 그들의 사회는 군주보다는 강력한 상인 가족과 의회를 중심으로 조직되어 이 지역의 독특한 통치 형태를 반영했습니다. 사바 왕국과 나중에 힘야르 왕국의 부상으로 영향력이 줄어들었지만 마인은 아라비아 무역, 언어, 문명의 초기 발전을 조명하는 풍부한 비문과 고고학적 유적을 남겼습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_FITIUTA', 			'피티우타' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_FITIUTA_ADJ', 			'투이 마누아의' UNION ALL
SELECT 'TXT_KEY_CIV5_FITIUTA_TEXT', 				'투이 마누아는 현재 아메리칸 사모아의 일부인 마누아 제도의 주권 통치자의 칭호였으며 폴리네시아에서 가장 오래된 것으로 알려진 추장 왕조 중 하나를 나타냅니다. 구전 전통과 계보에 따르면 투이 마누아 혈통은 2,000년 이상 거슬러 올라가며 고대 사모아와 더 넓은 폴리네시아 세계에서 가장 신성하고 권위 있는 칭호 중 하나로 간주되었습니다. 투이 마누아는 정치 지도자이자 신성한 인물로 여겨졌으며 사모아 군도 전역과 아마도 이웃 섬 그룹까지 영향력을 행사했습니다. 왕국은 19세기까지 자치권을 유지했으며, 마지막으로 인정받은 군주인 투이 마누아 엘리사라는 1909년까지 통치하다가 아메리칸 사모아를 설립한 양도 증서에 따라 공식적으로 미국 권위를 받아들였습니다. 오늘날 투이 마누아의 유산은 사모아 유산의 중요한 부분으로 남아 있으며 원주민 거버넌스, 영적 권위, 문화적 연속성을 상징합니다.' UNION ALL
