SELECT 'TXT_KEY_CITYSTATE_ETENHIRITIPA_ADJ', 		'샤반테의' UNION ALL
SELECT 'TXT_KEY_CIV5_ETENHIRITIPA_TEXT', 			'샤반테족은 브라질 중부의 원주민으로 주로 마투그로소의 세라도 지역에 거주합니다. 전통적으로 반유목 수렵 채집인이자 농부인 그들은 강력한 전사 문화, 정교한 입문 의식, 독특한 바디 페인팅 및 장식으로 유명합니다. 샤반테족은 역사적으로 더 동쪽 지역에 거주했지만 18세기와 19세기에 식민지 확장으로 인해 서쪽으로 이주했습니다. 20세기 중반에 그들은 정부의 "평화" 캠페인을 통해 비원주민 사회와 강제 접촉을 경험했으며, 이는 질병과 토지 상실을 가져왔지만 일부 영토를 인정받기도 했습니다. 오늘날 그들은 삼림 벌채, 농업 기업, 환경 압력으로 인한 지속적인 도전에 직면하면서 토지 권리와 자치권을 방어하기 위해 전통적인 관행과 정치적 행동주의를 혼합하여 활기찬 문화적 정체성을 유지하고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANGOLA', 			'망올라' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANGOLA_ADJ', 			'하자의' UNION ALL
SELECT 'TXT_KEY_CIV5_MANGOLA_TEXT', 				'하자베라고도 알려진 하자족은 탄자니아 북부의 에야시 호수 주변에 사는 원주민 수렵 채집인으로, 전통적인 채집 생활 방식을 유지하는 세계에서 마지막으로 남은 그룹 중 하나로 간주됩니다. 동아프리카 지구대에서의 그들의 조상은 수만 년 전으로 거슬러 올라가 가장 초기 인류 집단 중 일부와 연결될 가능성이 높습니다. 하자족은 작고 이동 가능한 무리로 살며 농업, 목축 또는 영구 주거지 없이 야생 식량(덩이줄기, 열매, 꿀, 사냥감 등)에 의존합니다. 그들의 평등주의적 사회 구조는 공유, 협력, 자율성을 강조하며 집단적으로 결정을 내리고 위계질서가 거의 없습니다. 토지 침해, 보존 구역, 현대화의 압력에도 불구하고 하자족은 완전한 동화에 저항해 왔으며 자연의 리듬과 밀접하게 연결된 삶의 방식을 계속 구현하고 있습니다. 오늘날 그들은 인류 기원을 이해하는 데 있어 깊은 인류학적 중요성과 조상의 땅과 문화적 자율성을 보호하기 위한 지속적인 투쟁으로 인정받고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MELGITAT', 			'멜기타트' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MELGITAT_ADJ', 			'베오투크의' UNION ALL
SELECT 'TXT_KEY_CIV5_MELGITAT_TEXT', 				'베오투크족은 캐나다 뉴펀들랜드의 원주민으로 유럽인과 접촉하기 전 수천 년 동안 섬에 살았으며 섬의 해안 및 숲 환경에서 낚시, 사냥, 채집에 의존하여 생계를 유지했습니다. 몸, 도구, 주거지를 칠하기 위해 붉은 황토를 독특하게 사용하는 것으로 알려진("사람들"을 의미하는 그들의 이름이 유래됨) 베오투크족은 16세기 이후 도착한 유럽 정착민 및 어부들과의 직접적인 접촉을 피하면서 대체로 자급자족하고 고립된 존재를 유지했습니다. 식민지 확장, 자원 경쟁, 유입된 질병이 확산됨에 따라 베오투크족은 점차 땅에서 쫓겨나고 필수 식량 자원에 대한 접근을 박탈당했습니다. 19세기 초까지 그들의 인구는 심각하게 줄어들었고 1829년 샤나우디티트의 죽음으로 베오투크족은 별개의 민족으로서 멸종된 것으로 선언되었습니다. 그러나 그들의 기억은 문화적 상실과 북미 식민지화의 지속적인 영향에 대한 가슴 아픈 상징으로 남아 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KOTA_BATU', 			'코타 바투' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_KOTA_BATU_ADJ', 			'브루나이의' UNION ALL
SELECT 'TXT_KEY_CIV5_KOTA_BATU_TEXT', 				'브루나이 제국은 현재의 브루나이 다루살람을 중심으로 14세기부터 17세기까지 번성했던 강력한 해양 술탄국이었습니다. 그 부상은 이 지역을 이슬람으로 개종시킨 초기 무슬림 통치자들 하에서 시작되어 보르네오 북부 해안을 따라 권력을 공고히 했습니다. 15세기 후반과 16세기 초 볼키아 이브니 술라이만 술탄의 통치 기간 동안 전성기를 누렸던 제국은 보르네오의 대부분을 통제하고 술루 제도와 현재 필리핀 일부까지 영향력을 확장했습니다. 향신료, 장뇌 및 기타 지역 상품 무역으로 번성하여 동남아시아를 더 넓은 무슬림 및 중국 무역 세계와 연결했습니다. 제국은 17세기에 내부 갈등, 계승 분쟁, 유럽 식민지 확장, 라이벌 세력의 부상으로 쇠퇴하기 시작했습니다. 19세기까지 영토의 대부분을 잃었지만 술탄국은 지속되어 결국 현대 브루나이 국가가 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PIR_E_SABZ', 			'피르에 사브즈' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_PIR_E_SABZ_ADJ', 			'사산의' UNION ALL
SELECT 'TXT_KEY_CIV5_PIR_E_SABZ_TEXT', 				'피르에 사브즈는 이란 야즈드주에 있는 마을입니다. 이 마을은 이란 중부 사막의 우뚝 솟은 절벽 아래에 자리 잡은 "피르"(조로아스터교 순례지)로 구성되어 있습니다. 이곳은 이전에 이란 국가의 다수이자 공식 종교였던 조로아스터교의 산악 성지 중 가장 신성한 곳입니다. 매년 6월 14일부터 18일까지 이란과 인도를 비롯한 여러 나라에서 수천 명의 조로아스터교 신자들이 이곳의 불의 사원으로 모여듭니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANGAZEYA', 			'망가제야' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_MANGAZEYA_ADJ', 			'망가제야의' UNION ALL
SELECT 'TXT_KEY_CIV5_MANGAZEYA_TEXT', 				'망가제야는 1601년 북극권 근처 시베리아 북서부의 타즈강에 세워진 번영하는 러시아 무역 도시였습니다. 이곳은 러시아의 동진 확장 기간 동안 핵심 전초 기지 역할을 했으며 수익성 있는 상아(바다코끼리 엄니)와 모피 무역, 특히 담비의 허브 역할을 하여 러시아 전역의 상인들을 끌어들였습니다. 종종 "북쪽의 황금 도시"라고 불리는 망가제야는 유럽 러시아와 시베리아를 연결하는 북부 강 경로의 전략적 위치 덕분에 빠르게 성장했습니다. 그러나 그 번영은 또한 원치 않는 외국의 관심, 특히 유럽 열강의 관심을 끌었고, 이는 모스크바를 걱정하게 했습니다. 이에 대응하여 정부는 결국 1619년 북부 해로를 폐쇄하고 도시 접근을 제한했습니다. 1642년의 파괴적인 화재와 무역로의 변화로 쇠퇴했고 17세기 후반에는 버려졌습니다. 오늘날 망가제야는 주로 고고학적 유적과 이전의 부에 대한 전설을 통해 살아남았습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_STANDING_ROCK', 		'스탠딩 록' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_STANDING_ROCK_ADJ', 			'수족의' UNION ALL
SELECT 'TXT_KEY_CIV5_STANDING_ROCK_TEXT', 				'수족은 북미의 아메리카 원주민으로 전통적으로 오세티 사코윈, 즉 대 수족 국가 또는 "일곱 불 의회"에 속합니다. 그들은 방언과 문화를 기준으로 산티, 양크톤-양크토나이, 라코타의 세 가지 주요 분파로 나눌 수 있습니다. 미네소타에서 서쪽으로 점차 이주하면서 수족은 원래 스페인 사람들이 아메리카 대륙으로 가져온 말을 이용하여 평원의 유목민이 되었습니다. 그들은 버팔로 사냥에 의존했고 사람들이 이주해야 할 때 빠르게 분해하여 포장할 수 있고 새로운 지역에 정착할 때 빠르게 재건할 수 있는 티피에 살면서 평원 전역에서 뛰어난 이동성을 허용했습니다. 그들은 17세기에 유럽인들과 처음 접촉했으며, 이는 유럽 정착민들이 수족 땅으로 계속 서쪽으로 밀고 들어오면서 일련의 갈등을 시작하게 했고, 1874년 블랙힐스에서 금이 발견되고 그에 따른 1876년 대 수족 전쟁으로 정점에 달했습니다. 세 번의 주요 전쟁과 수많은 다른 접전 끝에 1890년 12월 운디드 니 전투는 미군에 의해 약 300명의 라코타 남성, 여성, 어린이가 학살되면서 수족 저항의 끝을 알렸습니다. 오늘날 수족의 대다수는 사우스다코타 남서부의 2,782제곱마일 파인 리지 보호구역에 살고 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LANTAU', 				'란타우' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_LANTAU_ADJ', 				'란타우의' UNION ALL
SELECT 'TXT_KEY_CIV5_LANTAU_TEXT', 					'란타우섬은 홍콩에서 가장 큰 섬으로, 주강 삼각주 어귀에 위치하여 어업 중심지이자 중국 남부로 향하는 해상 관문으로서 오랫동안 전략적으로 중요한 위치를 차지해 왔습니다. 19세기 초, 이곳은 역사상 가장 강력한 해적 함대 중 하나를 지휘했던 악명 높은 해적 여왕 청석(青石)의 본거지였습니다. 전성기에는 400척의 함선과 4만 명이 넘는 해적들로 구성된 홍기방(洪業宗)을 이끌었던 청석은 란타우섬, 완산 군도, 레이저우 반도 주변 해역을 포함한 남중국해 대부분을 장악했습니다. 그녀의 지배력은 지역 무역을 교란시키고 청나라 해군과 서구 열강 모두에게 위협이 되었습니다. 마침내 1810년, 그녀는 청나라 정부와 전례 없는 사면을 협상하여 재산과 자유를 모두 지킨 채 은퇴했습니다. 오늘날 란타우 섬은 천혜의 자연 경관, 톈탄 불상과 같은 문화적 명소, 그리고 홍콩 국제공항과 디즈니랜드가 있는 현대적인 중심지로 변모한 모습으로 더욱 잘 알려져 있습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CO_LOA', 				'꼬로아' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_CO_LOA_ADJ', 				'베트남의' UNION ALL
SELECT 'TXT_KEY_CIV5_CO_LOA_TEXT', 					'베트남 하노이 인근에 위치한 고대 성채 꼬로아는 베트남 역사상 가장 오래되고 중요한 정치·군사 중심지 중 하나로 여겨집니다. 기원전 3세기 아락 왕국의 안즈엉부엉 왕에 의해 건설된 것으로 추정되는 이 성은 나선형 토성벽과 정교한 방어 시설로 유명했습니다. 수 세기 후인 서기 1세기, 꼬로아와 주변 지역은 쭝자매의 난(40~43년) 당시 저항의 중심지가 되었습니다. 쭝딱과 쭝니는 한족의 지배에 맞서 대규모 봉기를 일으켰고, 이 봉기는 베트남의 독립을 잠시 회복시켜 주었으며, 두 자매는 외세 지배에 대한 용기와 저항의 상징으로 국가적 영웅으로 추앙받았습니다. 쭝딱은 비록 3년이라는 짧은 재위 기간이었지만 베트남 역사상 최초의 여왕이 되었습니다.' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DELHI', 				'델리' UNION ALL
SELECT 'TXT_KEY_CITYSTATE_DELHI_ADJ', 				'델리의' UNION ALL
SELECT 'TXT_KEY_CIV5_DELHI_TEXT', 					'1206년에 건립된 델리 술탄국은 1526년까지 북인도 대부분을 통치했던 일련의 이슬람 왕조로, 이슬람 통치, 건축, 문화를 도입하여 인도 역사에 변혁적인 시대를 열었습니다. 쿠트브 알딘 아이바크가 세운 맘루크(노예) 왕조를 시작으로 칼지, 투글라크, 사이이드, 로디 왕조가 이어졌습니다. 그중에서도 라지아 술탄(라지야트 알딘이라고도 함)은 델리 왕좌에 오른 최초이자 유일한 여성 군주로, 1236년부터 1240년까지 통치했습니다. 일투트미쉬 술탄의 딸인 라지아는 뛰어난 지성과 행정 능력, 그리고 진보적인 비전으로 유명했으며, 남장을 하고 직접 군대를 지휘하는 등 성별 고정관념에 도전했습니다. 뛰어난 능력에도 불구하고, 여성 군주를 인정하지 않으려는 보수적인 귀족들의 강력한 반대에 부딪혀 결국 폐위되고 죽음을 맞이했습니다.';

