UPDATE Language_ko_KR
SET Text = '카라코룸'
WHERE Tag = 'TXT_KEY_CITYSTATE_ZUUNMOD';

UPDATE Language_ko_KR
SET Text = '몽골의'
WHERE Tag = 'TXT_KEY_CITYSTATE_ZUUNMOD_ADJ';

UPDATE Language_ko_KR
SET Text = '1220년경 칭기즈 칸이 몽골 중부 오르혼 계곡에 건설한 카라코룸은 몽골 제국의 초기 확장기와 후대 칭기즈 칸의 후계자인 오고타이 칸 시대에 수도 역할을 했습니다. 주요 무역로에 전략적으로 위치한 카라코룸은 행정, 상업, 문화의 중심지로 성장하여 아시아와 유럽 전역에서 상인, 장인, 외교관들을 끌어들였습니다. 도시에는 웅장한 궁전, 다양한 종교의 사원, 그리고 제국의 광범위한 다양성과 부를 반영하는 작업장들이 자리했습니다. 그러나 13세기 후반 쿠빌라이 칸이 몽골의 수도를 칸발리크(현대의 베이징)로 옮긴 후, 카라코룸의 정치적 중요성은 감소했습니다. 1372년, 이원중 장군이 이끄는 명나라 군대가 카라코룸을 점령하여 도시에 심각한 피해를 입혔습니다. 1380년에는 명나라 군대가 다시 점령하여 도시를 완전히 파괴했습니다. 그러나 카라코룸은 16세기 초 북원 왕조의 바투몽케 다얀 칸이 이곳을 다시 수도로 삼으면서 사람이 거주하기 시작했습니다. 17세기에 이르러서는 대부분 폐허가 되었고, 그 잔해는 후에 몽골 최초의 불교 사원 중 하나인 에르덴 주 사원 건설의 기초로 사용되었습니다.'
WHERE Tag = 'TXT_KEY_CITYSTATE_ZUUNMOD_PEDIA';
